insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26623, 'cm1', 'lecture', 'Que veut dire "transmise" à propos de la légende familiale racontée par le grand-père ?', 'passée d''une génération à l''autre au fil du temps', array['inventée tout récemment par le grand-père','trouvée dans un livre à la bibliothèque','totalement oubliée par la famille']::text[], null, 26609, 'V', 'publie');
