insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26667, 'cm1', 'lecture', 'Pourquoi Louis ressent-il à la fois de l''excitation et de l''appréhension quand son flotteur s''enfonce ?', 'cette sensation est totalement nouvelle et inconnue pour lui à ce moment précis', array['il a peur que sa ligne se casse définitivement','son grand-père l''a averti d''un danger réel','il pense avoir accroché un objet dangereux']::text[], null, 26651, 'I', 'publie');
