insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26669, 'cm1', 'lecture', 'Qu''est-ce qui montre que cette sortie de pêche représente un moment très important pour Louis ?', 'il en parle avec enthousiasme à toutes les personnes croisées sur le chemin du retour', array['il oublie complètement cette expérience dès le lendemain','il ne souhaite plus jamais retourner pécher avec son grand-père','il ne dit rien à personne de cette expérience vécue']::text[], null, 26651, 'I', 'publie');
