insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26729, 'cm1', 'lecture', 'Pourquoi Julia et son frère prennent-ils soin de bien mesurer chaque planche avant de la découper ?', 'une construction précise garantit la solidité et la durabilité de la cabane finale', array['ils n''ont simplement rien d''autre à faire de leur temps libre','leur papa exige cette précision sans explication','les planches sont toutes de tailles rigoureusement identiques au départ']::text[], null, 26714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26730, 'cm1', 'lecture', 'Pourquoi Julia invite-t-elle sa famille à admirer sa cabane seulement une fois le projet totalement termine ?', 'elle souhaite présenter le résultat final abouti de ses efforts prolonges', array['elle avait simplement oublie de le faire plus tôt dans le processus','sa famille refusait de venir voir la cabane avant son achèvement','la cabane n''était pas visible avant cette dernière étape']::text[], null, 26714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26731, 'cm1', 'lecture', 'Qu''est-ce qui montre que Julia est particulièrement fière du travail accompli sur sa cabane ?', 'elle invite toute sa famille à venir l''admirer dès son achèvement', array['elle refuse de montrer sa construction à qui que ce soit','elle démonte sa cabane dès le lendemain de sa construction','elle ne souhaite plus jamais y retourner par la suite']::text[], null, 26714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26732, 'cm1', 'lecture', 'Pourquoi la cabane devient-elle rapidement un lieu particulièrement important dans la vie quotidienne de Julia ?', 'elle lui offre un espace personnel propice à la détente et au partage avec ses amies', array['ses parents l''obligent à y passer du temps chaque jour','elle n''a accès à aucun autre endroit pour jouer dans la maison','elle cherche simplement à impressionner ses voisins de quartier']::text[], null, 26714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26733, 'cm1', 'lecture', 'Que peut-on déduire de la collaboration entre Julia et son grand frère tout au long de ce projet ?', 'ils forment une équipe complémentaire et efficace pour mener à bien leur projet commun', array['ils se disputent constamment durant toute la construction','le grand frère réalise l''intégralité du travail sans l''aide de Julia','Julia ne participe finalement que très peu à ce projet']::text[], null, 26714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26734, 'cm1', 'lecture', 'Que peut-on déduire de l''importance de ce projet personnel dans le développement de Julia ?', 'il lui permet de développer sa confiance et son autonomie à travers un projet mené à terme', array['ce projet n''a eu finalement aucune influence particulière sur elle','elle regrette d''avoir consacré autant de temps à cette construction','elle préférerait désormais éviter tout projet manuel similaire']::text[], null, 26714, 'I', 'publie');
