insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26983, 'cm1', 'lecture', 'Qu''est-ce qui montre que Selma a été profondément marquée par cette expérience au jardin des papillons ?', 'elle achète un souvenir spécifique pour conserver durablement ce moment vécu', array['elle oublie totalement cette sortie dès le lendemain','elle se plaint d''un profond ennui pendant toute la visite','elle refuse catégoriquement d''en reparler par la suite']::text[], null, 26966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26984, 'cm1', 'lecture', 'Pourquoi Selma choisit-elle d''acheter une simple carte postale plutôt qu''un véritable papillon en souvenir ?', 'elle respecte la fragilité et la liberté nécessaires à ces animaux délicats', array['elle n''a simplement pas assez d''argent disponible pour autre chose','la vente de papillons vivants est totalement impossible dans ce jardin','elle préfère nettement les cartes postales aux animaux vivants en général']::text[], null, 26966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26985, 'cm1', 'lecture', 'Que peut-on déduire de l''attitude générale de Selma et de ses camarades tout au long de cette visite ?', 'ils font preuve d''une curiosité sincère et d''un grand respect envers la nature observée', array['ils se montrent globalement indifférents au spectacle qui leur est proposé','ils cherchent principalement à s''amuser sans réel intérêt éducatif','ils manifestent une peur constante face aux nombreux papillons présents']::text[], null, 26966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (26986, 'cm1', 'lecture', 'Que peut-on déduire de l''objectif pédagogique poursuivi par cette sortie scolaire de fin d''année ?', 'elle vise à sensibiliser les élèves à la biodiversité et à la fragilité du monde naturel', array['elle sert uniquement à occuper agréablement une dernière journée de classe','elle n''entretient aucun lien réel avec les apprentissages scolaires habituels','elle est organisée uniquement pour récompenser les meilleurs élèves de l''année']::text[], null, 26966, 'I', 'publie');
