insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (43005, 'cm1', 'logique', 'Emma est plus âgée que Noah. Léa est plus jeune que Noah. Qui est le plus âgé ?', 'Emma', array['Noah','Léa','Impossible à savoir']::text[], null, null, null, 'publie');
