insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17001, 'cm2', 'lecture', 'Dans quel type de lieu habitent Milo et Emma ?', 'un village entouré de collines', array['une grande ville','une île','une forêt sans maisons']::text[], null, 17000, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17002, 'cm2', 'lecture', 'Comment le papillon poursuivi par Milo est-il décrit ?', 'jaune, avec des ailes bordées de noir', array['bleu et minuscule','blanc et très rapide','rouge et immobile']::text[], null, 17000, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17003, 'cm2', 'lecture', 'Comment Emma se rend-elle compte de l''absence de Milo ?', 'en descendant pour le petit-déjeuner', array['en rentrant de l''école','en entendant un bruit dans le jardin','un voisin la prévient']::text[], null, 17000, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17004, 'cm2', 'lecture', 'Que signifie "toujours à l''affût" ?', 'attentif, prêt à saisir une occasion', array['toujours fatigué','toujours en colère','toujours endormi']::text[], null, 17000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17005, 'cm2', 'lecture', 'Que veut dire "insaisissable" en parlant du papillon ?', 'qu''on ne peut pas attraper', array['très lent','très grand','très bruyant']::text[], null, 17000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17006, 'cm2', 'lecture', 'Que signifie "un pincement au coeur" quand Milo se rend compte qu''il est perdu ?', 'une petite douleur, une tristesse soudaine', array['un grand bonheur','une envie de courir','une grande fatigue']::text[], null, 17000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17007, 'cm2', 'lecture', 'Pourquoi peut-on dire que Milo guettait la porte ouverte "depuis toujours" ?', 'il attendait cette occasion depuis longtemps', array['il vient d''arriver chez Emma','il n''aime pas sortir d''habitude','il ne remarque jamais la porte']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17008, 'cm2', 'lecture', 'Pourquoi Milo ne prête-t-il pas attention au chemin qu''il prend ?', 'il est totalement concentré sur sa poursuite du papillon', array['il connaît le chemin par coeur','Emma marche devant lui','il suit une odeur familière']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17009, 'cm2', 'lecture', 'À quoi voit-on que Milo est vraiment terrifié une fois perdu ?', 'il reste immobile de longues minutes avant même d''oser miauler', array['il rentre aussitôt tout seul','il continue de jouer normalement','il s''endort sous le buisson']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17010, 'cm2', 'lecture', 'Qu''est-ce qui montre qu''Emma et Milo sont très proches à la fin ?', 'ils décident de ne plus se quitter du regard de la journée', array['ils repartent chacun de leur côté','Milo retourne aussitôt dans le jardin','Emma le laisse seul pour se reposer']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17011, 'cm2', 'lecture', 'Que fait Milo chaque matin avant même que la famille ne soit réveillée ?', 'il s''installe devant la porte du jardin et attend', array['il dort profondément dans le salon','il réveille Emma en miaulant','il mange son repas dans la cuisine']::text[], null, 17000, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17012, 'cm2', 'lecture', 'Sur quoi Milo garde-t-il l''œil rivé en poursuivant le papillon ?', 'sur sa proie', array['sur le chemin de la maison','sur Emma qui le cherche','sur les fleurs du jardin']::text[], null, 17000, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17013, 'cm2', 'lecture', 'Que décident Milo et Emma à la toute fin de l''histoire ?', 'de ne plus se quitter du regard de la journée', array['de repartir chercher le papillon ensemble','de rester chacun de leur côté','d''aller se coucher immédiatement']::text[], null, 17000, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17014, 'cm2', 'lecture', 'Que veut dire "distraite par mille pensées" à propos de la maman de Milo ce matin-là ?', 'préoccupée par de nombreuses idées différentes', array['totalement concentrée sur une seule tâche précise','très reposée et détendue','en colère sans raison particulière']::text[], null, 17000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17015, 'cm2', 'lecture', 'Que signifie "le chat s''arrête net" quand le papillon s''envole hors de portée ?', 'il s''arrête brusquement et complètement', array['il continue d''avancer lentement','il accélère encore sa course','il ne s''arrête jamais vraiment']::text[], null, 17000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17016, 'cm2', 'lecture', 'Que veut dire "blotti contre le tronc" à propos de Milo retrouvé par Emma ?', 'réfugié tout contre, cherchant protection et chaleur', array['installé confortablement en hauteur','en train de jouer joyeusement','en train de dormir profondément loin de là']::text[], null, 17000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17017, 'cm2', 'lecture', 'Pourquoi peut-on dire que Milo profite de l''inattention de sa maman ce matin-là ?', 'elle est distraite par ses pensées et ne referme pas bien la porte, ce que Milo remarque aussitôt', array['Milo a lui-même ouvert la porte du jardin','Emma laisse volontairement la porte ouverte pour lui','le vent a ouvert la porte durant la nuit']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17018, 'cm2', 'lecture', 'Qu''est-ce qui montre que Milo est complètement absorbé par sa poursuite du papillon ?', 'il garde l''œil rivé sur sa proie sans jamais prêter attention au chemin qu''il emprunte', array['il s''arrête régulièrement pour vérifier le chemin du retour','il abandonne rapidement cette poursuite pour rentrer','il pense sans cesse à Emma pendant qu''il court']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17019, 'cm2', 'lecture', 'Pourquoi Milo ressent-il un pincement au cœur en réalisant qu''il est perdu ?', 'il prend conscience que rien de familier ne l''entoure plus, ce qui l''inquiète profondément', array['il regrette simplement d''avoir manqué le papillon','il a faim et pense à son repas manqué','il se souvient d''un mauvais souvenir passé']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (17020, 'cm2', 'lecture', 'Que peut-on déduire de la décision finale de Milo et Emma de ne plus se quitter du regard ?', 'cette aventure a renforcé leur attachement mutuel et leur confiance réciproque', array['ils resteront désormais enfermés ensemble dans la maison','Milo ne sortira plus jamais dans le jardin à l''avenir','Emma se méfie désormais de son propre chat']::text[], null, 17000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27001, 'cm2', 'lecture', 'Où Léa passe-t-elle ses vacances d''été chaque année ?', 'dans une petite station balnéaire familiale', array['à la montagne uniquement','à la campagne chez ses grands-parents','en ville chez sa tante']::text[], null, 27000, 'L', 'publie');
