insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27006, 'cm2', 'lecture', 'Que fait Léa avant que son château ne soit englouti ?', 'elle le photographie fièrement', array['elle le détruit elle-même','elle pleure sans agir','elle demande de l''aide pour le sauver']::text[], null, 27000, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27007, 'cm2', 'lecture', 'Que veut dire "inexorablement" à propos de la remontée de la marée ?', 'de façon inévitable, sans qu''on puisse l''arrêter', array['de façon très hésitante et incertaine','de manière totalement imprévisible','de façon extrêmement lente et discrète']::text[], null, 27000, 'V', 'publie');
