insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27010, 'cm2', 'lecture', 'Que veut dire "éphémère" à propos de l''oeuvre architecturale réalisée par Léa ?', 'qui ne dure qu''un temps très court', array['qui dure indéfiniment sans jamais disparaître','qui est impossible à photographier','qui est interdite d''accès au public']::text[], null, 27000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27011, 'cm2', 'lecture', 'Que veut dire "engloutie" à propos du sort final du château de sable ?', 'recouverte et absorbée complètement par l''eau', array['transportée intacte vers un autre lieu','vendue à un autre enfant du rivage','reconstruite plus loin sur la plage']::text[], null, 27000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27012, 'cm2', 'lecture', 'Que veut dire "stratégique" à propos de l''emplacement choisi par Léa pour son château ?', 'choisi avec réflexion pour répondre à un objectif précis', array['choisi totalement au hasard sans réflexion','imposé par ses parents sans discussion','impossible à atteindre facilement']::text[], null, 27000, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27013, 'cm2', 'lecture', 'Pourquoi Léa choisit-elle un emplacement ni trop près ni trop loin du rivage ?', 'elle cherche un compromis entre facilite de construction et durée de vie du château face à la marée', array['elle suit simplement les indications de son petit frère','c''est le seul endroit encore libre sur la plage ce jour-là','ses parents lui imposent cet emplacement précis']::text[], null, 27000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27014, 'cm2', 'lecture', 'Pourquoi le petit frère de Léa participe-t-il activement au projet en transportant de l''eau ?', 'il souhaite contribuer avec enthousiasme au projet de sa grande soeur', array['sa maman l''oblige à aider Léa contre son gré','il n''a rien d''autre à faire de sa journée à la plage','Léa le menace de ne plus jouer avec lui sinon']::text[], null, 27000, 'I', 'publie');
