insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27016, 'cm2', 'lecture', 'Que peut-on déduire du caractère de Léa face à la destruction inévitable de son château par la marée ?', 'elle fait preuve de resilience et sait transformer une déception en projet futur', array['elle abandonne définitivement toute construction de châteaux de sable','elle se met durablement en colère contre les éléments naturels','elle refuse catégoriquement d''accepter que son château disparaisse']::text[], null, 27000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27017, 'cm2', 'lecture', 'Pourquoi Léa prend-elle soin de photographier son château avant sa disparition ?', 'elle souhaite conserver une trace durable de cette création temporaire', array['ses parents le lui demandent expressément pour des raisons pratiques','elle envisage de vendre cette photographie à d''autres vacanciers','elle ne reverra plus jamais cette plage de sa vie']::text[], null, 27000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27018, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Léa et son petit frère à travers ce projet commun ?', 'ils coopèrent avec plaisir sur un projet partage malgré leur différence d''âge', array['ils se disputent constamment pour la direction du projet','le petit frère se montre totalement indifférent au projet de sa soeur','Léa refuse catégoriquement toute aide venant de son frère']::text[], null, 27000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27019, 'cm2', 'lecture', 'Que peut-on déduire du plaisir que Léa retire de cette activité malgré la destruction finale et programmée du château ?', 'le plaisir du processus créatif compte davantage à ses yeux que la durée de vie de l''oeuvre', array['Léa regrette profondément d''avoir investi autant de temps dans ce projet','elle ne recommencera plus jamais ce type d''activité à l''avenir','elle est dégoûtée durablement de la plage à cause de cet épisode']::text[], null, 27000, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27020, 'cm2', 'lecture', 'Que peut-on déduire de l''attitude générale de Léa face aux contraintes naturelles rencontrées durant cette activité ?', 'elle sait s''adapter avec ingéniosité aux limites imposées par son environnement', array['elle ignore complètement les contraintes liées à la marée','elle considère la marée comme un simple obstacle à éviter définitivement','elle préfère désormais éviter toute activité liée au sable']::text[], null, 27000, 'I', 'publie');
