insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27034, 'cm2', 'lecture', 'Pourquoi Hugo est-il surpris d''apprendre l''origine réelle du lait qu''il boit chaque matin ?', 'il n''avait jamais réfléchi auparavant à la provenance concrète de cet aliment quotidien', array['il pensait sincèrement que le lait venait uniquement d''un magasin','le fermier lui à menti sur ce sujet auparavant','il n''aime pas particulièrement le goût du lait']::text[], null, 27021, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27035, 'cm2', 'lecture', 'Pourquoi le fermier laisse-t-il les enfants toucher le pis d''une vache particulièrement calme ?', 'il souhaite leur offrir une expérience concrète et rassurante avec un animal facile à approcher', array['il n''a aucune autre vache disponible ce jour-là','les enfants l''exigent avec insistance dès leur arrivée','cette vache précise est malade et doit être surveillée']::text[], null, 27021, 'I', 'publie');
