insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27038, 'cm2', 'lecture', 'Pourquoi Hugo installe-t-il son pot de graines près de la fenêtre de sa chambre en rentrant ?', 'il souhaite pouvoir suivre attentivement chaque étape de la croissance de sa plante', array['sa maman le lui impose sans lui donner d''explication','c''est le seul endroit disponible dans toute la maison','il a oublié ce pot dans un coin de sa chambre']::text[], null, 27021, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27039, 'cm2', 'lecture', 'Que peut-on déduire de l''objectif général poursuivi par cette sortie scolaire annuelle à la ferme ?', 'elle vise à faire découvrir concrètement aux élèves l''origine des aliments du quotidien', array['elle sert uniquement à occuper une journée de classe sans réel objectif','elle est organisée uniquement pour récompenser certains élèves précis','elle n''entretient aucun lien avec le programme scolaire habituel']::text[], null, 27021, 'I', 'publie');
