insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27047, 'cm2', 'lecture', 'Comment Nora se sent-elle en revenant au village le soir ?', 'épuisée mais très fière', array['totalement reposée et détendue','déçue de sa randonnée','malade et fiévreuse']::text[], null, 27042, 'L', 'publie');
