insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27053, 'cm2', 'lecture', 'Que veut dire "rapace" pour designer l''aigle observé par Nora ?', 'un oiseau chasseur qui se nourrit d''autres animaux', array['un oiseau qui ne mange que des graines','un animal qui ne vole jamais','un poisson vivant en eau douce']::text[], null, 27042, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27054, 'cm2', 'lecture', 'Que veut dire "niche" à propos du village situe au pied des sommets ?', 'installé et comme protégé dans un lieu précis', array['construit très récemment par des habitants','abandonne depuis de nombreuses années','visible depuis très loin dans la vallée']::text[], null, 27042, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27055, 'cm2', 'lecture', 'Pourquoi Nora respire-t-elle à pleins poumons dès le début de la randonnée en montagne ?', 'elle apprécie particulièrement l''air frais après la chaleur écrasante de la vallée', array['elle est déjà essoufflée par l''effort fourni','elle a peur de la hauteur atteinte','elle imite simplement le comportement de son papa']::text[], null, 27042, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27056, 'cm2', 'lecture', 'Pourquoi le papa de Nora la guide-t-il attentivement sur les passages les plus rocailleux ?', 'il souhaite l''aider à avancer en toute sécurité sur un terrain particulièrement difficile', array['Nora refuse catégoriquement d''avancer seule sur ce terrain','le sentier est officiellement interdit sans accompagnateur','il cherche simplement à ralentir le rythme de la marche']::text[], null, 27042, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27057, 'cm2', 'lecture', 'Qu''est-ce qui montre que la phase de descente s''avère difficile pour Nora ?', 'ses genoux commencent à la faire souffrir légèrement vers la fin du parcours', array['elle court tout le long du chemin sans ressentir aucune fatigué','elle demande explicitement à faire demi-tour en cours de route','elle s''arrête complètement de marcher à mi-parcours']::text[], null, 27042, 'I', 'publie');
