insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27061, 'cm2', 'lecture', 'Pourquoi Nora souhaite-t-elle déjà refaire une randonnée similaire l''année suivante ?', 'elle a retiré une grande fierté et un véritable plaisir de cette première expérience réussie', array['ses parents l''obligent à formuler cette demande explicite','elle n''a en réalité rien d''autre à proposer pour l''année suivante','elle espère simplement obtenir un nouveau téléphone en récompense']::text[], null, 27042, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27062, 'cm2', 'lecture', 'Que peut-on déduire de l''ambition exprimée par Nora de grimper encore plus haut la prochaine fois ?', 'cette première réussite nourrit chez elle une envie croissante de nouveaux défis physiques', array['elle n''a en réalité aucune envie réelle de recommencer une randonnée','elle cherche uniquement à impressionner ses cousins restes en ville','elle regrette d''avoir choisi un parcours aussi difficile cette fois-ci']::text[], null, 27042, 'I', 'publie');
