insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27151, 'cm2', 'lecture', 'Que découvre Marco à propos de sa cousine la plus âgée durant ce séjour ?', 'elle sait déjà conduire un petit tracteur', array['elle sait particulièrement bien nager','elle sait cuisiner des plats très compliques','elle sait jouer d''un instrument de musique']::text[], null, 27147, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27152, 'cm2', 'lecture', 'Que fait la famille réunie un soir autour d''un grand feu allume dans le jardin ?', 'elle grille des saucisses et raconte des histoires', array['elle regarde ensemble un film projeté','elle chante uniquement des chansons connues','elle joue simplement aux cartes']::text[], null, 27147, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27153, 'cm2', 'lecture', 'Que font les enfants durant la pluie orageuse qui les oblige à rester à l''intérieur ?', 'ils inventent un tout nouveau jeu de société', array['ils regardent la télévision durant toute la journée','ils restent chacun isole dans leur propre chambre','ils sortent quand même jouer dehors malgré la pluie']::text[], null, 27147, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27154, 'cm2', 'lecture', 'Que veut dire "habilement" à propos de la manière dont Marco se cache pendant le jeu ?', 'avec une réelle adresse et une certaine intelligence', array['de façon particulièrement maladroite','sans jamais réfléchir à son geste','beaucoup trop lentement pour réussir']::text[], null, 27147, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27155, 'cm2', 'lecture', 'Que veut dire "paisibles" à propos des vaches observées dans le pré voisin ?', 'calmes et particulièrement tranquilles', array['agitées et particulièrement bruyantes','manifestement effrayées par les enfants','visiblement malades et affaiblies']::text[], null, 27147, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27156, 'cm2', 'lecture', 'Que veut dire "anecdotes" à propos des histoires racontées par l''oncle de Marco ?', 'de petites histoires vécues et racontées à l''oral', array['des chansons traditionnelles anciennes','des recettes de cuisine familiales','des devinettes destinées aux enfants']::text[], null, 27147, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27157, 'cm2', 'lecture', 'Que veut dire "entourant" à propos du jardin immense de la maison familiale ?', 'qui se trouve tout autour de la maison', array['qui se trouve très loin de la maison','qui n''existe pas encore réellement','qui est officiellement ferme au public']::text[], null, 27147, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27158, 'cm2', 'lecture', 'Que veut dire "imaginées" à propos des règles du nouveau jeu de société invente ?', 'créées directement par l''imagination des enfants eux-mêmes', array['copiées fidèlement d''un jeu déjà existant','écrites entièrement par un adulte présent','trouvées telles quelles dans un livre']::text[], null, 27147, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27159, 'cm2', 'lecture', 'Que veut dire "élargie" à propos de la famille réunie autour du feu ce soir-là ?', 'comprenant plusieurs générations et branches familiales', array['réduite au strict minimum nécessaire','composée uniquement des parents et de Marco','totalement absente ce soir précis']::text[], null, 27147, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27160, 'cm2', 'lecture', 'Pourquoi Marco retrouve-t-il cette maison familiale avec un tel plaisir chaque été ?', 'il y vit des moments particulièrement privilégiés auprès de ses cousins qu''il apprécie beaucoup', array['ses parents l''y obligent chaque année sans exception','il n''a en réalité aucun autre endroit disponible pour ses vacances','il préfère globalement la campagne à la ville pour des raisons pratiques']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27161, 'cm2', 'lecture', 'Pourquoi Marco rêve-t-il d''apprendre lui aussi à conduire un tracteur comme sa cousine ?', 'il admire les nouvelles compétences acquises par sa cousine et souhaite les imiter à son tour', array['son oncle le lui à explicitement promis depuis très longtemps déjà','il doit impérativement conduire un tracteur pour aider à la ferme familiale','il n''apprécie particulièrement aucune des autres activités proposées durant le séjour']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27162, 'cm2', 'lecture', 'Pourquoi les enfants inventent-ils leur propre jeu de société pendant cette journée de pluie ?', 'ils s''adaptent avec créativité à l''impossibilité de sortir jouer dehors ce jour-là', array['ils ne connaissent en réalité aucun autre jeu de société existant','leurs parents le leur imposent explicitement ce jour-là','ils s''ennuient profondément de tous les autres jeux disponibles']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27163, 'cm2', 'lecture', 'Qu''est-ce qui montre que Marco éprouve une grande difficulté à quitter ses cousins à la toute fin du séjour ?', 'il a les larmes aux yeux en repartant en voiture avec ses propres parents', array['il se montre au contraire impatient de rentrer enfin chez lui','il oublie complètement de dire au revoir à ses cousins','il repart bien avant tous les autres membres de la famille']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27164, 'cm2', 'lecture', 'Que peut-on déduire de l''importance de ces vacances chez les cousins dans la vie de Marco ?', 'elles représentent un moment fort et particulièrement attendu chaque année dans sa vie', array['elles sont en réalité sans grand intérêt particulier pour lui','il préférerait globalement passer ses vacances ailleurs qu''ici','ce séjour ne change finalement rien à son quotidien habituel']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27165, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Marco et son oncle à travers les histoires racontées autour du feu ?', 'l''oncle transmet avec plaisir des éléments précieux de l''histoire familiale à la jeune génération', array['l''oncle raconte ces histoires uniquement par obligation sociale','Marco n''accorde en réalité aucun intérêt particulier à ces récits','cette tradition orale n''a aucune valeur réelle pour la famille']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27166, 'cm2', 'lecture', 'Que peut-on déduire de l''ambiance régnant entre tous les cousins durant ce séjour d''été ?', 'une grande complicité et beaucoup de joie partagée caractérisent leurs relations', array['de fréquentes disputes marquent régulièrement leurs interactions','un profond ennui général caractérise l''ensemble du séjour','une indifférence manifeste règne entre les différents enfants présents']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27167, 'cm2', 'lecture', 'Que peut-on déduire de l''évolution de Marco à travers cette semaine passée à la campagne ?', 'il découvre de nouvelles facettes de sa famille et gagne en autonomie et en curiosité', array['cette semaine n''apporte finalement aucun changement notable dans sa vie','il regrette globalement d''avoir accepté de passer cette semaine ici','il préfère désormais nettement rester enferme chez lui en ville']::text[], null, 27147, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27169, 'cm2', 'lecture', 'Pourquoi Sofia organise-t-elle ce grand pique-nique avec sa famille ?', 'pour fêter le début des vacances scolaires d''été', array['pour l''anniversaire de sa propre maman','pour marquer la rentrée des classes','sans raison particulière identifiée']::text[], null, 27168, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27170, 'cm2', 'lecture', 'Où la famille de Sofia installe-t-elle finalement son pique-nique ?', 'sous un vieux chêne, près d''une rivière', array['directement sur une plage de sable','dans un jardin public aménagé','au sommet d''une petite colline']::text[], null, 27168, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27171, 'cm2', 'lecture', 'Que font Sofia et son petit frère pendant que les adultes discutent entre eux ?', 'ils explorent les environs à la recherche d''insectes', array['ils dorment paisiblement sous l''arbre','ils aident activement à préparer le repas','ils restent assis sans bouger']::text[], null, 27168, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27172, 'cm2', 'lecture', 'Que découvrent finalement Sofia et son frère lors de leur exploration ?', 'une coccinelle rouge à sept points', array['un serpent inoffensif','un oiseau visiblement blesse','un nid d''abeilles abandonne']::text[], null, 27168, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27173, 'cm2', 'lecture', 'Que remarquent les enfants après avoir terminé leur repas en famille ?', 'un groupe de fourmis s''approchant des miettes', array['un orage menaçant qui approche','un autre groupe de pique-niqueurs voisins','rien de particulier à signaler']::text[], null, 27168, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27174, 'cm2', 'lecture', 'Que fait Sofia avant de repartir définitivement de cet endroit ?', 'elle range soigneusement les restes et les emballages', array['elle laisse simplement tout sur place','elle jette les restes directement dans la rivière','elle oublie complètement son panier sur l''herbe']::text[], null, 27168, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27175, 'cm2', 'lecture', 'Que veut dire "paisiblement" à propos de la rivière qui coule près du pique-nique ?', 'de façon calme et particulièrement tranquille', array['avec beaucoup de bruit et une grande force','en débordant largement de son lit habituel','en étant totalement gelée sur toute sa longueur']::text[], null, 27168, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27176, 'cm2', 'lecture', 'Que veut dire "ombrage" à propos de l''endroit choisi pour le pique-nique de la famille ?', 'protège efficacement du soleil par des arbres', array['expose directement en plein soleil','entièrement recouvert d''eau stagnante','très éloigne de toute végétation naturelle']::text[], null, 27168, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27177, 'cm2', 'lecture', 'Que veut dire "ballet organisé" à propos des fourmis observées attentivement par les enfants ?', 'un mouvement collectif remarquablement coordonne', array['un désordre total et particulièrement chaotique','une immobilité complète et prolongée','un combat violent entre plusieurs insectes']::text[], null, 27168, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27178, 'cm2', 'lecture', 'Que veut dire "prudemment" à propos de la manière dont les fourmis s''approchent des miettes ?', 'avec beaucoup de précaution et d''attention', array['avec une rapidité particulièrement imprudente','avec une totale indifférence visible','en groupe extrêmement bruyant et agite']::text[], null, 27168, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27179, 'cm2', 'lecture', 'Que veut dire "scrupuleusement" à propos de l''attention portée par Sofia au rangement final ?', 'avec un grand soin et une attention rigoureuse', array['en négligeant totalement cette tache précise','en refusant catégoriquement de s''en occuper','en se dépêchant sans réfléchir à rien']::text[], null, 27168, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27180, 'cm2', 'lecture', 'Que veut dire "préserve" à propos du lieu naturel visite par la famille de Sofia ?', 'protège et maintenu en bon état naturel', array['abandonne depuis de très nombreuses années','pollue et fortement dégrade au fil du temps','totalement artificiel et aménagé par l''homme']::text[], null, 27168, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27181, 'cm2', 'lecture', 'Pourquoi Sofia choisit-elle finalement de laisser repartir la coccinelle plutôt que de la garder avec elle ?', 'elle respecte profondément les petits animaux et l''équilibre naturel qui l''entoure', array['elle a en réalité peur de cette coccinelle précise','sa maman le lui interdit fermement sur le moment','la coccinelle s''échappe malgré elle sans qu''elle puisse intervenir']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27182, 'cm2', 'lecture', 'Pourquoi Sofia trouve-t-elle systématiquement que la nourriture à meilleur goût lorsqu''elle mange en plein air ?', 'le cadre naturel et l''ambiance conviviale du pique-nique rendent le repas plus agréable', array['la nourriture est objectivement meilleure une fois préparée à l''extérieur','elle a simplement très faim ce jour précis','elle compare inconsciemment avec un repas rate la veille au soir']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27183, 'cm2', 'lecture', 'Pourquoi Sofia veille-t-elle si scrupuleusement à ne laisser aucune trace de leur passage sur ce lieu ?', 'elle respecte sincèrement la nature et l''environnement naturel qui l''entoure', array['elle a simplement peur de recevoir une amende officielle','sa maman la surveille de très près à cet instant précis','elle souhaite pouvoir revenir sans que personne ne remarque leur passage']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27184, 'cm2', 'lecture', 'Qu''est-ce qui montre que Sofia est particulièrement curieuse et attentive à la nature qui l''entoure ?', 'elle observe attentivement la coccinelle et explique ensuite le comportement des fourmis à son frère', array['elle s''ennuie manifestement pendant toute la durée de la sortie','elle préfère nettement rester assise sur la nappe sans bouger','elle manifeste une peur évidente face à tous les insectes rencontres']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27185, 'cm2', 'lecture', 'Que peut-on déduire de la préparation minutieuse de ce pique-nique par Sofia et sa maman ?', 'elles ont organisé cette sortie avec un véritable soin et une anticipation certaine', array['elles ont improvisé ce pique-nique au tout dernier moment possible','Sofia n''a en réalité pas du tout participe à cette préparation','c''est la toute première fois qu''elles organisent ce type de sortie']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27186, 'cm2', 'lecture', 'Que peut-on déduire du plaisir manifeste de Sofia à observer les insectes plutôt que de simplement jouer avec son frère ?', 'elle porte un intérêt sincère et durable à la découverte du monde naturel', array['elle s''ennuie profondément et n''a rien d''autre à faire ce jour-là','son petit frère l''oblige explicitement à s''intéresser aux insectes','elle préfère en réalité nettement rester avec les adultes présents']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27187, 'cm2', 'lecture', 'Pourquoi Sofia prend-elle le temps d''expliquer à son petit frère le fonctionnement collectif des fourmis ?', 'elle souhaite partager avec lui ses propres connaissances et nourrir sa curiosité naturelle', array['son frère l''interroge avec une insistance particulière sur ce sujet précis','sa maman lui demande explicitement de faire cette explication','elle cherche simplement à impressionner les autres membres de sa famille']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27188, 'cm2', 'lecture', 'Que peut-on déduire de l''attitude générale de Sofia envers la nature à travers l''ensemble de cette journée ?', 'elle développe un rapport respectueux et curieux envers le monde naturel qui l''entoure', array['elle considère la nature comme un simple décor sans grande importance','elle préfère finalement nettement les activités organisées en intérieur','elle n''accorde aucune attention particulière aux éléments naturels rencontres']::text[], null, 27168, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27190, 'cm2', 'lecture', 'Où Elias passe-t-il précisément sa journée avec son papa ?', 'sur la plage', array['en haute montagne','dans un grand parc urbain','à la piscine municipale']::text[], null, 27189, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27191, 'cm2', 'lecture', 'D''ou provient exactement le cerf-volant utilisé par Elias ce jour-là ?', 'c''est un cadeau reçu à son dernier anniversaire', array['il l''a acheté lui-même avec son propre argent','il l''a entièrement fabriqué avec son papa','il l''a simplement emprunté à un ami proche']::text[], null, 27189, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27192, 'cm2', 'lecture', 'Que doit faire Elias selon les conseils précis donnés par son papa ?', 'courir face au vent en tenant fermement le fil', array['attendre patiemment que le vent tombe complètement','lancer directement le cerf-volant très haut dans les airs','s''asseoir tranquillement et attendre sans bouger']::text[], null, 27189, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27193, 'cm2', 'lecture', 'Que font d''autres enfants présents en voyant voler le cerf-volant d''Elias ?', 'ils s''approchent, visiblement curieux', array['ils se moquent ouvertement de lui','ils l''ignorent totalement sans réagir','ils partent immédiatement en courant']::text[], null, 27189, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27194, 'cm2', 'lecture', 'Que se passe-t-il précisément vers la fin de cette après-midi sur la plage ?', 'une rafale manque de faire tomber le cerf-volant dans l''eau', array['le vent s''arrête complètement et brutalement','Elias perd définitivement le fil de son cerf-volant','il commence soudainement à pleuvoir très fort']::text[], null, 27189, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27195, 'cm2', 'lecture', 'Que fait Elias en rentrant chez lui ce soir-là ?', 'il range précieusement son cerf-volant', array['il le jette car il est désormais casse','il le laisse simplement sur la plage','il le donne directement à un autre enfant']::text[], null, 27189, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27196, 'cm2', 'lecture', 'Que veut dire "infructueuses" à propos des premières tentatives d''Elias sur la plage ?', 'qui n''aboutissent finalement à aucun résultat positif', array['qui réussissent parfaitement dès le tout premier coup','qui sont formellement interdites par son papa','qui font particulièrement peur à Elias']::text[], null, 27189, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27197, 'cm2', 'lecture', 'Que veut dire "traction" à propos de la sensation ressentie par Elias dans sa main ?', 'une force qui tire fermement dans une direction précise', array['une absence totale de toute sensation','une douleur soudaine et particulièrement vive','une chaleur intense ressentie subitement']::text[], null, 27189, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27198, 'cm2', 'lecture', 'Que veut dire "scintillantes" à propos des vagues observées par Elias durant le vol ?', 'qui brillent par de multiples reflets de lumière', array['totalement sombres et particulièrement ternes','parfaitement immobiles et plates','recouvertes uniquement d''écume blanche']::text[], null, 27189, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27199, 'cm2', 'lecture', 'Que veut dire "rafale" à propos du vent qui manque de faire tomber le cerf-volant ?', 'un souffle de vent soudain et nettement plus fort', array['une absence totale et prolongée de vent','une fine pluie particulièrement légère','un changement brutal de température']::text[], null, 27189, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27200, 'cm2', 'lecture', 'Que veut dire "stabiliser" à propos du geste effectue par Elias avec le fil de son cerf-volant ?', 'rendre plus stable et parfaitement équilibre', array['laisser tomber complètement sans réagir','faire monter encore plus haut dans le ciel','faire descendre très rapidement vers le sol']::text[], null, 27189, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27201, 'cm2', 'lecture', 'Que veut dire "précieusement" à propos de la manière dont Elias range son cerf-volant le soir ?', 'avec beaucoup de soin, car l''objet compte véritablement pour lui', array['sans aucune attention particulière portée au geste','en le pliant n''importe comment et rapidement','en le cachant volontairement de tous les regards']::text[], null, 27189, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27202, 'cm2', 'lecture', 'Pourquoi Elias doit-il courir face au vent pour faire voler correctement son cerf-volant ?', 'cela crée la force nécessaire permettant au cerf-volant de prendre son envol', array['c''est simplement un jeu proposé par son papa sans raison particulière','il doit impérativement s''échauffer avant de commencer à jouer','le sable est bien trop chaud pour rester immobile longtemps']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27203, 'cm2', 'lecture', 'Pourquoi Elias n''arrive-t-il absolument pas à détacher son regard du cerf-volant une fois en vol ?', 'le spectacle du cerf-volant évoluant dans le ciel le fascine profondément', array['il a peur de le perdre complètement de vue et de l''abîmer','son papa le lui demande sans arrêt durant tout le vol','il cherche activement à compter les oiseaux présents autour de lui']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27204, 'cm2', 'lecture', 'Pourquoi certains enfants demandent-ils précisément des conseils techniques à Elias sur la plage ?', 'ils sont impressionnés par sa réussite et souhaitent apprendre à leur tour', array['ils veulent en réalité simplement lui prendre son cerf-volant','leurs propres parents les y obligent explicitement','ils ne savent tout simplement pas où se trouve exactement la plage']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27205, 'cm2', 'lecture', 'Qu''est-ce qui montre qu''Elias réagit particulièrement bien face à un imprévu survenant avec son cerf-volant ?', 'il tire rapidement et efficacement sur le fil pour stabiliser l''engin et éviter la chute', array['il abandonne immédiatement des la première difficulté rencontrée','il laisse le cerf-volant tomber dans l''eau sans réagir du tout','il appelle systématiquement son papa pour qu''il s''en occupe entièrement']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27206, 'cm2', 'lecture', 'Que peut-on déduire du plaisir général ressenti par Elias tout au long de cette journée sur la plage ?', 'il vit une expérience particulièrement marquante malgré les difficultés initiales rencontrées', array['il regrette globalement d''avoir reçu ce cerf-volant en cadeau','il préfère finalement largement les autres activités proposées à la plage','il ne recommencera certainement plus jamais cette activité précise']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27207, 'cm2', 'lecture', 'Pourquoi Elias explique-t-il fièrement aux autres enfants les gestes techniques nécessaires au vol du cerf-volant ?', 'il est fier de sa propre réussite et souhaite sincèrement partager son savoir-faire nouveau', array['son papa l''oblige explicitement à partager ces informations précises','il cherche uniquement à impressionner les autres enfants présents','il n''a en réalité rien d''autre à faire durant cette après-midi']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27208, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Elias et son papa à travers cette expérience partagée sur la plage ?', 'son papa l''accompagne avec patience et bienveillance dans cette nouvelle expérience', array['son papa reste totalement indifférent aux efforts fournis par son fils','il fait en réalité tout le travail à la place d''Elias','il se moque ouvertement des échecs initiaux de son fils']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27209, 'cm2', 'lecture', 'Que peut-on déduire globalement de cette expérience du cerf-volant dans le développement personnel d''Elias ?', 'elle renforce sa confiance en lui et sa capacité à persister face aux difficultés', array['elle n''a finalement aucun effet particulier sur sa confiance personnelle','elle le décourage durablement de toute activité similaire future','elle ne représente en définitive qu''un simple moment sans conséquence']::text[], null, 27189, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27211, 'cm2', 'lecture', 'Avec qui Greta va-t-elle cueillir des champignons ce samedi matin ?', 'son papi', array['sa mamie uniquement','toute sa classe scolaire','elle y va entièrement seule']::text[], null, 27210, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27212, 'cm2', 'lecture', 'Que rappelle précisément papi avant de commencer cette cueillette en forêt ?', 'les règles essentielles de sécurité', array['l''heure exacte du déjeuner','le chemin précis du retour','la liste complète des espèces rares']::text[], null, 27210, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27213, 'cm2', 'lecture', 'Quelle est exactement la toute première découverte de Greta durant cette sortie ?', 'un cèpe brun', array['une girolle jaune','un champignon rouge dangereux','rien du tout au tout début']::text[], null, 27210, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27214, 'cm2', 'lecture', 'Que remarque Greta à propos des girolles trouvées un peu plus loin dans la forêt ?', 'elles sont disposées en cercle autour d''un arbre', array['elles sont toutes cachées sous des feuilles mortes','elles sont directement accrochées aux branches','il n''y en à en réalité qu''une seule']::text[], null, 27210, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27215, 'cm2', 'lecture', 'Que fait papi en apercevant le champignon rouge tacheté de blanc ?', 'il prévient immédiatement Greta de ne pas le toucher', array['il le ramasse aussitôt sans hésitation','il le fait goûter directement à Greta','il l''ignore totalement sans réagir']::text[], null, 27210, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27216, 'cm2', 'lecture', 'Que préparent ensemble Greta et sa mamie à leur retour à la maison ?', 'une omelette aux champignons', array['une simple soupe de légumes','une tarte aux fruits de saison','rien de particulier ce jour-là']::text[], null, 27210, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27217, 'cm2', 'lecture', 'Que veut dire "tapisse" à propos du sol de la forêt parcourue par Greta ?', 'recouvert entièrement sur toute sa surface', array['totalement nu et complètement vide','creuse profondément par endroits','gelé et particulièrement dur']::text[], null, 27210, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27218, 'cm2', 'lecture', 'Que veut dire "caractéristiques" à propos des formes rondes recherchées activement par Greta ?', 'propres et particulières à une espèce précise', array['totalement rares et absolument inconnues','identiques à toutes les autres formes existantes','invisibles complètement à l''oeil nu']::text[], null, 27210, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27219, 'cm2', 'lecture', 'Que veut dire "rond de sorcière" dans le contexte de cette promenade en forêt ?', 'une formation circulaire naturelle de champignons autour d''un arbre', array['un type rare de champignon particulièrement venimeux','un cercle trace volontairement par un promeneur','une simple légende sans rapport avec les champignons']::text[], null, 27210, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27220, 'cm2', 'lecture', 'Que veut dire "ingère" à propos du danger lie à l''amanite tue-mouches évoque par papi ?', 'avale et consomme par voie orale', array['simplement touche du bout des doigts','regarde attentivement de très près','photographie avec beaucoup de précaution']::text[], null, 27210, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27221, 'cm2', 'lecture', 'Que veut dire "peu avertis" à propos des promeneurs pouvant être attires par ce champignon dangereux ?', 'insuffisamment informes des dangers réels existants', array['particulièrement bien formes sur ce sujet précis','totalement indifférents à la question posée','extrêmement prudents en toutes circonstances']::text[], null, 27210, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27222, 'cm2', 'lecture', 'Que veut dire "sélectionnés" à propos des champignons finalement rapportes par Greta dans son panier ?', 'choisis avec soin après une vérification attentive', array['ramasses totalement au hasard sans réflexion','trouvés par pur hasard sur le chemin parcouru','achetés directement dans un magasin spécialise']::text[], null, 27210, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27223, 'cm2', 'lecture', 'Pourquoi papi rappelle-t-il systématiquement les règles de sécurité avant chaque cueillette de champignons ?', 'certains champignons peuvent se révéler dangereux si on les confond avec d''autres espèces comestibles', array['c''est une simple habitude sans lien réel avec un véritable danger','Greta à déjà commis une erreur grave par le passe','la forêt est officiellement un lieu interdit sans autorisation préalable']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27224, 'cm2', 'lecture', 'Pourquoi Greta avance-t-elle aussi prudemment en observant attentivement le sol de la forêt ?', 'elle cherche minutieusement les champignons dissimules parmi les feuilles mortes', array['elle a simplement peur de se blesser en marchant sur ce terrain','le sol se révèle particulièrement glissant ce jour-là précis','elle suit attentivement les traces laissées par un animal']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27225, 'cm2', 'lecture', 'Pourquoi le champignon rouge tacheté de blanc est-il particulièrement dangereux malgré son aspect attrayant ?', 'son apparence séduisante peut tromper les promeneurs alors qu''il se révèle toxique', array['il pique douloureusement au simple toucher','il dégage une odeur particulièrement mauvaise et repoussante','il ressemble exactement à n''importe quel autre cèpe comestible']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27226, 'cm2', 'lecture', 'Qu''est-ce qui montre que cette activité de cueillette représente une véritable tradition familiale importante ?', 'Greta et son papi la partagent ensemble depuis déjà plusieurs années consécutives', array['c''est en réalité la toute première fois qu''ils la pratiquent ensemble','Greta n''apprécie manifestement pas vraiment cette activité particulière','papi organise cette sortie à contrecoeur chaque année']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27227, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par papi dans la transmission de ce savoir naturaliste à sa petite-fille ?', 'il lui transmet avec patience des connaissances précieuses et utiles sur le monde naturel', array['il se contente simplement de l''accompagner sans jamais rien lui expliquer','il décourage activement Greta de poursuivre cette activité','il garde égoïstement toutes ses connaissances pour lui seul']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27228, 'cm2', 'lecture', 'Que peut-on déduire de la fierté manifestée par Greta à la toute fin de cette matinée de cueillette ?', 'elle est sincèrement satisfaite d''avoir participé activement à une cueillette particulièrement réussie', array['elle se montre en réalité déçue du résultat finalement obtenu','elle regrette globalement d''avoir accompagné son papi ce jour-là','elle aurait préféré nettement réaliser cette cueillette entièrement seule']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27229, 'cm2', 'lecture', 'Pourquoi Greta note-t-elle soigneusement le soir les noms des champignons découverts durant la journée ?', 'elle souhaite mémoriser durablement ces connaissances pour progresser lors de futures sorties', array['sa maîtresse d''école le lui a explicitement demandé','elle doit impérativement rendre ce travail pour l''école dès le lundi','elle n''a en réalité rien d''autre à faire ce soir-là précis']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27230, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''attitude de Greta envers la nature à travers cette journée de cueillette ?', 'elle développe un rapport curieux et respectueux envers le monde naturel qui l''entoure', array['elle considère cette activité comme une simple corvée imposée','elle préfère finalement nettement les activités pratiquées en intérieur','elle n''accorde aucune attention particulière aux explications données par son papi']::text[], null, 27210, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27232, 'cm2', 'lecture', 'Que découvre précisément Oskar en se réveillant ce matin-là ?', 'le jardin recouvert d''un épais manteau de neige', array['un jardin totalement inonde par la pluie','un jardin simplement recouvert de feuilles mortes','rien de particulier à signaler ce jour-là']::text[], null, 27231, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27233, 'cm2', 'lecture', 'Que fait Oskar avant de sortir dans le jardin recouvert de neige ?', 'il enfile plusieurs couches de vêtements chauds', array['il reste simplement en pyjama toute la matinée','il se contente d''un manteau très léger','il ne se prépare pas particulièrement avant de sortir']::text[], null, 27231, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27234, 'cm2', 'lecture', 'Qui Oskar retrouve-t-il précisément dans le jardin familial ce matin-là ?', 'ses deux meilleurs amis du quartier', array['uniquement ses propres parents','sa maîtresse d''école habituelle','personne, il se retrouve entièrement seul']::text[], null, 27231, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27235, 'cm2', 'lecture', 'Que font les enfants une fois le bonhomme de neige entièrement termine ?', 'ils organisent une bataille de boules de neige', array['ils rentrent immédiatement chez eux sans attendre','ils recommencent aussitôt un autre bonhomme','ils partent voir un autre jardin voisin']::text[], null, 27231, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27236, 'cm2', 'lecture', 'Que fait la maman d''Oskar vers midi lorsque les enfants rentrent trempes ?', 'elle leur prépare un chocolat chaud réconfortant', array['elle les gronde sévèrement d''être trempes','elle les envoie directement prendre une douche','elle leur demande de ranger immédiatement le jardin']::text[], null, 27231, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27237, 'cm2', 'lecture', 'Que fait précisément Oskar seul durant l''après-midi de cette journée ?', 'il essaie de fabriquer un igloo miniature', array['il regarde simplement la télévision','il fait consciencieusement ses devoirs scolaires','il dort profondément tout l''après-midi']::text[], null, 27231, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27238, 'cm2', 'lecture', 'Que veut dire "scintillant" à propos du manteau blanc recouvrant le jardin d''Oskar ?', 'qui brille par de multiples reflets de lumière', array['totalement terne et particulièrement sombre','sale et visiblement grisâtre','en train de fondre très rapidement']::text[], null, 27231, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27239, 'cm2', 'lecture', 'Que veut dire "guette" à propos d''Oskar cache derrière le buisson enneigé ?', 'surveille attentivement en attendant le bon moment précis', array['dort profondément sans se soucier de rien','s''ennuie visiblement sans rien faire de particulier','cherche activement à s''enfuir discrètement']::text[], null, 27231, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27240, 'cm2', 'lecture', 'Que veut dire "attendrissement" à propos de la manière dont la maman écoute les enfants raconter leurs exploits ?', 'avec beaucoup de tendresse et d''émotion sincère', array['avec une indifférence manifeste et visible','avec une colère non dissimulée','avec un ennui particulièrement évident']::text[], null, 27231, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27241, 'cm2', 'lecture', 'Que veut dire "riposter" à propos de la réaction des amis d''Oskar après avoir été surpris ?', 'répondre activement à une attaque reçue précédemment', array['abandonner immédiatement toute forme de jeu','fuir rapidement et sans se retourner','pleurer abondamment sans aucune réaction']::text[], null, 27231, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27242, 'cm2', 'lecture', 'Que veut dire "radieux" à propos de l''état d''Oskar en s''endormant le soir de cette journée ?', 'exprimant un très grand bonheur visible et manifeste', array['totalement épuise et particulièrement abattu','en colère et sensiblement frustré','indifférent aux événements vécus durant la journée']::text[], null, 27231, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27243, 'cm2', 'lecture', 'Que veut dire "s''inspirant" à propos du livre sur les régions polaires lu par Oskar quelques semaines auparavant ?', 'prenant une idée précise à partir d''une source existante', array['copiant exactement sans jamais réfléchir personnellement','ignorant totalement le contenu de cette source','critiquant sévèrement le contenu de ce livre']::text[], null, 27231, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27244, 'cm2', 'lecture', 'Pourquoi Oskar avale-t-il son petit-déjeuner particulièrement vite ce matin de neige ?', 'il est impatient de profiter au plus vite de la neige fraîchement tombée', array['il est visiblement en retard pour se rendre à l''école','sa maman le presse fortement sans raison apparente','il n''apprécie manifestement pas ce petit-déjeuner précis']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27245, 'cm2', 'lecture', 'Pourquoi Oskar choisit-il de se cacher derrière un buisson pendant la bataille de boules de neige ?', 'il souhaite surprendre efficacement ses amis avec une attaque totalement inattendue', array['il a en réalité peur d''être touche par une boule de neige','il cherche simplement à se reposer un court instant','il ne souhaite plus du tout participer à ce jeu collectif']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27246, 'cm2', 'lecture', 'Qu''est-ce qui montre que cette journée de neige rend Oskar particulièrement heureux du début à la fin ?', 'sa joie immense au réveil se prolonge par un enthousiasme constant tout au long de la journée', array['il reste enferme à l''intérieur durant l''intégralité de cette journée','il se plaint constamment du froid ressenti tout au long de la journée','il préfère nettement jouer seul plutôt qu''avec ses deux amis']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27247, 'cm2', 'lecture', 'Pourquoi Oskar essaie-t-il de construire un igloo l''après-midi après avoir déjà joue toute la matinée ?', 'il souhaite prolonger le plaisir procure par la neige en s''inspirant de sa lecture récente', array['ses amis le lui demandent explicitement de réaliser ce projet','sa maman l''oblige fermement à rester dehors plus longtemps','il n''a en réalité plus rien d''autre à faire de sa journée']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27248, 'cm2', 'lecture', 'Que peut-on déduire du caractère général d''Oskar à travers l''ensemble des activités menées durant cette journée de neige ?', 'il se révèle curieux, actif et particulièrement plein d''imagination créative', array['il préfère globalement rester à l''intérieur dans le calme','il n''apprécie manifestement pas particulièrement jouer dehors','il se lasse très rapidement des activités liées à la neige']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27249, 'cm2', 'lecture', 'Que peut-on déduire de l''amitié unissant Oskar à ses deux camarades du quartier à travers cette journée partagée ?', 'ils partagent une complicité joyeuse et sincère autour d''activités menées en commun', array['ils se disputent régulièrement pendant l''ensemble de leurs jeux partagés','Oskar préfère en réalité nettement jouer seul plutôt qu''avec eux','leur amitié se révèle finalement récente et particulièrement fragile']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27250, 'cm2', 'lecture', 'Pourquoi Oskar espère-t-il secrètement qu''il neigera de nouveau durant les prochains jours de vacances ?', 'cette journée lui a procuré un plaisir intense qu''il souhaite sincèrement revivre bientôt', array['il n''a en réalité aucun autre projet prévu pour ses vacances scolaires','ses parents lui ont promis explicitement un cadeau en cas de nouvelle neige','il souhaite simplement éviter de devoir retourner à l''école rapidement']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27251, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''importance de cette journée de neige dans les souvenirs futurs d''Oskar ?', 'elle constitue un souvenir marquant et particulièrement heureux de son enfance', array['elle ne représente en définitive qu''une journée banale parmi tant d''autres','il oubliera vraisemblablement cette journée des la semaine suivante','cette journée n''aura finalement aucune conséquence sur ses futurs souvenirs']::text[], null, 27231, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27253, 'cm2', 'lecture', 'Quel âge précis Chiara fête-t-elle durant cette journée particulière ?', 'dix ans', array['huit ans seulement','douze ans déjà','sept ans à peine']::text[], null, 27252, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27254, 'cm2', 'lecture', 'Où se déroule exactement l''anniversaire organisé pour Chiara ?', 'à la maison familiale', array['dans un restaurant réserve','directement à l''école','dans un grand parc public']::text[], null, 27252, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27255, 'cm2', 'lecture', 'Qui organise spécifiquement le jeu de piste de cette après-midi d''anniversaire ?', 'le papa de Chiara', array['la maîtresse habituelle de Chiara','un animateur professionnel embauche','personne, ce n''était pas prévu initialement']::text[], null, 27252, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27256, 'cm2', 'lecture', 'Combien de bougies sont précisément allumées sur le gâteau d''anniversaire ?', 'dix', array['huit seulement','douze exactement','cinq à peine']::text[], null, 27252, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27257, 'cm2', 'lecture', 'Que fait Chiara en toute fin de journée, une fois les invites repartis ?', 'elle aide sa maman à ranger le salon', array['elle part immédiatement se coucher sans attendre','elle sort retrouver d''autres amis en ville','elle oublie totalement ses cadeaux reçus']::text[], null, 27252, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27258, 'cm2', 'lecture', 'Que fait Chiara juste avant de s''endormir ce soir-là précisément ?', 'elle relit les petits mots d''anniversaire reçus', array['elle range immédiatement tous ses jouets','elle appelle une amie au téléphone','elle regarde la télévision jusque tard']::text[], null, 27252, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27259, 'cm2', 'lecture', 'Que veut dire "banderole" dans le contexte de la décoration du salon ce jour-là ?', 'une longue bande de tissu ou de papier portant un message', array['un simple ballon de fête gonfle','une guirlande lumineuse décorative','une nappe posée sur la table']::text[], null, 27252, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27260, 'cm2', 'lecture', 'Que veut dire "énigmes" à propos du jeu de piste organisé par le papa de Chiara ?', 'dès questions ou devinettes précises à résoudre', array['des cadeaux simplement dissimules dans la maison','des chansons à chanter collectivement','des photos anciennes à retrouver']::text[], null, 27252, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27261, 'cm2', 'lecture', 'Que veut dire "inattendus" à propos des endroits ou sont cachés certains indices du jeu ?', 'surprenants, que l''on n''imaginait absolument pas', array['particulièrement faciles à deviner immédiatement','toujours identiques d''une année sur l''autre','formellement interdits d''accès aux enfants']::text[], null, 27252, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27262, 'cm2', 'lecture', 'Que veut dire "généreuses" à propos des parts de gâteau distribuées à tous les invites ?', 'particulièrement grandes et abondantes', array['toutes petites et particulièrement fines','inégales entre les différents invités présents','servies complètement froides ce jour-là']::text[], null, 27252, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27263, 'cm2', 'lecture', 'Que veut dire "chaleureusement" à propos de la manière dont Chiara remercie ses invites présents ?', 'avec beaucoup de sincérité et une affection visible', array['froidement et sans aucun entrain particulier','avec une indifférence manifeste et visible','avec une pointe évidente de moquerie']::text[], null, 27252, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27264, 'cm2', 'lecture', 'Que veut dire "précieusement" à propos des petits mots gardés soigneusement par Chiara ?', 'avec beaucoup de soin, car cela compte véritablement pour elle', array['sans aucune attention particulière portée au geste','en les jetant rapidement sans y penser','en les cachant volontairement de tous les regards']::text[], null, 27252, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27265, 'cm2', 'lecture', 'Pourquoi Chiara ferme-t-elle précisément les yeux avant de souffler ses dix bougies d''anniversaire ?', 'elle se concentre pleinement pour formuler un voeu secret personnel', array['elle a en réalité peur du feu produit par les bougies','sa maman le lui demande explicitement de faire ainsi','elle se sent particulièrement fatiguée après cette longue journée']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27266, 'cm2', 'lecture', 'Pourquoi le papa de Chiara organise-t-il spécifiquement un jeu de piste pour cet anniversaire précis ?', 'il souhaite rendre la fête plus amusante et originale pour l''ensemble des enfants présents', array['il n''a en réalité pas eu le temps de préparer autre chose de différent','les enfants le lui ont explicitement imposé au dernier moment','c''est une tradition rigoureusement obligatoire chaque année sans exception']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27267, 'cm2', 'lecture', 'Qu''est-ce qui montre que Chiara attendait cette journée particulière avec une réelle impatience ?', 'elle attend cette journée précise depuis déjà plusieurs semaines complètes', array['elle avait en réalité totalement oublie la date de son propre anniversaire','elle préférerait clairement fêter son anniversaire un autre jour de l''année','elle s''ennuie visiblement pendant l''intégralité de cette fête organisée']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27268, 'cm2', 'lecture', 'Pourquoi Chiara garde-t-elle si précieusement les petits mots d''anniversaire reçus par ses proches ?', 'ils représentent des marques sincères d''affection venant de ses proches et amis', array['elle doit impérativement les rendre à ses amis plus tard dans l''année','sa maman le lui impose sans lui donner davantage d''explications','elle souhaite en réalité les jeter rapidement après les avoir lus']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27269, 'cm2', 'lecture', 'Que peut-on déduire de l''ambiance générale ayant règne durant cet anniversaire particulier de Chiara ?', 'c''est une fête joyeuse et particulièrement chaleureuse partagée entre proches', array['c''est une fête triste et globalement décevante pour la jeune Chiara','les invites présents s''ennuient visiblement durant toute la journée','Chiara préférerait clairement être restée seule ce jour-là précis']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27270, 'cm2', 'lecture', 'Que peut-on déduire de l''implication de toute la famille dans la préparation minutieuse de cette fête ?', 'chacun contribue avec une réelle attention à rendre cette journée particulièrement réussie', array['seule Chiara s''occupe finalement de l''ensemble des préparatifs','les parents ne participent en réalité pas du tout à cette organisation','cette fête a été organisée sans la moindre préparation préalable']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27271, 'cm2', 'lecture', 'Pourquoi Chiara décide-t-elle de conserver les petits mots reçus dans une boite à souvenirs spécifique ?', 'elle souhaite pouvoir se remémorer durablement les marques d''affection reçues ce jour-là', array['sa maman lui impose explicitement cette organisation particulière','elle n''a en réalité nulle part ailleurs pour ranger ces papiers','elle doit impérativement les montrer à sa maîtresse le lundi suivant']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27272, 'cm2', 'lecture', 'Que peut-on déduire globalement de la place occupée par les relations amicales et familiales dans la vie de Chiara ?', 'elles occupent une place particulièrement précieuse et centrale dans son bonheur personnel', array['elles n''ont finalement qu''une importance très secondaire pour elle','elle préférerait clairement passer davantage de temps seule','ces relations ne comptent en réalité pas véritablement pour elle']::text[], null, 27252, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27274, 'cm2', 'lecture', 'À quel moment précis Liam se rend-il régulièrement à la bibliothèque de son quartier ?', 'chaque mercredi après-midi', array['chaque samedi matin uniquement','pendant les vacances scolaires exclusivement','une seule fois par année entière']::text[], null, 27273, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27275, 'cm2', 'lecture', 'Vers quel rayon précis Liam se dirige-t-il systématiquement en arrivant à la bibliothèque ?', 'le rayon des romans d''aventure', array['le rayon des bandes dessinées','le rayon des livres de cuisine','le rayon des magazines actuels']::text[], null, 27273, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27276, 'cm2', 'lecture', 'Que raconte précisément le nouveau livre découvert par Liam ce jour-là ?', 'l''histoire d''un jeune explorateur perdu dans une forêt tropicale', array['l''histoire d''un simple animal domestique','l''histoire d''un voyage lointain dans l''espace','l''histoire d''une compétition sportive nationale']::text[], null, 27273, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27277, 'cm2', 'lecture', 'Que fait précisément la bibliothécaire en apercevant Liam ce mercredi-là ?', 'elle lui recommande discrètement un autre livre', array['elle lui demande poliment de quitter les lieux','elle l''ignore totalement sans lui adresser la parole','elle lui confisque immédiatement son livre choisi']::text[], null, 27273, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27278, 'cm2', 'lecture', 'Combien de livres Liam emprunte-t-il finalement à la fin de cette visite ?', 'trois', array['un seul livre uniquement','cinq livres au total','aucun livre ce jour-là précis']::text[], null, 27273, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27279, 'cm2', 'lecture', 'Que demande spécifiquement Liam à la bibliothécaire concernant le nouveau livre découvert ?', 'des précisions sur l''auteur de ce livre', array['le prix exact de cet ouvrage','l''année précise de sa première parution','le nombre total de pages du livre']::text[], null, 27273, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27280, 'cm2', 'lecture', 'Que veut dire "bruissement" à propos des pages tournées dans le silence de la bibliothèque ?', 'un léger bruit doux et particulièrement continu', array['un bruit très fort et absolument soudain','un silence total et parfaitement absolu','un grincement métallique particulièrement désagréable']::text[], null, 27273, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27281, 'cm2', 'lecture', 'Que veut dire "absorbe" à propos de Liam plonge dans sa nouvelle lecture ?', 'totalement concentre et profondément captive', array['distrait et visiblement inattentif','fatigué et manifestement somnolent','ennuyé par le contenu du livre']::text[], null, 27273, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27282, 'cm2', 'lecture', 'Que veut dire "susceptible de lui plaire" à propos du livre recommande par la bibliothécaire attentive ?', 'qui présente de fortes chances de lui plaire réellement', array['qui ne lui plaira sûrement absolument pas','qui est en réalité déjà lu par Liam','qui est strictement réserve aux lecteurs adultes']::text[], null, 27273, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27283, 'cm2', 'lecture', 'Que veut dire "volontiers" à propos de la manière dont Liam accepte le conseil de la bibliothécaire ?', 'avec un véritable plaisir et sans la moindre hésitation', array['avec une réticence particulièrement marquée','en se plaignant ouvertement de la proposition','par pure obligation et sans conviction']::text[], null, 27273, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27284, 'cm2', 'lecture', 'Que veut dire "contrées lointaines" à propos des romans précédents écrits par cet auteur découvert ?', 'des régions géographiques particulièrement éloignées', array['des quartiers proches de chez Liam','des lieux totalement imaginaires et fictifs','des périodes historiques très anciennes']::text[], null, 27273, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27285, 'cm2', 'lecture', 'Que veut dire "couramment" à propos de la manière dont Liam sait désormais lire ?', 'avec une aisance et une fluidité réelles', array['très lentement et particulièrement difficilement','uniquement les mots les plus simples','seulement lorsqu''il lit à voix haute']::text[], null, 27273, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27286, 'cm2', 'lecture', 'Pourquoi Liam passe-t-il généralement de longues minutes à comparer les couvertures des livres disponibles ?', 'il souhaite choisir avec un soin particulier l''histoire qui lui plaira le plus', array['il ne sait pas encore véritablement lire les titres proposés','la bibliothécaire le lui impose explicitement à chaque visite','il cherche uniquement à perdre du temps volontairement']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27287, 'cm2', 'lecture', 'Pourquoi la bibliothécaire recommande-t-elle systématiquement un livre précis à Liam et pas à un autre enfant ?', 'elle connaît particulièrement bien ses goûts grâce à ses nombreuses visites régulières', array['elle recommande en réalité les mêmes livres à tous les enfants sans distinction','elle cherche uniquement à se débarrasser d''un livre peu emprunté habituellement','Liam le lui a explicitement demandé dès son arrivée ce jour-là']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27288, 'cm2', 'lecture', 'Qu''est-ce qui montre que Liam apprécie sincèrement la lecture et non pas seulement l''obligation scolaire imposée ?', 'il se montre impatient de continuer sa lecture jusque tard le soir une fois rentre chez lui', array['il n''emprunte des livres qu''exclusivement pour réaliser ses devoirs scolaires','il n''ouvre en réalité jamais les livres qu''il emprunte pourtant régulièrement','il préférerait clairement faire tout autre chose de son mercredi après-midi']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27289, 'cm2', 'lecture', 'Pourquoi Liam accepte-t-il volontiers la suggestion de la bibliothécaire plutôt que de choisir uniquement seul ?', 'il apprécie sincèrement découvrir de nouvelles histoires suggérées par une autre personne', array['il n''a en réalité plus le temps de chercher lui-même un livre','il fait systématiquement tout ce qu''on lui demande sans jamais réfléchir','il n''apprécie pas particulièrement le rayon des aventures ce jour-là']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27290, 'cm2', 'lecture', 'Pourquoi Liam demande-t-il des précisions supplémentaires sur l''auteur du nouveau livre découvert ?', 'sa curiosité naturelle le pousse à approfondir sa compréhension de cette nouvelle découverte', array['la bibliothécaire l''oblige explicitement à poser cette question précise','il doit impérativement rédiger un expose scolaire sur cet auteur','il n''a en réalité rien d''autre à dire à la bibliothécaire ce jour-là']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27291, 'cm2', 'lecture', 'Que peut-on déduire de la relation particulière entre Liam et la bibliothécaire au fil du temps ?', 'une relation de confiance sincère construite progressivement au fil de visites régulières', array['ils se rencontrent en réalité pour la toute première fois ce jour-là','Liam évite habituellement de lui adresser la parole','la bibliothécaire ne se souvient absolument jamais de lui']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27292, 'cm2', 'lecture', 'Pourquoi Liam se promet-il de revenir des la semaine suivante pour partager ses impressions de lecture ?', 'il souhaite entretenir cette relation d''échange privilégiée avec la bibliothécaire attentionnée', array['c''est une obligation stricte imposée par le règlement de la bibliothèque','il n''a en réalité personne d''autre à qui parler de ses lectures','sa maman l''oblige explicitement à effectuer cette démarche précise']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27293, 'cm2', 'lecture', 'Que peut-on déduire de l''importance globale de la bibliothèque dans le quotidien et l''épanouissement de Liam ?', 'c''est un lieu essentiel qui nourrit durablement sa passion sincère pour la lecture', array['c''est un endroit qu''il fréquente uniquement par pure obligation scolaire','il préférerait clairement rester chez lui plutôt que de s''y rendre','cette sortie hebdomadaire ne compte en réalité pas véritablement pour lui']::text[], null, 27273, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27295, 'cm2', 'lecture', 'Où précisément Amelia passe-t-elle toute sa journée durant ces vacances d''été ?', 'à la piscine municipale', array['directement à la plage','au bord d''un lac naturel','dans un simple jardin public']::text[], null, 27294, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27296, 'cm2', 'lecture', 'Que rappelle patiemment la maman d''Amelia avant le début de la baignade ?', 'les règles de sécurité essentielles', array['l''heure précise du déjeuner','le prix exact de l''entrée','les horaires de fermeture de la piscine']::text[], null, 27294, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27297, 'cm2', 'lecture', 'Quelle technique de nage précise Amelia pratique-t-elle fièrement ce jour-là ?', 'la brasse', array['le crawl uniquement','la nage sur le dos','elle ne sait pas encore nager']::text[], null, 27294, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27298, 'cm2', 'lecture', 'En quoi consiste précisément le jeu organisé par le maître-nageur vers onze heures ?', 'récupérer des anneaux colorés au fond de l''eau', array['réaliser une course de nage rapide','organiser un concours de plongeon','jouer simplement avec un ballon']::text[], null, 27294, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27299, 'cm2', 'lecture', 'Que décide de faire Amelia après avoir déjeuné à l''ombre d''un parasol ?', 'elle essaie le grand toboggan aquatique', array['elle rentre directement à la maison','elle fait une longue sieste réparatrice','elle regarde simplement les autres enfants nager']::text[], null, 27294, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27300, 'cm2', 'lecture', 'Que demande Amelia à ses parents sur le chemin du retour à la maison ?', 's''ils pourront revenir bientôt à cette piscine', array['de ne plus jamais y retourner','d''acheter immédiatement un nouveau maillot','de changer définitivement de piscine']::text[], null, 27294, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27301, 'cm2', 'lecture', 'Que veut dire "barbotent" à propos des enfants s''amusant dans le grand bassin ?', 's''amusent en jouant dans une eau peu profonde', array['nagent avec une très grande rapidité','restent totalement immobiles sans bouger','sortent constamment et rapidement de l''eau']::text[], null, 27294, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27302, 'cm2', 'lecture', 'Que veut dire "radieuse" à propos d''Amelia en fin de cette longue journée ?', 'rayonnante d''une joie et d''un bonheur visibles', array['totalement épuisée et manifestement triste','en colère contre elle-même','malade et particulièrement fiévreuse']::text[], null, 27294, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27303, 'cm2', 'lecture', 'Que veut dire "courageusement" à propos de la manière dont Amelia plonge pour récupérer les anneaux ?', 'avec une réelle bravoure malgré une possible appréhension', array['avec une peur intense qui l''empêche totalement d''agir','sans le moindre effort particulier fourni','en étant simplement poussée par un adulte présent']::text[], null, 27294, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27304, 'cm2', 'lecture', 'Que veut dire "surveillée" à propos de la zone dans laquelle Amelia doit obligatoirement rester ?', 'contrôlée et attentivement observée pour des raisons de sécurité', array['totalement libre et dépourvue de toute règle','strictement interdite d''accès à tous les visiteurs','exclusivement réservée aux adultes présents']::text[], null, 27294, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27305, 'cm2', 'lecture', 'Que veut dire "récemment" à propos de la date d''installation du toboggan aquatique de la piscine ?', 'il y a relativement peu de temps', array['il y a de très nombreuses années déjà','depuis toujours, sans exception aucune','on ne connaît en réalité pas cette date précise']::text[], null, 27294, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27306, 'cm2', 'lecture', 'Que veut dire "appréhension" à propos du sentiment possible d''Amelia avant de descendre le toboggan ?', 'une légère crainte ou une inquiétude passagère', array['une très grande joie sans aucun mélange','une profonde fatigue physique accumulée','une totale indifférence face à la situation']::text[], null, 27294, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27307, 'cm2', 'lecture', 'Pourquoi la maman d''Amelia insiste-t-elle particulièrement sur les règles de sécurité avant la baignade ?', 'elle souhaite protéger efficacement sa fille des dangers potentiels présents à la piscine', array['c''est une règle imposée de manière identique par tous les établissements sans exception','Amelia a déjà connu un accident par le passe à ce sujet précis','le maître-nageur l''exige personnellement auprès de chaque parent présent']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27308, 'cm2', 'lecture', 'Pourquoi Amelia hésite-t-elle quelques instants avant de se lancer sur le nouveau toboggan aquatique ?', 'c''est la toute première fois qu''elle essaie cette attraction totalement nouvelle pour elle', array['elle a en réalité peur de l''eau de manière générale','sa maman le lui interdit formellement dans un premier temps','le toboggan connaît à ce moment une panne technique']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27309, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement qu''Amelia progresse sérieusement dans sa pratique de la natation ?', 'elle pratique désormais fièrement la brasse apprise durant l''année scolaire précédente', array['elle refuse catégoriquement d''entrer dans le grand bassin de la piscine','elle a systématiquement besoin d''une bouée pour flotter dans l''eau','elle reste exclusivement dans le petit bassin réserve aux débutants']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27310, 'cm2', 'lecture', 'Pourquoi Amelia se retrouve-t-elle finalement parmi les meilleurs participants du jeu aux anneaux colorés ?', 'elle plonge courageusement à plusieurs reprises et parvient à rapporter trois anneaux distincts', array['elle triche discrètement pendant le déroulement du jeu propose','les autres enfants présents abandonnent très rapidement la partie','le maître-nageur présent la favorise ouvertement par rapport aux autres']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27311, 'cm2', 'lecture', 'Que peut-on déduire du plaisir général ressenti par Amelia tout au long de cette journée à la piscine ?', 'elle vit une journée particulièrement riche en découvertes et en réussites personnelles', array['elle s''ennuie manifestement du tout début jusqu''à la toute fin de la journée','elle préférerait clairement rester à la maison la prochaine fois','elle a globalement peur de l''eau durant l''intégralité de cette journée']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27312, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Amelia et sa maman tout au long de cette sortie à la piscine ?', 'sa maman l''accompagne avec attention tout en lui laissant gagner en autonomie personnelle', array['sa maman reste totalement indifférente aux activités menées par sa fille','sa maman empêche systématiquement Amelia de profiter pleinement de la piscine','Amelia préférerait clairement être accompagnée par quelqu''un d''autre']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27313, 'cm2', 'lecture', 'Pourquoi Amelia demande-t-elle déjà à revenir bientôt à cette même piscine sur le chemin du retour ?', 'elle souhaite sincèrement continuer à progresser dans sa pratique de la natation', array['elle a simplement oublié un objet personnel à la piscine ce jour-là','ses parents l''obligent explicitement à formuler cette demande précise','elle n''a en réalité rien d''autre à proposer pour les jours suivants']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27314, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''évolution de la confiance d''Amelia en elle-même durant cette journée entière ?', 'elle gagne progressivement en assurance grâce aux nombreuses réussites accumulées ce jour-là', array['elle perd au contraire toute confiance face aux différentes difficultés rencontrées','cette journée n''a finalement aucun effet notable sur sa confiance personnelle','elle regrette globalement d''avoir tenté de nouvelles activités ce jour-là']::text[], null, 27294, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27316, 'cm2', 'lecture', 'Que reçoit précisément Mateo pour l''occasion de son anniversaire ?', 'un vélo bleu équipe de vitesses', array['un vélo rouge sans aucune vitesse','une simple trottinette électrique','une paire de rollers neufs']::text[], null, 27315, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27317, 'cm2', 'lecture', 'Où se déroule précisément la toute première sortie à vélo effectuée par Mateo ?', 'dans le parc voisin de chez lui', array['directement dans la rue devant sa maison','à la campagne, loin de chez lui','au bord de la mer, en vacances']::text[], null, 27315, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27318, 'cm2', 'lecture', 'Que doit impérativement apprendre Mateo en tout premier lieu sur son nouveau vélo ?', 'le changement de vitesses', array['la réparation d''une crevaison','la réalisation d''acrobaties diverses','la conduite à très grande vitesse']::text[], null, 27315, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27319, 'cm2', 'lecture', 'Que lui explique également avec patience son papa concernant l''usage du vélo ?', 'comment utiliser correctement les freins', array['comment réparer efficacement une roue','comment nettoyer soigneusement le vélo','comment changer entièrement une chaîne']::text[], null, 27315, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27320, 'cm2', 'lecture', 'Avec qui précisément Mateo sort-il à vélo le week-end suivant sa première sortie ?', 'trois de ses amis du quartier', array['l''ensemble de sa famille proche','toute sa classe d''école','il décide de sortir entièrement seul']::text[], null, 27315, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27321, 'cm2', 'lecture', 'Où précisément le groupe d''amis s''arrête-t-il à mi-parcours de leur balade ?', 'près d''une fontaine publique', array['directement chez un ami du groupe','à proximité de leur école habituelle','dans un magasin de vélos du quartier']::text[], null, 27315, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27322, 'cm2', 'lecture', 'Que veut dire "goudronnées" à propos des allées empruntées dans le parc voisin ?', 'recouvertes d''un revêtement lisse permettant de circuler', array['recouvertes uniquement de terre et de boue','recouvertes entièrement de sable fin','recouvertes simplement d''herbe verte']::text[], null, 27315, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27323, 'cm2', 'lecture', 'Que veut dire "se familiariser" à propos de Mateo apprenant à utiliser le changement de vitesses ?', 's''habituer progressivement à un élément totalement nouveau pour lui', array['refuser catégoriquement d''apprendre quoi que ce soit','oublier très rapidement une information récemment donnée','éviter complètement une situation nouvelle rencontrée']::text[], null, 27315, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27324, 'cm2', 'lecture', 'Que veut dire "progressivement" à propos de la manière de freiner recommandée par le papa de Mateo ?', 'petit à petit, sans brusquerie particulière', array['de façon brutale et particulièrement soudaine','en s''arrêtant instantanément sans transition','en accélérant encore davantage la vitesse']::text[], null, 27315, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27325, 'cm2', 'lecture', 'Que veut dire "déséquilibre" à propos du danger évoque par le papa de Mateo concernant le freinage ?', 'une perte de stabilité pouvant provoquer une chute', array['un excès de vitesse uniquement rencontre','une simple panne mécanique du vélo','un bruit inhabituel provenant du vélo']::text[], null, 27315, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27326, 'cm2', 'lecture', 'Que veut dire "sacoches" à propos des accessoires attachés aux vélos du groupe d''amis ?', 'de petits sacs attachés au vélo pour transporter des affaires', array['des freins supplémentaires installés sur le vélo','des lumières destinées à un usage nocturne','des pneus de rechange transportés par précaution']::text[], null, 27315, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27327, 'cm2', 'lecture', 'Que veut dire "environnants" à propos des chemins explorés ensemble par le groupe d''amis de Mateo ?', 'qui se trouvent aux alentours immédiats du quartier', array['qui se situent très loin du quartier habituel','qui sont formellement interdits d''accès au public','qui n''existent en réalité plus aujourd''hui']::text[], null, 27315, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27328, 'cm2', 'lecture', 'Pourquoi le papa de Mateo choisit-il précisément le parc pour la toute première sortie à vélo de son fils ?', 'les larges allées permettent de rouler en toute sécurité, loin de la circulation automobile', array['c''est en réalité le seul endroit ouvert au public ce jour-là précis','Mateo le lui a explicitement demandé pour une raison précise','il n''existe simplement aucun autre parc disponible dans le quartier']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27329, 'cm2', 'lecture', 'Pourquoi Mateo persiste-t-il à apprendre le changement de vitesses malgré ses deux petites chutes initiales ?', 'il se montre véritablement motive à l''idée de maîtriser pleinement son nouveau vélo', array['son papa le force explicitement à continuer malgré les difficultés rencontrées','il n''a en réalité pas d''autre choix pour rentrer chez lui ce jour-là','ses amis se moqueraient ouvertement de lui dans le cas contraire']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27330, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que Mateo est particulièrement fier de son nouveau vélo lors de la sortie entre amis ?', 'il se sent très fier en roulant aux côtés de ses amis proches durant cette sortie', array['il préfère en réalité cacher discrètement son vélo à ses propres amis','il regrette visiblement d''avoir reçu ce vélo en cadeau d''anniversaire','il emprunte finalement le vélo d''un ami plutôt que d''utiliser le sien']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27331, 'cm2', 'lecture', 'Pourquoi le groupe d''amis emporte-t-il précisément des biscuits dans les sacoches attachées à leurs vélos ?', 'ils prévoient sagement de faire une pause et de se restaurer pendant leur sortie', array['ils doivent impérativement les livrer à une personne précise','c''est une règle strictement imposée par l''ensemble des parents concernes','ils n''ont en réalité pas eu le temps de déjeuner avant de partir']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27332, 'cm2', 'lecture', 'Que peut-on déduire de la progression évidente de Mateo entre sa première sortie et celle effectuée avec ses amis ?', 'il gagne rapidement en confiance et en maîtrise technique de son nouveau vélo', array['il ne progresse en réalité pas du tout entre ces deux sorties distinctes','il regrette finalement d''avoir choisi ce vélo particulier comme cadeau','il abandonne complètement la pratique du vélo après sa toute première sortie']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27333, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par le papa de Mateo dans cet apprentissage progressif du vélo ?', 'il transmet patiemment des conseils de sécurité essentiels à son fils avec bienveillance', array['il laisse Mateo apprendre entièrement seul sans lui apporter la moindre aide','il décourage plutôt Mateo de continuer à s''entraîner régulièrement','il critique systématiquement les erreurs commises par Mateo sans jamais les expliquer']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27334, 'cm2', 'lecture', 'Pourquoi Mateo raconte-t-il en détail chaque étape de cette journée à sa maman une fois rentre chez lui ?', 'il souhaite sincèrement partager avec elle sa joie et sa fierté ressenties ce jour-là', array['sa maman l''oblige explicitement à lui faire ce récit détaille','il n''a en réalité rien d''autre à faire de sa soirée ce jour-là','il cherche uniquement à obtenir un nouveau cadeau en récompense']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27335, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''évolution du rapport de Mateo à son propre vélo au fil de cette histoire ?', 'il développe progressivement un véritable attachement et une réelle maîtrise de cet objet nouveau', array['il regrette finalement d''avoir reçu ce cadeau d''anniversaire particulier','cette expérience n''a en réalité aucun effet notable sur son quotidien','il préfère désormais nettement son ancien vélo, plus simple d''utilisation']::text[], null, 27315, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27337, 'cm2', 'lecture', 'Où précisément Freya découvre-t-elle cette vieille cabane totalement abandonnée ?', 'au fond du grand jardin de ses grands-parents', array['directement dans la forêt voisine','au grenier même de la maison familiale','au bord d''une rivière proche']::text[], null, 27336, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27338, 'cm2', 'lecture', 'Que trouve exactement Freya en pénétrant à l''intérieur de cette cabane ?', 'un intérieur poussiéreux mais encore solide', array['un intérieur totalement détruit et inutilisable','des meubles entièrement neufs et modernes','d''autres enfants déjà installes à l''intérieur']::text[], null, 27336, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27339, 'cm2', 'lecture', 'Qui aide précisément Freya à nettoyer soigneusement sa nouvelle cabane ?', 'son papi, avec son accord bienveillant', array['uniquement ses cousins présents','personne, elle réalise tout entièrement seule','sa mamie exclusivement, sans aide']::text[], null, 27336, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27340, 'cm2', 'lecture', 'Que répare précisément le papi de Freya durant cette période de travaux ?', 'une planche de bois cassée près de l''entrée', array['l''intégralité du toit de la cabane','la fenêtre entièrement cassée','la porte particulièrement grinçante']::text[], null, 27336, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27341, 'cm2', 'lecture', 'Avec quels éléments précis Freya aménage-t-elle finalement l''intérieur de sa cabane ?', 'de vieux coussins, une caisse en bois et une guirlande lumineuse', array['des meubles entièrement neufs achetés en magasin','rien du tout, elle laisse volontairement l''espace vide','uniquement des jouets casses récupères']::text[], null, 27336, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27342, 'cm2', 'lecture', 'Que fait précisément Freya à la toute fin des vacances estivales ?', 'elle invite ses cousins à découvrir sa cabane', array['elle détruit entièrement la cabane avant son départ','elle garde définitivement la cabane secrète pour toujours','elle abandonne totalement son projet initial']::text[], null, 27336, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27343, 'cm2', 'lecture', 'Que veut dire "grinçante" à propos de la porte de la cabane découverte par Freya ?', 'qui produit un bruit aigu et particulièrement désagréable en s''ouvrant', array['qui s''ouvre sans produire le moindre bruit','qui reste totalement bloquée et immobile','qui est décorée de couleurs particulièrement vives']::text[], null, 27336, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27344, 'cm2', 'lecture', 'Que veut dire "refuge" à propos de ce que devient progressivement cette cabane pour la jeune Freya ?', 'un endroit ou l''on se sent particulièrement à l''abri et tranquille', array['un lieu manifestement dangereux qu''il faut absolument éviter','un endroit ouvert librement à tout le monde','un simple espace de rangement supplémentaire']::text[], null, 27336, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27345, 'cm2', 'lecture', 'Que veut dire "savourant" à propos de la manière dont Freya profite de son moment de calme quotidien ?', 'appréciant pleinement et avec un réel plaisir', array['supportant difficilement une situation subie','ignorant totalement ce moment particulier','redoutant fortement ce moment de la journée']::text[], null, 27336, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27346, 'cm2', 'lecture', 'Que veut dire "agitation" à propos de l''ambiance habituelle régnant dans la maison familiale ?', 'un mouvement particulièrement bruyant et anime', array['un calme particulièrement profond et paisible','un silence relativement pesant et inquiétant','une tristesse générale ressentie par tous']::text[], null, 27336, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27347, 'cm2', 'lecture', 'Que veut dire "aménagé" à propos de ce que réalise concrètement Freya à l''intérieur de sa cabane ?', 'organise et installe avec soin pour la rendre confortable', array['abandonne complètement sans y revenir','détruit petit à petit au fil du temps','ferme définitivement à clé sans jamais y revenir']::text[], null, 27336, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27348, 'cm2', 'lecture', 'Que veut dire "complicité" à propos de la relation qui se développe entre Freya et sa cousine préférée ?', 'une entente particulière et une proximité affective sincère', array['une rivalité manifeste et une tension constante','une indifférence totale l''une envers l''autre','un simple lien de politesse superficiel']::text[], null, 27336, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27349, 'cm2', 'lecture', 'Pourquoi Freya recherche-t-elle précisément un endroit loin du bruit de la maison familiale habituelle ?', 'elle recherche activement un moment de calme personnel loin de l''agitation des nombreux cousins', array['elle n''apprécie en réalité pas du tout sa propre famille','ses grands-parents l''obligent explicitement à s''isoler ainsi','elle a en réalité peur des autres enfants présents']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27350, 'cm2', 'lecture', 'Pourquoi le papi de Freya accepte-t-il volontiers de l''aider à réparer entièrement cette vieille cabane ?', 'il soutient avec bienveillance le projet personnel de sa petite-fille', array['il souhaite simplement se débarrasser d''une cabane gênante','Freya le menace explicitement de ne plus jamais lui parler sinon','c''est une obligation qu''il s''impose chaque été sans grand plaisir']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27351, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que Freya est particulièrement fière du travail accompli sur sa cabane ?', 'elle invite ses cousins à la découvrir à la toute fin des vacances estivales', array['elle cache définitivement la cabane à l''ensemble de son entourage','elle regrette visiblement d''avoir commencé ce projet personnel','elle demande finalement à son papi de tout refaire entièrement']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27352, 'cm2', 'lecture', 'Pourquoi Freya choisit-elle de n''inviter sa cousine préférée que discrètement, avant d''inviter tous les autres cousins ?', 'elle souhaite d''abord partager ce secret précieux avec la personne la plus proche d''elle', array['elle avait simplement oublie d''inviter les autres cousins présents','sa cousine préférée refusait de venir en présence des autres enfants','la cabane n''était pas encore suffisamment aménagée pour tous']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27353, 'cm2', 'lecture', 'Pourquoi Freya demande-t-elle à son papi de surveiller sa cabane durant toute la période hivernale ?', 'elle souhaite sincèrement pouvoir la retrouver intacte lors des prochaines vacances estivales', array['elle n''a en réalité pas confiance en la solidité de sa propre construction','son papi le lui impose explicitement avant son départ','elle envisage déjà de ne jamais revenir dans cette maison']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27354, 'cm2', 'lecture', 'Que peut-on déduire de la collaboration entre Freya et son papi tout au long de ce projet de rénovation ?', 'ils forment une équipe complémentaire et efficace autour d''un projet partage avec plaisir', array['ils se disputent constamment durant l''intégralité de cette construction','le papi réalise en réalité l''intégralité du travail sans l''aide de Freya','Freya ne participe finalement que très peu à ce projet commun']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27355, 'cm2', 'lecture', 'Que peut-on déduire de l''importance de cette cabane personnelle dans le développement de la jeune Freya ?', 'elle lui permet de développer sa confiance et son autonomie à travers un projet mené à terme', array['ce projet n''a eu finalement aucune influence particulière sur son développement','elle regrette d''avoir consacré autant de temps à cette construction personnelle','elle préférerait désormais nettement éviter tout projet manuel similaire']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27356, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''évolution des relations familiales de Freya à travers cette expérience de la cabane ?', 'elle renforce ses liens avec son papi et sa cousine tout en gagnant en indépendance personnelle', array['cette expérience n''a en réalité aucun effet sur ses relations familiales existantes','elle s''éloigne progressivement de l''ensemble de sa famille durant cet été','elle préfère finalement rester seule plutôt que de partager cette expérience']::text[], null, 27336, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27358, 'cm2', 'lecture', 'Où précisément Antoine aperçoit-il ce chien perdu et visiblement affame ?', 'dans le parc près de chez lui', array['dans la rue devant son école','directement à la campagne','à l''intérieur d''un magasin']::text[], null, 27357, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27359, 'cm2', 'lecture', 'De quelle race précise est le chien découvert par Antoine ce jour-là ?', 'un épagneul', array['un labrador retriever','un simple caniche','un berger allemand']::text[], null, 27357, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27360, 'cm2', 'lecture', 'Que porte précisément le chien autour de son cou lorsqu''Antoine le trouve ?', 'un collier rouge sans médaille identifiante', array['une médaille avec un numéro précis','rien du tout autour du cou','une laisse manifestement cassée']::text[], null, 27357, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27361, 'cm2', 'lecture', 'Que fait précisément la maman d''Antoine pour aider à retrouver le propriétaire du chien ?', 'elle l''aide à publier une annonce avec une photo', array['elle appelle uniquement la police locale','elle décide de garder le chien pour elle-même','elle ne fait finalement rien de particulier']::text[], null, 27357, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27362, 'cm2', 'lecture', 'Qui précisément Antoine appelle-t-il également pour signaler sa découverte du chien ?', 'la mairie', array['un vétérinaire uniquement','ses propres amis proches','personne d''autre que sa maman']::text[], null, 27357, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27363, 'cm2', 'lecture', 'Que fait exactement la femme en larmes le lendemain matin de la découverte ?', 'elle appelle Antoine après avoir vu l''annonce', array['elle vient directement sans jamais prévenir','elle ne se manifeste finalement jamais','elle appelle la police pour porter plainte']::text[], null, 27357, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27364, 'cm2', 'lecture', 'Que veut dire "errant" à propos du chien trouvé par Antoine dans le parc ?', 'qui se déplace sans direction précise, sans maître visible', array['qui court très rapidement vers un but précis','qui dort profondément sans bouger','qui reste attache solidement quelque part']::text[], null, 27357, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27365, 'cm2', 'lecture', 'Que veut dire "affame" à propos de l''état physique général du chien découvert ce jour-là ?', 'qui ressent une très grande faim', array['qui est particulièrement fatigué physiquement','qui est visiblement malade','qui ressent uniquement une grande soif']::text[], null, 27357, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27366, 'cm2', 'lecture', 'Que veut dire "soulagement" à propos des larmes versées par la propriétaire retrouvant son chien ?', 'un sentiment de libération ressenti après une longue inquiétude', array['une grande tristesse qui persiste malgré tout','une colère manifestement intense','une indifférence totale face à la situation']::text[], null, 27357, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27367, 'cm2', 'lecture', 'Que veut dire "timidement" à propos de la manière dont le chien remue sa queue au début ?', 'avec une certaine réserve, assez doucement', array['avec une très grande énergie manifeste','de façon particulièrement agressive','sans produire le moindre mouvement']::text[], null, 27357, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27368, 'cm2', 'lecture', 'Que veut dire "signaler" à propos de l''appel passe par Antoine directement à la mairie ?', 'informer officiellement les autorités d''un fait précis', array['cacher volontairement une information importante','refuser catégoriquement de communiquer','demander explicitement une récompense financière']::text[], null, 27357, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27369, 'cm2', 'lecture', 'Que veut dire "attachants" à propos des animaux qu''Antoine espère désormais mieux comprendre ?', 'qui suscitent facilement une affection sincère', array['qui repoussent généralement les personnes rencontrées','qui restent totalement indifférents aux humains','qui sont particulièrement dangereux au quotidien']::text[], null, 27357, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27370, 'cm2', 'lecture', 'Pourquoi Antoine s''approche-t-il très doucement du chien plutôt que de manière brusque ?', 'il ne souhaite surtout pas effrayer un animal déjà visiblement méfiant envers lui', array['il a en réalité peur d''être mordu immédiatement par le chien','le chien se montre particulièrement agressif envers les humains','sa maman le lui interdit fermement de s''approcher rapidement']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27371, 'cm2', 'lecture', 'Pourquoi Antoine décide-t-il de contacter simultanément les réseaux sociaux et les services de la mairie ?', 'il souhaite maximiser efficacement ses chances de retrouver rapidement les véritables propriétaires', array['c''est une obligation légale particulièrement stricte à respecter','sa maman ne lui fait pas suffisamment confiance pour agir seul','il n''a en réalité aucun autre moyen disponible pour agir']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27372, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que la propriétaire est particulièrement attachée à son chien retrouve ?', 'elle pleure de soulagement en le retrouvant après trois jours entiers de disparition', array['elle met plusieurs semaines entières avant de réagir à l''annonce publiée','elle demande à quelqu''un d''autre de venir chercher le chien à sa place','elle semble finalement indifférente au moment de récupérer son animal']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27373, 'cm2', 'lecture', 'Pourquoi la propriétaire offre-t-elle précisément un livre à Antoine en plus de ses sincères remerciements ?', 'elle souhaite exprimer concrètement sa gratitude pour son geste particulièrement généreux', array['c''est une obligation systématique lorsqu''on retrouve un animal perdu','Antoine le lui a explicitement demandé dès le début','elle n''avait en réalité rien d''autre à lui offrir ce jour-là']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27374, 'cm2', 'lecture', 'Que peut-on déduire du caractère général d''Antoine à travers l''ensemble de cette histoire vécue ?', 'il se révèle généreux, responsable et particulièrement attentif aux autres êtres vivants', array['il se montre en réalité indifférent au sort des animaux perdus rencontres','il n''agit finalement que pour obtenir une récompense matérielle','il préfère globalement ne pas s''impliquer dans ce genre de situation']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27375, 'cm2', 'lecture', 'Que peut-on déduire du soutien apporté par la maman d''Antoine tout au long de cette expérience vécue ?', 'elle encourage et aide activement son fils dans sa démarche solidaire envers l''animal', array['elle empêche en réalité Antoine de s''occuper correctement du chien trouve','elle préfère confier entièrement cette tache à quelqu''un d''autre','elle reste complètement indifférente à la situation vécue par son fils']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27376, 'cm2', 'lecture', 'Pourquoi Antoine demande-t-il finalement à ses parents s''il pourrait lui-même adopter un chien ?', 'cette expérience lui a fait découvrir à quel point les animaux peuvent devenir attachants', array['il souhaite simplement imiter le comportement d''un ami proche','ses parents lui ont explicitement promis cette adoption depuis longtemps','il n''a en réalité aucun autre projet personnel à proposer actuellement']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27377, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''impact de cette expérience sur la vision qu''Antoine à désormais des animaux ?', 'elle transforme durablement son rapport aux animaux et nourrit un nouveau projet personnel', array['cette expérience n''a finalement aucune conséquence sur sa vision des animaux','il se montre désormais plus méfiant envers l''ensemble des animaux rencontres','il regrette globalement de s''être implique dans cette situation particulière']::text[], null, 27357, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27379, 'cm2', 'lecture', 'Pourquoi précisément Zoé change-t-elle d''école cette année scolaire ?', 'sa famille a déménagé dans une nouvelle ville durant l''été', array['elle a malheureusement redoublé sa classe précédente','elle voulait elle-même changer d''école volontairement','ses parents l''ont inscrite ailleurs par simple erreur']::text[], null, 27378, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27380, 'cm2', 'lecture', 'Que fait précisément Zoé la veille au soir de cette rentrée particulière ?', 'elle prépare soigneusement son cartable neuf', array['elle range simplement sa propre chambre','elle rend visite à des amis proches','elle ne prépare finalement rien de particulier']::text[], null, 27378, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27381, 'cm2', 'lecture', 'Comment précisément Zoé se lève-t-elle le matin de cette rentrée si particulière ?', 'très tôt, sans pouvoir se rendormir ensuite', array['très tard, en étant visiblement en retard','normalement, exactement comme d''habitude','elle ne se lève en réalité pas seule']::text[], null, 27378, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27382, 'cm2', 'lecture', 'Qui précisément accueille les nouveaux élèves dans la cour de récréation ?', 'une maîtresse particulièrement souriante', array['uniquement le directeur de l''école','un autre élève plus âge','personne ne les accueille réellement']::text[], null, 27378, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27383, 'cm2', 'lecture', 'Que découvre précisément Zoé en entrant dans sa nouvelle salle de classe ?', 'son nom déjà inscrit sur une étiquette à son bureau', array['qu''elle n''a en réalité aucune place assise','qu''elle connaît déjà tous les autres élèves','qu''elle s''est simplement trompée de salle']::text[], null, 27378, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27384, 'cm2', 'lecture', 'Qui précisément invite Zoé à rejoindre un groupe d''amies pendant la récréation ?', 'une fillette prénommée Lisa', array['sa propre maîtresse de classe','sa maman restée dans la cour','un garçon de sa nouvelle classe']::text[], null, 27378, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27385, 'cm2', 'lecture', 'Que veut dire "appréhension" au tout début de cette histoire, à propos de Zoé ?', 'une inquiétude légère face à une situation entièrement nouvelle', array['une très grande joie sans le moindre mélange','une profonde fatigue physique accumulée','une totale indifférence face à la situation']::text[], null, 27378, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27386, 'cm2', 'lecture', 'Que veut dire "anxiété" à propos du sentiment ressenti par Zoé le matin de la rentrée ?', 'un sentiment d''inquiétude ou de stress relativement marqué', array['un sentiment de très grande joie manifeste','un sentiment de fatigue purement physique','un sentiment général d''ennui profond']::text[], null, 27378, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27387, 'cm2', 'lecture', 'Que veut dire "spontanément" à propos du geste accompli par Lisa envers Zoé ce jour-là ?', 'naturellement, sans y avoir été explicitement poussée', array['après y avoir très longuement réfléchi au préalable','sur ordre direct donné par la maîtresse présente','avec une réticence particulièrement visible']::text[], null, 27378, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27388, 'cm2', 'lecture', 'Que veut dire "naissante" à propos de l''amitié qui se développe entre Zoé et Lisa ?', 'qui commence tout juste à se former entre elles', array['qui existe en réalité depuis de très nombreuses années','qui est déjà définitivement terminée','qui n''existe finalement pas véritablement']::text[], null, 27378, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27389, 'cm2', 'lecture', 'Que veut dire "timidement" à propos de la manière dont Zoé observe initialement les autres enfants ?', 'avec une certaine réserve, sans oser s''approcher directement', array['avec une très grande assurance manifeste','avec une colère visible et marquée','de façon particulièrement moqueuse envers eux']::text[], null, 27378, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27390, 'cm2', 'lecture', 'Que veut dire "facilite" à propos de l''effet produit par les goûts communs partagés entre Zoé et Lisa ?', 'rend plus simple et plus naturel un processus donne', array['complique inutilement une situation existante','rend totalement impossible une chose précise','n''a en réalité aucun effet particulier observable']::text[], null, 27378, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27391, 'cm2', 'lecture', 'Pourquoi précisément Zoé se lève-t-elle si tôt le matin de la rentrée sans parvenir à se rendormir ?', 'l''anxiété liée à cette nouvelle expérience occupe entièrement toutes ses pensées', array['elle est simplement réveillée par un bruit provenant de l''extérieur','elle a en réalité mal dormi à cause d''une forte chaleur','elle doit impérativement partir très tôt pour un autre rendez-vous']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27392, 'cm2', 'lecture', 'Pourquoi précisément Zoé reste-t-elle d''abord à l''écart du groupe pendant la première récréation ?', 'elle ne connaît encore personne et se sent quelque peu intimidée par la situation', array['elle n''apprécie en réalité pas du tout jouer avec les autres enfants','sa propre maîtresse le lui demande explicitement','elle est en réalité punie pour un comportement passe']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27393, 'cm2', 'lecture', 'Pourquoi le geste accompli par Lisa envers Zoé se révèle-t-il particulièrement important ce jour-là précis ?', 'il permet à Zoé de se sentir immédiatement moins seule dans ce nouvel environnement inconnu', array['il oblige en réalité Zoé à jouer entièrement contre son gré','Lisa cherche uniquement à se faire bien voir de sa propre maîtresse','il n''a finalement aucune conséquence sur le reste de la journée de Zoé']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27394, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que la première journée de Zoé se termine finalement plutôt bien ?', 'elle rentre chez elle avec le sourire et raconte sa journée avec un réel enthousiasme', array['elle refuse catégoriquement de parler de sa journée à ses propres parents','elle pleure abondamment une fois rentrée à la maison familiale','elle demande explicitement à changer à nouveau d''école dès le lendemain']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27395, 'cm2', 'lecture', 'Que peut-on déduire du caractère de Lisa à travers le geste sincère qu''elle accomplit envers Zoé ce jour-là ?', 'elle fait preuve d''une réelle gentillesse et d''une ouverture envers les nouveaux élèves', array['elle se moque en réalité des élèves arrivant en cours d''année scolaire','elle se montre habituellement indifférente envers les nouveaux venus','elle agit uniquement pour obéir strictement à sa propre maîtresse']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27396, 'cm2', 'lecture', 'Que peut-on déduire de l''évolution du sentiment de Zoé entre le matin et le soir de cette journée de rentrée ?', 'son inquiétude initiale laisse progressivement place à un sentiment nettement plus positif et rassurant', array['elle demeure tout aussi anxieuse du tout début jusqu''à la toute fin de la journée','elle regrette globalement d''avoir déménagé des ce tout premier jour','aucun changement notable n''affecte finalement son ressenti au fil de la journée']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27397, 'cm2', 'lecture', 'Pourquoi Zoé écrit-elle précisément dans son journal intime le soir de cette première journée de rentrée ?', 'elle souhaite garder une trace personnelle de cette expérience finalement plus positive que prévu', array['sa maîtresse lui a explicitement imposé ce devoir dès le premier jour','elle n''a en réalité rien d''autre à faire de sa soirée ce jour-là','ses parents l''obligent formellement à tenir ce journal quotidien']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27398, 'cm2', 'lecture', 'Que peut-on déduire globalement de la capacité d''adaptation de Zoé face à ce changement d''école important ?', 'elle sait faire preuve de resilience et parvient progressivement à s''adapter positivement à une situation nouvelle', array['elle rencontre en réalité des difficultés insurmontables face à ce changement','elle refuse catégoriquement de s''adapter à sa nouvelle situation scolaire','cette capacité d''adaptation ne se manifeste finalement jamais chez elle']::text[], null, 27378, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27400, 'cm2', 'lecture', 'À quel événement scolaire précis Noah participe-t-il cette année-là ?', 'l''exposition de sciences de son école', array['un simple concours de dessin','une kermesse organisée par l''école','un tournoi sportif inter-classes']::text[], null, 27399, 'L', 'publie');
