insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27402, 'cm2', 'lecture', 'Qui précisément aide Noah à préparer le mélange chimique nécessaire à son expérience ?', 'son papa', array['sa propre maîtresse de classe','un camarade de sa classe','personne, il réalise tout entièrement seul']::text[], null, 27399, 'L', 'publie');
