insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27408, 'cm2', 'lecture', 'Que veut dire "jaillit" à propos du mélange orange sortant soudainement du cratère fabrique ?', 'sort brusquement et avec une certaine force', array['coule très lentement et progressivement','reste totalement immobile à l''intérieur','disparaît instantanément sans laisser de trace']::text[], null, 27399, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27409, 'cm2', 'lecture', 'Que veut dire "avec assurance" à propos de la manière dont Noah présente son projet au public ?', 'avec une réelle confiance en lui-même', array['avec une très grande hésitation visible','avec une peur manifeste et évidente','en lisant simplement un texte sans le comprendre']::text[], null, 27399, 'V', 'publie');
