insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27411, 'cm2', 'lecture', 'Que veut dire "spectaculaire" à propos de l''éruption chimique réalisée par le jeune Noah ?', 'qui impressionne fortement l''ensemble de ceux qui l''observent', array['totalement banal et particulièrement sans intérêt','invisible complètement pour le public présent','dangereux pour l''ensemble des visiteurs présents']::text[], null, 27399, 'V', 'publie');
