insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27431, 'cm2', 'lecture', 'Que veut dire "envahit" à propos de l''odeur sucrée se répandant dans toute la maison ?', 'se propage largement dans l''ensemble de l''espace disponible', array['reste confinée exclusivement à la cuisine','disparaît particulièrement rapidement une fois émise','n''est perceptible qu''une fois sorti de la maison']::text[], null, 27420, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27432, 'cm2', 'lecture', 'Que veut dire "onctueuse" à propos de la crème fraîche accompagnant la tarte dégustée ?', 'douce et particulièrement veloutée en bouche', array['particulièrement dure et compacte','totalement liquide et particulièrement fluide','séchée et particulièrement granuleuse']::text[], null, 27420, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27433, 'cm2', 'lecture', 'Pourquoi précisément mamie insiste-t-elle tant sur les règles d''hygiène avant de commencer à cuisiner ensemble ?', 'elle souhaite transmettre de bonnes habitudes tout en assurant une sécurité alimentaire optimale', array['c''est une règle sans importance qu''elle applique par pure habitude','Camille a déjà été malade auparavant à cause d''une mauvaise hygiène','c''est une exigence explicitement imposée par les propres parents de Camille']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27434, 'cm2', 'lecture', 'Pourquoi précisément mamie guide-t-elle Camille à chaque étape plutôt que de la laisser réaliser seule la recette ?', 'elle souhaite transmettre progressivement son savoir-faire tout en assurant la sécurité de sa petite-fille', array['elle ne fait en réalité pas du tout confiance à Camille','Camille le lui demande explicitement à chaque instant de la préparation','il est simplement plus rapide pour mamie de tout réaliser elle-même']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27435, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que Camille est particulièrement impatiente de découvrir le résultat de leur travail commun ?', 'l''odeur sucrée qui envahit progressivement la maison la rend particulièrement impatiente', array['elle refuse catégoriquement d''attendre la fin complète de la cuisson','elle demande explicitement à arrêter la cuisson bien plus tôt','elle s''endort complètement pendant toute la durée de la cuisson']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27436, 'cm2', 'lecture', 'Pourquoi mamie choisit-elle de raconter ses propres souvenirs d''enfance pendant le temps d''attente de la cuisson ?', 'elle souhaite partager avec Camille l''histoire et la valeur affective de cette recette familiale', array['elle n''a en réalité rien d''autre à faire pendant ce temps précis','Camille l''interroge avec une insistance particulière à ce sujet','c''est une habitude qu''elle répète systématiquement chaque semaine']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27437, 'cm2', 'lecture', 'Pourquoi ce moment hebdomadaire compte-t-il si particulièrement pour Camille et sa mamie réunies ?', 'il leur permet de partager un moment complice autour d''une passion commune sincère', array['c''est une obligation familiale dépourvue de tout plaisir réel','les propres parents de Camille l''exigent explicitement chaque semaine','elles n''ont finalement aucune autre activité disponible ce jour précis']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27438, 'cm2', 'lecture', 'Que peut-on déduire de la transmission du savoir-faire culinaire entre les générations illustrée par cette histoire ?', 'elle crée un lien affectif fort et valorisant entre Camille et sa grand-mère', array['elle n''apporte en réalité rien de particulier à leur relation existante','Camille n''apprend finalement rien de nouveau durant ces visites régulières','mamie regrette globalement de devoir partager ses propres recettes familiales']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27439, 'cm2', 'lecture', 'Que peut-on déduire du plaisir ressenti par les deux générations réunies lors de cette activité culinaire partagée ?', 'cuisiner ensemble constitue une source sincère de joie et de complicité pour toutes les deux', array['seule mamie retire un véritable plaisir de cette activité partagée','Camille préférerait clairement faire autre chose de son mercredi après-midi','cette activité est en réalité plutôt source de tension entre elles']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27440, 'cm2', 'lecture', 'Pourquoi Camille demande-t-elle déjà à préparer une nouvelle recette lors de leur prochain rendez-vous hebdomadaire ?', 'elle a pris un véritable plaisir à cette expérience et souhaite sincèrement la renouveler', array['sa mamie l''oblige explicitement à formuler cette demande précise','elle n''a en réalité rien d''autre à proposer pour la semaine suivante','elle cherche uniquement à faire plaisir à sa propre mamie']::text[], null, 27420, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27442, 'cm2', 'lecture', 'Où précisément se situe le potager entretenu ensemble par Bruno et son papi ?', 'derrière la maison de campagne', array['dans un jardin situe en pleine ville','directement à l''intérieur de l''école','chez un voisin proche de la maison']::text[], null, 27441, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27443, 'cm2', 'lecture', 'Que propose précisément papi à Bruno ce samedi matin particulier ?', 'planter de nouvelles graines de tomates', array['récolter des légumes déjà bien murs','arroser uniquement les fleurs présentes','construire une nouvelle serre']::text[], null, 27441, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27444, 'cm2', 'lecture', 'Que doit précisément apprendre Bruno en tout premier lieu ce jour-là ?', 'creuser de petits trous réguliers à intervalles précis', array['tailler soigneusement les arbres fruitiers','reconnaître les différentes mauvaises herbes','utiliser correctement un tracteur']::text[], null, 27441, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27445, 'cm2', 'lecture', 'Que fait précisément Bruno juste après avoir planté l''ensemble des graines ?', 'il arrose soigneusement chaque emplacement', array['il recouvre entièrement le potager d''une bâche','il rentre immédiatement à la maison','il replante aussitôt d''autres graines']::text[], null, 27441, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27446, 'cm2', 'lecture', 'Que tient précisément Bruno pour suivre l''évolution de ses plants au fil des semaines ?', 'un petit carnet avec des notes et des croquis', array['un appareil photo numérique','un simple tableau accroche au mur','rien de particulier, il mémorise tout']::text[], null, 27441, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27447, 'cm2', 'lecture', 'Que récolte finalement précisément Bruno à la toute fin de l''été ?', 'ses premières tomates bien rouges et juteuses', array['des tomates encore complètement vertes','rien du tout, les plants n''ont pas pousse','des légumes totalement différents des tomates']::text[], null, 27441, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27448, 'cm2', 'lecture', 'Que veut dire "scrupuleusement" à propos de la manière dont Bruno respecte l''espacement des trous creuses ?', 'avec une grande rigueur et une attention particulière', array['de façon relativement approximative','sans la moindre précision particulière','en improvisant totalement sans méthode']::text[], null, 27441, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27449, 'cm2', 'lecture', 'Que veut dire "meuble" à propos de la terre utilisée pour recouvrir les graines plantées ?', 'souple et particulièrement facile à travailler', array['très dure et particulièrement compacte','totalement humide et détrempée','gelée et impossible à travailler']::text[], null, 27441, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27450, 'cm2', 'lecture', 'Que veut dire "germination" à propos du début du processus de croissance de la graine plantée ?', 'le processus par lequel une graine commence à se développer', array['le moment précis de la récolte finale','la période exclusive de floraison','l''arrosage régulier des plantes existantes']::text[], null, 27441, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27451, 'cm2', 'lecture', 'Que veut dire "pousses" à propos de ce qu''observe précisément Bruno après quelques semaines d''attente ?', 'les premières petites tiges qui sortent de terre', array['les fruits déjà complètement murs','les fleurs déjà fanées et abîmées','les racines visibles à la surface']::text[], null, 27441, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27452, 'cm2', 'lecture', 'Que veut dire "juteuses" à propos des tomates finalement récoltées par Bruno cet été-là ?', 'pleines de jus et particulièrement savoureuses', array['totalement sèches et sans saveur','encore vertes et particulièrement dures','sans le moindre goût particulier']::text[], null, 27441, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27453, 'cm2', 'lecture', 'Que veut dire "croquis" à propos de ce que dessine Bruno dans son petit carnet personnel ?', 'de simples dessins rapides représentant une observation', array['des textes écrits particulièrement longs','des photographies imprimées et collées','des formules mathématiques complexes']::text[], null, 27441, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27454, 'cm2', 'lecture', 'Pourquoi précisément papi insiste-t-il sur le respect exact de l''espacement entre les graines plantées ?', 'chaque plante a besoin de suffisamment d''espace disponible pour bien se développer', array['c''est une simple règle esthétique sans conséquence réelle sur la croissance','cela permet simplement de gagner du temps lors de la plantation','Bruno le demande spécifiquement pour s''amuser durant la plantation']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27455, 'cm2', 'lecture', 'Pourquoi précisément Bruno doit-il veiller à ne pas trop arroser les graines fraîchement plantées dans le sol ?', 'un excès d''eau pourrait endommager gravement ces graines particulièrement fragiles', array['l''eau coûte particulièrement cher et il faut l''économiser','papi n''apprécie pas de voir de l''eau stagner dans le potager','cela n''a en réalité aucune importance réelle pour la croissance future']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27456, 'cm2', 'lecture', 'Pourquoi précisément Bruno revient-il régulièrement observer ses plants durant plusieurs semaines consécutives ?', 'il se montre passionne par le processus de croissance qu''il a lui-même initie et suivi', array['papi l''oblige explicitement à vérifier le potager chaque semaine sans exception','il a en réalité peur que quelqu''un vole ses propres plants','il n''a simplement rien d''autre à faire durant ses week-ends']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27457, 'cm2', 'lecture', 'Pourquoi précisément Bruno tient-il un petit carnet pour suivre l''évolution de ses plants au fil du temps ?', 'il souhaite garder une trace précise et personnelle de chaque étape de cette expérience vécue', array['sa maîtresse d''école le lui a explicitement demandé pour un devoir','papi l''oblige à documenter chaque étape sans exception aucune','il n''a en réalité rien d''autre à faire de son temps libre']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27458, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que Bruno est particulièrement fier du résultat obtenu à la fin de l''été ?', 'il se montre extrêmement fier d''avoir suivi personnellement tout le processus jusqu''à la récolte finale', array['il trouve finalement les tomates obtenues plutôt décevantes','il regrette globalement d''avoir commencé ce projet personnel','il préfère clairement acheter des tomates directement au marche']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27459, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Bruno et son papi à travers cette activité de jardinage partagée ?', 'papi transmet avec patience un savoir-faire particulièrement précieux à son petit-fils', array['papi se contente simplement de donner des ordres sans jamais rien expliquer','Bruno n''est en réalité pas vraiment intéressé par le jardinage propose','cette activité crée en réalité des tensions manifestes entre eux deux']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27460, 'cm2', 'lecture', 'Que peut-on déduire de l''avenir probable de Bruno concernant sa pratique future du jardinage ?', 'il pourrait très bien continuer à jardiner en grandissant, ayant développe un véritable intérêt', array['il abandonnera sûrement cette activité des la rentrée scolaire suivante','il n''aime en réalité pas vraiment jardiner malgré les apparences observées','il préfère nettement d''autres activités que celle du jardinage propose']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27461, 'cm2', 'lecture', 'Que peut-on déduire globalement de la fierté partagée par toute la famille lors de la dégustation de cette première récolte ?', 'elle valorise le travail personnel de Bruno et renforce les liens familiaux existants', array['cette dégustation n''a finalement aucune signification particulière pour la famille','seul Bruno retire une réelle satisfaction de ce moment partage','la famille se montre globalement indifférente au travail accompli par Bruno']::text[], null, 27441, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27463, 'cm2', 'lecture', 'Où précisément Inès se rend-elle avec l''ensemble de sa classe ?', 'au musée d''histoire naturelle', array['au musée d''art moderne de la ville','directement au zoo de sa région','à la bibliothèque municipale']::text[], null, 27462, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27464, 'cm2', 'lecture', 'Qui précisément accueille les élèves dès leur arrivée à l''entrée du musée ?', 'un guide', array['uniquement le directeur du musée','leur propre maîtresse de classe','personne ne les accueille réellement']::text[], null, 27462, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27465, 'cm2', 'lecture', 'Que voit précisément Inès dès son entrée dans la toute première salle visitée ?', 'un immense squelette de dinosaure', array['de simples tableaux particulièrement anciens','des animaux vivants en cage','une collection variée de coquillages']::text[], null, 27462, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27466, 'cm2', 'lecture', 'Comment précisément les scientifiques reconstituent-ils un squelette selon les explications du guide ?', 'à partir de fragments d''os retrouvés lors de fouilles', array['en dessinant simplement une forme totalement imaginaire','en utilisant uniquement d''anciennes photographies','ils ne reconstituent en réalité jamais de squelette complet']::text[], null, 27462, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27467, 'cm2', 'lecture', 'Que voit précisément Inès dans la salle consacrée aux minéraux et pierres précieuses ?', 'une magnifique améthyste violette', array['un diamant particulièrement célèbre','uniquement des pierres de couleur grise','aucune pierre précieuse particulière']::text[], null, 27462, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27468, 'cm2', 'lecture', 'À quoi précisément les élèves participent-ils vers la toute fin de cette visite guidée ?', 'un atelier interactif avec de vraies répliques de fossiles', array['un simple spectacle de danse organise','un quiz écrit réalise individuellement','un goûter offert gracieusement par le musée']::text[], null, 27462, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27469, 'cm2', 'lecture', 'Que veut dire "fragments" à propos des morceaux d''os retrouvés par les scientifiques lors des fouilles ?', 'des morceaux, des parties d''un ensemble plus grand', array['des objets entiers et parfaitement complets','de simples empreintes laissées dans le sol','des dessins représentant fidèlement des os']::text[], null, 27462, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27470, 'cm2', 'lecture', 'Que veut dire "archéologiques" à propos des fouilles évoquées précisément par le guide du musée ?', 'relatives à l''étude scientifique des vestiges du passe', array['relatives à l''étude précise des étoiles','relatives à la cuisine traditionnelle ancienne','relatives aux sports pratiques autrefois']::text[], null, 27462, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27471, 'cm2', 'lecture', 'Que veut dire "scintillent" à propos des cristaux de l''améthyste observée par Inès ?', 'brillent par de multiples reflets de lumière', array['restent totalement ternes et sans éclat','changent constamment et rapidement de couleur','sont totalement invisibles à l''oeil nu']::text[], null, 27462, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27472, 'cm2', 'lecture', 'Que veut dire "enrichissante" à propos de l''expérience vécue par Inès durant l''atelier interactif propose ?', 'qui apporte de nouvelles connaissances particulièrement utiles', array['totalement inutile sur le plan éducatif','ennuyeuse et particulièrement sans intérêt','dangereuse pour l''ensemble des enfants présents']::text[], null, 27462, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27473, 'cm2', 'lecture', 'Que veut dire "minutieuses" à propos des fouilles archéologiques évoquées par le guide du musée ?', 'réalisées avec beaucoup de précision et un soin particulier', array['faites très rapidement sans aucune attention','totalement improvisées sans méthode précise','réalisées uniquement par pur hasard']::text[], null, 27462, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27474, 'cm2', 'lecture', 'Que veut dire "fossilisés" à propos des restes anciens présentes durant l''atelier interactif ?', 'transformes en pierre au fil du temps par un processus naturel', array['récemment découverts dans la nature environnante','artificiellement fabriqués par des scientifiques','totalement invisibles sans équipement spécial']::text[], null, 27462, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27475, 'cm2', 'lecture', 'Pourquoi précisément Inès pose-t-elle plusieurs questions curieuses au guide tout au long de la visite ?', 'elle se montre passionnée par le sujet aborde et souhaite approfondir ses connaissances personnelles', array['elle s''ennuie visiblement et cherche uniquement à faire passer le temps','sa propre maîtresse l''oblige explicitement à poser dès questions précises','elle n''a en réalité pas compris les explications données par le guide']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27476, 'cm2', 'lecture', 'Pourquoi précisément le squelette de dinosaure impressionne-t-il autant Inès dès son arrivée dans la salle ?', 'sa taille réelle dépasse largement ce qu''elle avait pu imaginer avant de le voir directement', array['elle avait déjà vu ce même squelette à plusieurs reprises auparavant','elle a en réalité une peur persistante des animaux disparus en général','le guide l''a décrit de manière particulièrement effrayante avant l''entrée']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27477, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que Inès à particulièrement appreci l''atelier propose avec les fossiles ?', 'elle trouve cette expérience particulièrement enrichissante et mémorable pour elle', array['elle refuse catégoriquement d''y participer dès le début','elle s''ennuie manifestement pendant l''intégralité de cet atelier','elle préfère nettement retourner voir uniquement les dinosaures']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27478, 'cm2', 'lecture', 'Pourquoi précisément le guide explique-t-il aux élèves comment différencier un vrai fossile d''une simple pierre ?', 'il souhaite approfondir leur compréhension scientifique et satisfaire leur curiosité naturelle', array['cette explication n''a en réalité aucun lien avec le reste de la visite guidée','les élèves l''exigent explicitement avant de continuer la visite','c''est une information sans réel intérêt pour de jeunes enfants']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27479, 'cm2', 'lecture', 'Pourquoi précisément Inès achète-t-elle une carte postale du squelette de dinosaure plutôt qu''un autre objet ?', 'cette image représente ce qui l''a le plus marquée durant l''ensemble de cette visite guidée', array['c''est en réalité le seul objet disponible à la boutique du musée','sa propre maîtresse le lui impose explicitement avant de partir','elle n''a en réalité pas assez d''argent pour acheter autre chose']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27480, 'cm2', 'lecture', 'Que peut-on déduire de l''attitude générale d''Inès tout au long de cette visite particulière au musée ?', 'elle fait preuve d''une grande curiosité et d''un véritable intérêt scientifique sincère', array['elle s''ennuie manifestement du tout début jusqu''à la toute fin de la visite','elle préférerait clairement être restée simplement à l''école ce jour-là','elle ne retient en réalité aucune information de cette sortie particulière']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27481, 'cm2', 'lecture', 'Pourquoi précisément Inès partage-t-elle ses découvertes avec ses camarades sur le chemin du retour vers l''école ?', 'elle souhaite sincèrement transmettre l''enthousiasme et les connaissances qu''elle vient d''acquérir', array['sa maîtresse l''oblige explicitement à faire ce récit détaille à tous','elle n''a en réalité rien d''autre à faire durant ce trajet de retour','elle cherche uniquement à impressionner ses propres camarades de classe']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27482, 'cm2', 'lecture', 'Que peut-on déduire de l''objectif pédagogique global poursuivi par cette sortie scolaire organisée au musée ?', 'elle vise à éveiller durablement la curiosité scientifique des élèves de manière concrète et vivante', array['elle sert uniquement à occuper une simple journée de classe sans réel objectif','elle n''entretient en réalité aucun lien avec le programme scolaire habituel','elle est organisée uniquement dans le but de récompenser certains élèves précis']::text[], null, 27462, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27484, 'cm2', 'lecture', 'Avec qui précisément Lucas passe-t-il cette journée entière au zoo ?', 'ses parents et sa petite soeur', array['l''ensemble de sa classe scolaire','uniquement ses grands-parents','il y va entièrement seul']::text[], null, 27483, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27485, 'cm2', 'lecture', 'Par quel pavillon précisément la famille commence-t-elle sa visite guidée du zoo ?', 'le pavillon des grands félins', array['le pavillon réserve aux oiseaux','le pavillon dédie aux reptiles','le pavillon consacre aux poissons']::text[], null, 27483, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27486, 'cm2', 'lecture', 'Que fait précisément le lion observe attentivement par Lucas au tout début de la visite ?', 'il se prélasse paresseusement au soleil', array['il rugit de manière constante et forte','il court rapidement dans son enclos','il dort profondément dans une grotte']::text[], null, 27483, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27487, 'cm2', 'lecture', 'Qui précisément nourrit les otaries devant l''ensemble du public présent ?', 'un soigneur expérimente', array['un simple visiteur volontaire','personne, elles se nourrissent seules','un vétérinaire spécialement appelé']::text[], null, 27483, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27488, 'cm2', 'lecture', 'Où précisément la famille de Lucas déjeune-t-elle vers midi durant cette visite ?', 'près de l''enclos des girafes', array['près du pavillon des grands félins','directement à l''extérieur du zoo','dans un restaurant situe hors du parc']::text[], null, 27483, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27489, 'cm2', 'lecture', 'Que fait précisément Lucas dans l''espace interactif propose durant l''après-midi ?', 'il hésite avant de toucher un serpent docile', array['il refuse catégoriquement d''y participer','il touche immédiatement tous les animaux sans hésiter','il décide de ne pas se rendre dans cet espace']::text[], null, 27483, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27490, 'cm2', 'lecture', 'Que veut dire "se prélasser" à propos du lion observe attentivement au soleil par Lucas ?', 'se détendre paresseusement en profitant du confort', array['courir à une très grande vitesse','chercher activement de la nourriture disponible','se cacher précipitamment par peur']::text[], null, 27483, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27491, 'cm2', 'lecture', 'Que veut dire "agiles" à propos des otaries observées dans l''eau par toute la famille ?', 'capables de mouvements rapides et particulièrement souples', array['lentes et particulièrement maladroites dans leurs déplacements','totalement immobiles la plupart du temps','fragiles et visiblement malades']::text[], null, 27483, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27492, 'cm2', 'lecture', 'Que veut dire "docile" à propos du serpent finalement touche par Lucas dans l''espace interactif ?', 'calme et particulièrement facile à manipuler sans danger', array['agressif et particulièrement dangereux pour l''homme','totalement sauvage et parfaitement imprévisible','venimeux et potentiellement mortel pour l''homme']::text[], null, 27483, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27493, 'cm2', 'lecture', 'Que veut dire "écosystème" à propos du rôle joue par le serpent dans son environnement naturel ?', 'l''ensemble des relations entre les êtres vivants et leur milieu naturel', array['un simple enclos artificiel aménagé pour les visiteurs','une espèce particulière d''animal rare et menace','un type de nourriture spécifique donnée aux animaux']::text[], null, 27483, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27494, 'cm2', 'lecture', 'Que veut dire "majestueux" à propos des lions et tigres observés par Lucas dès le début de la visite ?', 'impressionnants par leur prestance et leur allure naturelle', array['petits et particulièrement discrets dans leur enclos','effrayes et manifestement caches du public','malades et visiblement affaiblis physiquement']::text[], null, 27483, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27495, 'cm2', 'lecture', 'Que veut dire "spectaculaire" à propos de la réussite des otaries attrapant habilement les poissons lancés ?', 'qui impressionne fortement l''ensemble des spectateurs présents', array['totalement banale et particulièrement sans intérêt','invisible complètement pour le public rassemble','dangereuse pour les animaux présents dans le bassin']::text[], null, 27483, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27496, 'cm2', 'lecture', 'Pourquoi précisément Lucas applaudit-il à chaque réussite des otaries pendant tout le spectacle propose ?', 'il se montre véritablement impressionné par leur agilité et leur intelligence naturelle', array['c''est en réalité une règle explicitement imposée par le soigneur présent','il cherche simplement à imiter le comportement des autres visiteurs présents','il s''ennuie profondément et cherche uniquement à passer le temps']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27497, 'cm2', 'lecture', 'Pourquoi précisément la famille de Lucas choisit-elle de déjeuner près de l''enclos des girafes ce jour-là ?', 'cela leur permet d''observer agréablement ces animaux tout en se restaurant ensemble', array['c''est en réalité le seul endroit disponible pour manger dans tout le zoo','les girafes attirent généralement moins de visiteurs à cette heure précise','ils n''avaient tout simplement pas prévu de déjeuner ailleurs ce jour-là']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27498, 'cm2', 'lecture', 'Pourquoi précisément Lucas hésite-t-il avant de toucher le serpent présente dans l''espace interactif du zoo ?', 'il ressent une appréhension naturelle malgré le caractère totalement inoffensif de l''animal présente', array['il a déjà été mordu par un serpent lors d''une expérience antérieure','le soigneur présent le lui déconseille fortement dès le début','il n''apprécie en réalité pas du tout les animaux en général']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27499, 'cm2', 'lecture', 'Pourquoi précisément le soigneur explique-t-il à Lucas le rôle écologique important joue par ce serpent particulier ?', 'il souhaite sensibiliser les enfants à l''importance de chaque espèce dans son propre environnement naturel', array['cette explication n''a en réalité aucun lien réel avec le reste de la visite guidée','Lucas l''interroge avec une insistance particulière sur ce sujet précis','c''est une information totalement inutile pour de jeunes visiteurs']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27500, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que Lucas à particulièrement appreci cette journée passée au zoo avec sa famille ?', 'il raconte déjà avec un enthousiasme évident les animaux qu''il souhaite absolument revoir', array['il s''ennuie manifestement du tout début jusqu''à la toute fin de cette visite','il refuse catégoriquement de reparler de cette journée particulière par la suite','il préférerait clairement ne jamais y retourner à l''avenir']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27501, 'cm2', 'lecture', 'Que peut-on déduire de l''intérêt manifeste de Lucas pour les animaux à travers l''ensemble de cette sortie vécue ?', 'il se révèle passionne et curieux de découvrir la nature et les animaux qui l''entourent', array['il a en réalité une peur persistante des animaux en général','il s''ennuie visiblement devant la plupart des enclos visites','il préfère nettement uniquement les animaux domestiques familiers']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27502, 'cm2', 'lecture', 'Pourquoi précisément Lucas dessine-t-il déjà mentalement les animaux observés sur le chemin du retour en voiture ?', 'cette expérience marquante nourrit son imagination et sa créativité artistique personnelle', array['il n''a en réalité rien d''autre à faire durant ce trajet de retour','ses parents l''obligent explicitement à réaliser ce type d''exercice créatif','il cherche uniquement à se souvenir des noms exacts des animaux observés']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27503, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''organisation minutieuse de cette sortie familiale par les parents de Lucas ?', 'ils ont planifié une journée particulièrement riche en découvertes pour l''ensemble de la famille', array['ils ont en réalité improvise cette sortie au tout dernier moment possible','ils n''accordent finalement pas une grande importance à ce type de sortie','ils préféreraient globalement que les enfants restent simplement à la maison']::text[], null, 27483, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27505, 'cm2', 'lecture', 'Quand précisément Marta se promène-t-elle habituellement en forêt avec son papa ?', 'chaque dimanche matin', array['chaque samedi soir uniquement','seulement pendant les vacances scolaires','une seule fois par mois environ']::text[], null, 27504, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27506, 'cm2', 'lecture', 'De quelle couleur précisément sont les feuilles recouvrant le chemin ce dimanche d''automne ?', 'du jaune dore au brun particulièrement profond', array['toutes entièrement vertes','toutes entièrement blanches','toutes rouges uniquement']::text[], null, 27504, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27507, 'cm2', 'lecture', 'Que fait précisément Marta avec les feuilles qu''elle ramasse durant cette promenade ?', 'elle les glisse dans un carnet pour les faire sécher', array['elle les jette immédiatement après les avoir ramassées','elle les donne directement à son papa','elle les laisse simplement sur le chemin parcouru']::text[], null, 27504, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27508, 'cm2', 'lecture', 'Quel animal précisément traverse soudainement le sentier devant Marta et son papa ?', 'un renard roux', array['un sanglier particulièrement imposant','un cerf majestueux','un simple lapin des bois']::text[], null, 27504, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27509, 'cm2', 'lecture', 'Que fait précisément cet animal juste après avoir traversé rapidement le sentier ?', 'il disparaît rapidement dans les fourres', array['il s''approche directement de Marta','il reste immobile pendant longtemps','il suit Marta et son papa durant la promenade']::text[], null, 27504, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27510, 'cm2', 'lecture', 'Depuis combien de temps précisément le chêne observe est-il plante selon les explications du papa ?', 'plus de deux cents ans', array['environ dix ans seulement','cinquante ans à peine','on ne le sait en réalité pas du tout']::text[], null, 27504, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27511, 'cm2', 'lecture', 'Que veut dire "fourres" à propos de l''endroit précis où disparaît le renard observe ?', 'des buissons particulièrement denses et touffus', array['des trous particulièrement profonds dans le sol','des rochers pointus et dangereux','de simples flaques d''eau stagnante']::text[], null, 27504, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27512, 'cm2', 'lecture', 'Que veut dire "crépuscule" à propos du moment où le renard est habituellement le plus actif ?', 'le moment de transition entre le jour et la nuit', array['le milieu exact de la journée','le milieu précis de la nuit','le lever du soleil uniquement']::text[], null, 27504, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27513, 'cm2', 'lecture', 'Que veut dire "rugueuse" à propos de l''écorce du chêne touchée par Marta ce jour-là ?', 'rude et particulièrement irrégulière au toucher', array['totalement lisse et particulièrement douce','collante et visiblement humide','glacée et particulièrement froide']::text[], null, 27504, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27514, 'cm2', 'lecture', 'Que veut dire "inattendue" à propos de la rencontre soudaine avec le renard observe ?', 'surprenante, que l''on n''attendait absolument pas', array['prévue depuis longtemps à l''avance','totalement banale et particulièrement habituelle','organisée volontairement par le papa de Marta']::text[], null, 27504, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27515, 'cm2', 'lecture', 'Que veut dire "discret" à propos du renard décrit précisément par le papa de Marta ?', 'qui se fait remarquer le moins possible', array['qui attire toujours l''attention générale','qui se montre particulièrement bruyant','qui vit exclusivement en groupe nombreux']::text[], null, 27504, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27516, 'cm2', 'lecture', 'Que veut dire "offrandes" à propos de ce que déposaient autrefois les anciens habitants près du chêne ?', 'des présents symboliques offerts lors d''une cérémonie', array['de simples déchets abandonnes sans raison','des outils de travail quotidien','des vêtements uses et abîmes']::text[], null, 27504, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27517, 'cm2', 'lecture', 'Pourquoi précisément Marta reste-t-elle totalement immobile en voyant le renard traverser le sentier ?', 'elle ne souhaite surtout pas effrayer l''animal et cherche à prolonger cette observation rare', array['elle ressent en réalité une très grande peur face à cet animal','son papa le lui ordonne strictement des cet instant précis','elle ne remarque en réalité pas vraiment la présence de cet animal']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27518, 'cm2', 'lecture', 'Pourquoi précisément le papa de Marta insiste-t-il sur le caractère rare de cette rencontre avec le renard ?', 'il souhaite faire comprendre à sa fille la chance particulière qu''ils ont eue d''observer cet animal discret', array['il a en réalité peur que Marta ne le croie absolument pas','c''est la toute première fois qu''il observe lui-même un renard','il cherche uniquement à effrayer Marta pour qu''elle reste prudente']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27519, 'cm2', 'lecture', 'Pourquoi précisément Marta essaie-t-elle d''imaginer les générations passées devant ce chêne si impressionnant ?', 'l''âge particulièrement impressionnant de l''arbre l''amène naturellement à réfléchir au temps qui passe', array['son papa lui pose directement cette question précise à cet instant','elle s''ennuie visiblement et cherche uniquement à s''occuper l''esprit','elle a lu une histoire précise concernant ce chêne en particulier']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27520, 'cm2', 'lecture', 'Pourquoi précisément le papa de Marta choisit-il de raconter la légende du chêne à ce moment précis de la promenade ?', 'il souhaite enrichir l''expérience de sa fille en lui transmettant l''histoire locale liée a ce lieu', array['cette légende n''a en réalité aucun lien réel avec le chêne observe','Marta l''interroge avec une insistance particulière à ce sujet précis','il n''a en réalité rien d''autre à raconter durant cette promenade']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27521, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que cette promenade hebdomadaire représente un moment important pour la jeune Marta ?', 'elle collectionne des souvenirs précis et se montre impatiente de les partager avec ses camarades', array['elle participe uniquement par obligation envers son propre papa','elle oublie systématiquement ce qu''elle a pu observer en forêt','elle préférerait clairement faire autre chose chaque dimanche matin']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27522, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Marta et son papa à travers cette habitude partagée chaque semaine ?', 'ils cultivent ensemble une complicité durable autour de leur intérêt commun pour la nature environnante', array['ils se voient en réalité très rarement en dehors de ces promenades dominicales','Marta n''apprécie en réalité pas vraiment ces sorties dominicales proposées','le papa emmène Marta uniquement par obligation familiale ressentie']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27523, 'cm2', 'lecture', 'Que peut-on déduire de l''intérêt grandissant de Marta pour l''histoire et les légendes locales à travers cette histoire ?', 'elle développe une curiosité nouvelle pour le patrimoine culturel et naturel de sa propre région', array['elle s''intéresse en réalité uniquement aux animaux rencontres en forêt','elle n''apprend finalement rien de nouveau lors de ces sorties dominicales','elle préférerait clairement explorer la forêt entièrement seule sans son papa']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27524, 'cm2', 'lecture', 'Que peut-on déduire globalement du rôle joue par ces promenades hebdomadaires dans l''éducation personnelle de Marta ?', 'elles nourrissent sa curiosité naturelle tout en renforçant durablement son lien avec son papa', array['elles n''ont finalement aucune influence particulière sur son propre développement','elles représentent en réalité une contrainte plutôt subie que choisie','elles n''apportent rien de plus que de simples moments de détente physique']::text[], null, 27504, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27526, 'cm2', 'lecture', 'Où précisément Julian passe-t-il plusieurs jours entiers chaque été ?', 'à la ferme de son papi', array['chez ses propres cousins','directement au bord de la mer','dans une colonie de vacances organisée']::text[], null, 27525, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27527, 'cm2', 'lecture', 'Où précisément Julian est-il assis ce matin-là durant les moissons ?', 'dans la cabine du tracteur aux côtés de son papi', array['sur un simple banc près du champ','dans la maison de son papi','directement sur la moissonneuse-batteuse elle-même']::text[], null, 27525, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27528, 'cm2', 'lecture', 'Que fait précisément la moissonneuse-batteuse en avançant à travers le champ de blé ?', 'elle coupe les tiges de blé avec précision', array['elle plante de nouvelles graines de blé','elle arrose simplement le champ existant','elle transporte le lait des vaches présentes']::text[], null, 27525, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27529, 'cm2', 'lecture', 'Quels animaux précisément jaillissent des rangs de blé effrayes par le bruit du moteur ?', 'des lièvres et des perdrix', array['des vaches et des moutons','de simples chevaux présents','des oiseaux migrateurs de passage']::text[], null, 27525, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27530, 'cm2', 'lecture', 'Que propose spontanément Julian à son papi en remarquant sa fatigue après la matinée de travail ?', 'son aide pour les taches plus légères de l''après-midi', array['de rentrer immédiatement à la maison','d''appeler quelqu''un d''autre pour aider','de reporter le travail au lendemain']::text[], null, 27525, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27531, 'cm2', 'lecture', 'Que confie précisément papi à Julian pendant qu''il se repose un peu à l''ombre ?', 'surveiller le bon fonctionnement de la machine', array['conduire lui-même le tracteur','préparer le repas du soir','s''occuper des autres animaux de la ferme']::text[], null, 27525, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27532, 'cm2', 'lecture', 'Que veut dire "méthodiquement" à propos de la manière dont avance précisément la moissonneuse-batteuse ?', 'de façon organisée et particulièrement régulière', array['de manière totalement désordonnée','très lentement et sans but précis','en s''arrêtant fréquemment sans raison apparente']::text[], null, 27525, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27533, 'cm2', 'lecture', 'Que veut dire "jaillissent" à propos des lièvres et perdrix sortant soudainement du champ de blé ?', 'surgissent brusquement et particulièrement rapidement', array['avancent très lentement et progressivement','restent totalement immobiles assez longtemps','disparaissent silencieusement sans être remarques']::text[], null, 27525, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27534, 'cm2', 'lecture', 'Que veut dire "confectionnent" à propos de la fabrication quotidienne du pain par les boulangers évoquée ?', 'fabriquent, réalisent avec un soin particulier', array['détruisent complètement un produit existant','achètent simplement tout déjà prépare','refusent catégoriquement de préparer quoi que ce soit']::text[], null, 27525, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27535, 'cm2', 'lecture', 'Que veut dire "convivial" à propos du repas partage en famille à l''ombre de l''arbre ce jour-là ?', 'chaleureux et particulièrement agréable à partager ensemble', array['froid et particulièrement silencieux','très bref et visiblement presse','réserve exclusivement aux adultes présents']::text[], null, 27525, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27536, 'cm2', 'lecture', 'Que veut dire "élargie" à propos de la famille de Julian réunie ce jour-là à l''heure du repas ?', 'comprenant plusieurs générations et branches de la famille', array['réduite au strict minimum nécessaire','composée uniquement des parents et de Julian','totalement absente ce jour-là précis']::text[], null, 27525, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27537, 'cm2', 'lecture', 'Que veut dire "généreuse" à propos de la proposition d''aide spontanément formulée par Julian ?', 'faite avec bienveillance et sans rien attendre en retour', array['faite uniquement par pure obligation ressentie','faite avec une certaine réticence visible','faite uniquement pour obtenir une récompense précise']::text[], null, 27525, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27538, 'cm2', 'lecture', 'Pourquoi précisément Julian pose-t-il tant de questions à son papi sur le fonctionnement de la machine agricole ?', 'il se montre fascine par cette technologie agricole particulièrement impressionnante à ses yeux', array['il doit impérativement remplir un questionnaire précis pour l''école','il s''ennuie visiblement et cherche uniquement à faire durer le trajet','son papi l''y oblige constamment durant toute la matinée']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27539, 'cm2', 'lecture', 'Pourquoi précisément les lièvres et perdrix fuient-ils si rapidement le champ de blé cultive ?', 'le bruit particulièrement puissant du moteur les effraie fortement', array['ils cherchent en réalité de la nourriture ailleurs volontairement','papi les chasse expressément avec le tracteur utilise','ils suivent simplement d''autres animaux présents dans le champ']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27540, 'cm2', 'lecture', 'Pourquoi précisément papi explique-t-il à Julian tout le cheminement du grain jusqu''au pain consomme ?', 'il souhaite lui faire comprendre l''origine concrète des aliments qu''il consomme quotidiennement', array['c''est une information sans grand intérêt réel pour un jeune enfant','Julian a posé une question totalement différente à ce sujet','il n''a en réalité rien d''autre à lui expliquer durant le trajet']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27541, 'cm2', 'lecture', 'Pourquoi précisément Julian propose-t-il spontanément son aide en remarquant la fatigue de son papi ?', 'il fait preuve d''une attention sincère envers son papi et souhaite alléger sa charge de travail', array['son papi le lui demande explicitement à ce moment précis','il n''a en réalité rien d''autre à faire durant cette après-midi','il cherche uniquement à impressionner le reste de sa famille présente']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27542, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que Julian est particulièrement fier d''avoir participé aux moissons ce jour-là ?', 'il s''endort épuise mais très fier, impatient de raconter cette expérience à ses camarades', array['il regrette visiblement d''avoir passé sa journée entière à la ferme','il ne souhaite plus jamais retourner à la ferme de son papi','il oublie finalement rapidement cette journée particulière vécue']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27543, 'cm2', 'lecture', 'Que peut-on déduire de l''importance de cette tradition estivale des moissons pour le jeune Julian ?', 'elle représente un moment particulièrement fort et attendu chaque année dans sa propre vie', array['elle n''a en réalité pas vraiment d''importance particulière pour lui','il préférerait globalement passer ses êtes d''une autre manière','cette tradition n''existe en réalité que depuis cette année précise']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27544, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Julian et son papi à travers cette journée de moisson particulière ?', 'ils partagent une véritable complicité autour du travail commun réalise à la ferme', array['ils se voient en réalité rarement en dehors de la période des moissons','Julian n''apprécie en réalité pas vraiment accompagner son papi','papi préfère clairement travailler seul sans la présence de Julian']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27545, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''évolution de la relation entre Julian et son papi au fil de cette journée précise ?', 'elle se renforce grâce à l''entraide spontanée manifestée par Julian envers son papi fatigué', array['elle reste totalement identique du tout début jusqu''à la toute fin de la journée','elle se dégrade progressivement au fil des heures passées ensemble','cette journée n''a finalement aucun effet particulier sur leur relation existante']::text[], null, 27525, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27547, 'cm2', 'lecture', 'Que découvre précisément Erik en se réveillant ce matin d''hiver particulier ?', 'le jardin recouvert d''un épais manteau de neige', array['un jardin totalement inonde par la pluie','un jardin simplement recouvert de feuilles mortes','rien de particulier à signaler ce matin-là']::text[], null, 27546, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27548, 'cm2', 'lecture', 'Que fait précisément Erik avant de sortir affronter le froid dans le jardin ?', 'il enfile plusieurs couches de vêtements chauds', array['il reste simplement en pyjama toute la matinée','il met uniquement un manteau particulièrement léger','il ne se prépare pas particulièrement avant de sortir']::text[], null, 27546, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27549, 'cm2', 'lecture', 'Combien précisément de boules de neige Erik empile-t-il au total pour son bonhomme ?', 'trois', array['seulement deux boules','cinq boules distinctes','une seule boule unique']::text[], null, 27546, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27550, 'cm2', 'lecture', 'Qu''utilise précisément Erik pour former les yeux de son bonhomme de neige ?', 'deux morceaux de charbon', array['de simples boutons colorés','deux cailloux particulièrement blancs','deux pièces de monnaie']::text[], null, 27546, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27551, 'cm2', 'lecture', 'Que propose précisément l''un des voisins à Erik en admirant son bonhomme de neige ?', 'de photographier ensemble le bonhomme pour le journal local', array['de détruire immédiatement cette création','d''acheter le bonhomme de neige réalise','de construire un autre bonhomme différent']::text[], null, 27546, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27552, 'cm2', 'lecture', 'Que découvre précisément Erik le lendemain matin concernant son bonhomme de neige ?', 'il a résisté au dégel malgré le temps écoulé', array['il a complètement fondu durant la nuit','il a été détruit par un animal quelconque','il a été déplace par un voisin curieux']::text[], null, 27546, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27553, 'cm2', 'lecture', 'Que veut dire "immaculée" à propos de la neige fraîchement tombée dans le jardin ce matin-là ?', 'totalement blanche et particulièrement sans tache', array['sale et visiblement grisâtre','en train de fondre particulièrement rapidement','mélangée à de la boue existante']::text[], null, 27546, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27554, 'cm2', 'lecture', 'Que veut dire "décroissante" à propos de la taille des boules empilées successivement par Erik ?', 'qui diminue progressivement d''une boule à l''autre', array['qui augmente progressivement d''une boule à l''autre','qui reste rigoureusement identique à chaque fois','qui varie complètement au hasard sans logique']::text[], null, 27546, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27555, 'cm2', 'lecture', 'Que veut dire "généreusement" à propos de la manière dont la maman prête précisément ses propres affaires ?', 'avec beaucoup de bonne volonté, sans rien compter', array['avec une grande réticence particulièrement visible','en exigeant explicitement quelque chose en retour','en se plaignant fortement de la demande formulée']::text[], null, 27546, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27556, 'cm2', 'lecture', 'Que veut dire "persiste" à propos du froid qu''Erik espère sincèrement voir durer plus longtemps ?', 'continue, se maintient durablement dans le temps', array['disparaît totalement et immédiatement','diminue particulièrement rapidement','n''a en réalité jamais existe réellement']::text[], null, 27546, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27557, 'cm2', 'lecture', 'Que veut dire "convenablement" à propos de la manière dont Erik habille finalement son bonhomme de neige ?', 'de façon appropriée et particulièrement satisfaisante', array['de façon négligée et visiblement bacleé','de manière excessive et particulièrement exagérée','sans le moindre soin particulier apporte']::text[], null, 27546, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27558, 'cm2', 'lecture', 'Que veut dire "dégel" à propos du phénomène que le bonhomme de neige d''Erik parvient à résister ?', 'la fonte progressive de la neige et de la glace', array['une nouvelle chute de neige abondante','un simple changement de vent ressenti','une augmentation de la luminosité ambiante']::text[], null, 27546, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27559, 'cm2', 'lecture', 'Pourquoi précisément Erik enfile-t-il plusieurs couches de vêtements avant de sortir dans le jardin ?', 'il sait qu''il va passer beaucoup de temps dehors dans le froid pour construire son bonhomme', array['sa maman l''y oblige explicitement sans raison particulière apparente','il a en réalité déjà froid à l''intérieur même de sa propre maison','c''est une règle qu''il doit systématiquement suivre chaque matin sans exception']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27560, 'cm2', 'lecture', 'Pourquoi précisément Erik tasse-t-il soigneusement chaque étage de son bonhomme de neige au fur et à mesure ?', 'il souhaite garantir efficacement la stabilité de sa construction face au vent qui souffle', array['il n''a en réalité rien d''autre à faire de son temps libre ce jour-là','sa maman le lui demande explicitement de procéder ainsi','il pense simplement que cela rendra son bonhomme plus joli visuellement']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27561, 'cm2', 'lecture', 'Pourquoi précisément les voisins s''arrêtent-ils devant la maison d''Erik pour observer sa création ?', 'ils se montrent particulièrement impressionnés par la qualité de sa création hivernale réalisée', array['ils cherchent simplement à discuter avec les parents d''Erik présents','ils veulent en réalité se plaindre du bruit occasionne','ils passent simplement par hasard sans remarquer particulièrement le bonhomme']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27562, 'cm2', 'lecture', 'Pourquoi précisément le voisin propose-t-il de partager la photo du bonhomme dans le journal local du quartier ?', 'il souhaite sincèrement valoriser auprès de tous le talent créateur manifeste par le jeune Erik', array['il n''a en réalité aucune autre photo disponible à publier cette semaine','il cherche uniquement à se faire bien voir des parents d''Erik','c''est une obligation régulière imposée par ce journal local']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27563, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement qu''Erik est particulièrement attache à sa propre création le soir venu ?', 'il l''observe longuement depuis sa fenêtre en espérant sincèrement qu''elle dure plusieurs jours', array['il oublie complètement son bonhomme dès le lendemain matin suivant','il demande explicitement à le détruire lui-même dès le soir même','il refuse catégoriquement d''en reparler avec ses propres parents']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27564, 'cm2', 'lecture', 'Que peut-on déduire du plaisir général ressenti par Erik au cours de cette journée particulière de neige ?', 'il vit un moment de joie simple et particulièrement mémorable grâce à une activité créative réussie', array['il regrette globalement d''avoir passé autant de temps dehors ce jour-là','il aurait clairement préféré rester devant les écrans toute la journée entière','cette journée ne représente en réalité rien de particulier pour lui']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27565, 'cm2', 'lecture', 'Que peut-on déduire de l''attitude de la maman d''Erik envers cette activité hivernale menée par son fils ?', 'elle encourage et soutient sincèrement son fils tout en veillant attentivement à sa sécurité', array['elle désapprouve complètement cette activité proposée par son propre fils','elle reste totalement indifférente aux activités menées par Erik','elle refuse catégoriquement de prêter le moindre objet pour le bonhomme']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27566, 'cm2', 'lecture', 'Que peut-on déduire globalement de la fierté ressentie par Erik en découvrant que son bonhomme a résisté au dégel ?', 'elle renforce durablement sa confiance en ses propres capacités créatives et manuelles', array['elle n''a en réalité aucune importance particulière à ses propres yeux','il regrette finalement d''avoir construit ce bonhomme particulier','cette découverte n''apporte finalement rien de plus à son quotidien habituel']::text[], null, 27546, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27568, 'cm2', 'lecture', 'Où précisément Mia se rend-elle pour la toute première fois de sa vie ?', 'à la patinoire municipale', array['directement à la piscine','au cinéma du quartier','au musée de sa ville']::text[], null, 27567, 'L', 'publie');
