insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27580, 'cm2', 'lecture', 'Pourquoi précisément Mia s''accroche-t-elle fermement à la barrière au tout début de sa séance de patinage ?', 'elle ressent une peur naturelle de tomber car elle débute complètement dans cette discipline nouvelle', array['elle souhaite simplement se reposer un court instant sur place','sa soeur le lui demande explicitement sans autre raison apparente','la glace présente en réalité un défaut visible à cet endroit précis']::text[], null, 27567, 'I', 'publie');
