insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27584, 'cm2', 'lecture', 'Pourquoi précisément Mia souhaite-t-elle absolument revenir la semaine suivante malgré les difficultés rencontrées ce jour-là ?', 'elle a pris un plaisir sincère malgré les chutes et souhaite continuer à progresser davantage', array['sa soeur l''y oblige fermement sans lui laisser d''autre choix','elle a simplement oublié ses propres patins et doit revenir les chercher','elle n''a en réalité pas eu suffisamment de temps pour patiner ce jour-là']::text[], null, 27567, 'I', 'publie');
