insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27617, 'cm2', 'lecture', 'Que veut dire "constellé" à propos du ciel particulièrement observé par Anna ce soir-là ?', 'parsemé d''un très grand nombre d''étoiles visibles', array['totalement vide et particulièrement sombre','recouvert entièrement de nuages épais','éclaire uniquement par la lune présente']::text[], null, 27609, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27618, 'cm2', 'lecture', 'Que veut dire "avec entrain" à propos de la manière dont Anna chante les chansons proposées ?', 'avec beaucoup d''enthousiasme et un dynamisme visible', array['avec beaucoup d''ennui particulièrement manifeste','avec une tristesse particulièrement évidente','en chuchotant à peine de manière audible']::text[], null, 27609, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27619, 'cm2', 'lecture', 'Que veut dire "mémorable" à propos de la soirée particulière vécue par Anna ce jour-là ?', 'digne d''être retenue durablement dans la mémoire personnelle', array['vite oubliée et particulièrement sans importance','pénible et particulièrement désagréable à vivre','identique à toutes les autres soirées vécues']::text[], null, 27609, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27620, 'cm2', 'lecture', 'Que veut dire "fondants" à propos des marshmallows particulièrement apprécies par Anna ce soir-là ?', 'qui deviennent mous et particulièrement coulants à l''intérieur en chauffant', array['qui restent durs et particulièrement froids','qui brûlent complètement et rapidement','qui explosent soudainement en cuisant']::text[], null, 27609, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27621, 'cm2', 'lecture', 'Que veut dire "transmise" à propos de la légende familiale racontée précisément par le grand-père ?', 'passée d''une génération à l''autre au fil du temps écoule', array['inventée tout récemment par le grand-père lui-même','trouvée simplement dans un livre à la bibliothèque locale','totalement oubliée par l''ensemble de la famille réunie']::text[], null, 27609, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27622, 'cm2', 'lecture', 'Pourquoi précisément Anna attend-elle chaque année cette soirée de feu de camp avec une impatience grandissante ?', 'c''est un moment de partage familial particulièrement chaleureux qu''elle apprécie sincèrement', array['elle n''a en réalité rien d''autre à faire pendant ces vacances spécifiques','ses parents l''y obligent explicitement chaque année sans exception','elle espère simplement pouvoir manger des marshmallows à volonté']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27623, 'cm2', 'lecture', 'Pourquoi précisément le grand-père choisit-il de raconter une légende familiale plutôt qu''une tout autre histoire ?', 'il souhaite sincèrement transmettre l''histoire et les traditions vivantes de la famille aux plus jeunes', array['il ne connaît en réalité aucune autre histoire à raconter ce soir-là','les enfants présents le lui ont demandé spécifiquement ce soir précis','c''est une obligation qu''il s''impose chaque année sans grand plaisir personnel']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27624, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement qu''Anna se sent totalement à l''aise pendant cette soirée malgré ses erreurs de paroles ?', 'elle chante avec entrain sans se soucier particulièrement de ses erreurs occasionnelles', array['elle refuse absolument de participer aux chansons proposées ce soir-là','elle quitte immédiatement le cercle dès qu''elle se trompe une fois','elle pleure de honte visible à chaque erreur commise durant les chants']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27625, 'cm2', 'lecture', 'Pourquoi précisément Anna interroge-t-elle son grand-père sur l''origine et la transmission de cette légende familiale ?', 'sa curiosité naturelle la pousse à mieux comprendre les traditions vivantes de sa propre famille', array['elle doute en réalité sérieusement de la véracité de cette histoire racontée','son grand-père l''oblige explicitement à poser cette question précise','elle cherche uniquement à faire durer la soirée plus longtemps que prévu']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27626, 'cm2', 'lecture', 'Pourquoi précisément Anna souhaite-t-elle que son grand-père écrive cette légende dans un petit carnet spécial ?', 'elle souhaite sincèrement pouvoir la transmettre elle-même à ses propres enfants dans le futur', array['sa maîtresse d''école le lui a explicitement demandé pour un devoir précis','elle craint en réalité d''oublier rapidement cette histoire particulière','ses propres parents l''obligent à réaliser cette demande spécifique']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27627, 'cm2', 'lecture', 'Que peut-on déduire de l''ambiance générale régnant lors de cette soirée particulière en famille ?', 'une atmosphère chaleureuse et particulièrement conviviale propice au partage intergénérationnel sincère', array['une atmosphère tendue entre les différents membres de la famille réunie','un ennui général ressenti manifestement par l''ensemble des participants présents','une soirée organisée uniquement pour les adultes présents ce soir-là']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27628, 'cm2', 'lecture', 'Que peut-on déduire de l''importance grandissante des traditions familiales dans la vie personnelle de la jeune Anna ?', 'elles occupent une place particulièrement précieuse et structurante dans ses propres souvenirs d''enfance', array['elles n''ont finalement aucune signification particulière à ses propres yeux','elle préférerait clairement passer ce temps seule avec des amis proches','ces traditions se révèlent en réalité récentes et sans lien avec le passe familial']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27629, 'cm2', 'lecture', 'Que peut-on déduire globalement du rôle joue par le grand-père d''Anna dans la transmission du patrimoine familial ?', 'il assure avec plaisir le passage des traditions et des souvenirs entre les différentes générations', array['il transmet ces histoires uniquement par pure obligation ressentie','il n''accorde en réalité aucune importance particulière à ces traditions familiales','il préférerait que ces légendes disparaissent progressivement avec le temps']::text[], null, 27609, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27631, 'cm2', 'lecture', 'Où précisément Félix part-il camper pour la toute première fois de sa vie ?', 'au bord d''une rivière tranquille', array['directement au bord de la mer','en pleine haute montagne','dans un simple jardin public']::text[], null, 27630, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27632, 'cm2', 'lecture', 'Que fait précisément toute la famille dès son arrivée sur le lieu de camping ?', 'elle monte ensemble la grande tente familiale', array['elle part immédiatement se baigner','elle prépare directement le dîner du soir','elle explore la forêt avant toute autre chose']::text[], null, 27630, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27633, 'cm2', 'lecture', 'Comment précisément Félix aide-t-il concrètement à monter la tente familiale ?', 'en tenant fermement les piquets métalliques', array['en donnant simplement des conseils oraux','il n''aide en réalité pas du tout ce jour-là','en préparant le repas pendant ce temps précis']::text[], null, 27630, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27634, 'cm2', 'lecture', 'Avec qui précisément Félix se baigne-t-il durant l''après-midi de cette première journée ?', 'son papa', array['sa propre maman','entièrement seul, sans personne','un autre campeur rencontre sur place']::text[], null, 27630, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27635, 'cm2', 'lecture', 'Que perçoit précisément Félix une fois la nuit complètement tombée sur le campement ?', 'de nombreux bruits mystérieux venant de la forêt', array['de la musique diffusée au loin','des voitures qui passent régulièrement','rien du tout, un silence total']::text[], null, 27630, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27636, 'cm2', 'lecture', 'Que demande précisément Félix à son papa concernant les animaux actifs durant la nuit ?', 'comment ils parviennent à se déplacer dans l''obscurité', array['pourquoi ils dorment durant la journée entière','ou précisément ils habitent durant l''hiver','combien ils sont exactement dans la forêt']::text[], null, 27630, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27637, 'cm2', 'lecture', 'Que veut dire "ombrage" à propos de l''emplacement choisi précisément par la famille pour la tente ?', 'protège efficacement du soleil par des arbres proches', array['expose directement en plein soleil','recouvert entièrement d''eau stagnante','particulièrement pentu et instable']::text[], null, 27630, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27638, 'cm2', 'lecture', 'Que veut dire "impressionne" à propos du ressenti de Félix face aux bruits nocturnes entendus ?', 'un peu troublé, marqué par une émotion particulière ressentie', array['totalement indifférent à la situation vécue','particulièrement en colère sans raison','extrêmement fatigué physiquement']::text[], null, 27630, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27639, 'cm2', 'lecture', 'Que veut dire "berce" à propos de Félix s''endormant paisiblement près de la rivière ?', 'doucement accompagné et apaisé par un bruit régulier', array['brusquement réveillé en pleine nuit','particulièrement effrayé par un événement','empêche complètement de trouver le sommeil']::text[], null, 27630, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27640, 'cm2', 'lecture', 'Que veut dire "nocturnes" à propos des oiseaux et mammifères évoques par le papa de Félix ?', 'actifs particulièrement pendant la période de la nuit', array['actifs uniquement pendant la journée','qui ne se déplacent jamais réellement','qui vivent exclusivement dans l''eau']::text[], null, 27630, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27641, 'cm2', 'lecture', 'Que veut dire "adaptée" à propos de la vision nocturne particulière de certains animaux évoquée par le papa ?', 'spécialement développée pour répondre a un besoin précis', array['totalement inutile dans ce contexte précis','identique en tout point à celle de l''homme','particulièrement faible et peu efficace']::text[], null, 27630, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27642, 'cm2', 'lecture', 'Que veut dire "clapotis" à propos du bruit doux produit par l''eau de la rivière ce soir-là ?', 'le petit bruit produit par l''eau qui coule doucement', array['un bruit très fort et particulièrement assourdissant','un silence total et particulièrement absolu','un grondement menaçant et inquiétant']::text[], null, 27630, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27643, 'cm2', 'lecture', 'Pourquoi précisément Félix trouve-t-il l''installation de la tente étonnamment confortable malgré son caractère improvise ?', 'il ne s''attendait en réalité pas à un tel confort pour une toute première expérience de camping', array['il a en réalité déjà campé de très nombreuses fois auparavant','ses parents ont en réalité apporte un véritable lit pour l''occasion','la tente utilisée est en réalité un petit chalet aménagé sur place']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27644, 'cm2', 'lecture', 'Pourquoi précisément Félix apprécie-t-il particulièrement la baignade malgré la température froide de l''eau ?', 'la sensation vivifiante ressentie lui procure un réel plaisir malgré l''inconfort initial', array['il n''a en réalité pas remarque que l''eau était particulièrement froide','son papa l''oblige explicitement à se baigner contre son propre gré','c''est la seule activité possible durant cet après-midi particulier']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27645, 'cm2', 'lecture', 'Pourquoi précisément les bruits nocturnes impressionnent-ils quelque peu Félix la toute première nuit ?', 'ce sont des sons totalement inconnus et nouveaux pour lui dans cet environnement particulier', array['il a en réalité déjà vécu une mauvaise expérience en forêt auparavant','ses parents l''ont volontairement effrayé avant d''aller dormir ce soir-là','il pense qu''un animal particulièrement dangereux approche de la tente']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27646, 'cm2', 'lecture', 'Qu''est-ce qui permet précisément à Félix de se sentir rapidement rassure face à ces bruits inconnus rencontres ?', 'les explications claires et particulièrement rassurantes fournies par son propre papa', array['le fait de rester éveille toute la nuit pour surveiller les environs','l''absence totale de bruit après quelques minutes seulement passées','le retour immédiat de toute la famille vers la maison familiale']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27647, 'cm2', 'lecture', 'Pourquoi précisément Félix interroge-t-il son papa sur la manière dont les animaux voient dans l''obscurité totale ?', 'sa curiosité naturelle le pousse à mieux comprendre le monde naturel qui l''entoure durant cette nuit', array['il a en réalité peur de ces animaux et cherche à se rassurer davantage','son papa l''oblige explicitement à poser cette question particulière','il n''a en réalité rien d''autre à demander durant cette soirée précise']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27648, 'cm2', 'lecture', 'Que peut-on déduire globalement du plaisir manifeste de Félix à l''égard de cette expérience de camping vécue ?', 'il apprécie sincèrement découvrir un nouveau mode de vie temporaire proche de la nature environnante', array['il regrette globalement d''avoir accepté de participer à cette sortie particulière','il préférerait clairement passer ses vacances dans un hôtel confortable','cette expérience ne lui laisse en réalité aucun souvenir particulier durable']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27649, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par le papa de Félix tout au long de cette expérience de camping partagée ?', 'il rassure et accompagne son fils avec une patience sincère face aux nouveautés rencontrées ensemble', array['il laisse Félix affronter entièrement seul toutes les difficultés rencontrées','il se montre en réalité plus inquiet que Félix face aux bruits nocturnes entendus','il ne s''implique en réalité pas particulièrement dans cette sortie familiale']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27650, 'cm2', 'lecture', 'Pourquoi précisément Félix demande-t-il dès le lendemain matin à organiser une nouvelle sortie de camping l''été suivant ?', 'cette première expérience très positive nourrit chez lui une véritable envie de renouveler l''aventure', array['ses parents l''obligent explicitement à formuler cette demande particulière','il n''a en réalité aucune autre idée de sortie à proposer pour l''été suivant','il cherche uniquement à faire plaisir à ses propres parents présents']::text[], null, 27630, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27652, 'cm2', 'lecture', 'À quelle heure précisément Louis se lève-t-il ce samedi matin particulier ?', 'très tôt', array['particulièrement tard','aux alentours de midi','en fin d''après-midi seulement']::text[], null, 27651, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27653, 'cm2', 'lecture', 'Depuis quel âge précis Louis pratique-t-il la pêche avec son grand-père ?', 'depuis l''âge de six ans', array['depuis cette année seulement','depuis sa toute petite enfance','il n''a jamais pêche auparavant']::text[], null, 27651, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27654, 'cm2', 'lecture', 'Où précisément se déroule cette partie de pêche particulière ce matin-là ?', 'sur un étang paisible', array['directement en pleine mer','dans une simple piscine','dans une rivière particulièrement tumultueuse']::text[], null, 27651, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27655, 'cm2', 'lecture', 'Que montre précisément le grand-père à Louis avant de commencer à pécher ?', 'comment fixer correctement l''appât au bout de l''hameçon', array['comment nager efficacement dans l''étang','comment construire entièrement une canne à pêche','comment cuisiner ensuite un poisson attrape']::text[], null, 27651, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27656, 'cm2', 'lecture', 'Que remontent-ils finalement précisément au bout de la ligne de Louis ?', 'un magnifique poisson argenté', array['une vieille botte particulièrement abîmée','des algues complètement emmêlées','rien du tout, la ligne était vidé']::text[], null, 27651, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27657, 'cm2', 'lecture', 'Que décident-ils finalement de faire ensemble avec le poisson attrape ce matin-là ?', 'le relâcher délicatement dans l''étang', array['le ramener directement à la maison familiale','le donner à un autre pêcheur présent','le vendre directement au marche local']::text[], null, 27651, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27658, 'cm2', 'lecture', 'Que veut dire "ondulations" à propos de la surface de l''eau observée par Louis et son grand-père ?', 'de petites vagues légères et particulièrement régulières', array['des vagues très hautes et particulièrement violentes','une surface parfaitement plate et totalement immobile','des tourbillons particulièrement dangereux et imprévisibles']::text[], null, 27651, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27659, 'cm2', 'lecture', 'Que veut dire "avises" à propos des conseils donnés précisément par le grand-père de Louis ce matin-là ?', 'sages et particulièrement pertinents pour la situation', array['totalement inutiles dans ce contexte précis','contradictoires et particulièrement confus à suivre','donnes uniquement à contrecoeur et sans conviction']::text[], null, 27651, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27660, 'cm2', 'lecture', 'Que veut dire "vigoureusement" à propos du poisson se débattant au bout de la ligne de Louis ?', 'avec beaucoup de force et une énergie particulièrement visible', array['très mollement, sans le moindre effort particulier','sans aucun mouvement particulier observe','très lentement et particulièrement faiblement']::text[], null, 27651, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27661, 'cm2', 'lecture', 'Que veut dire "préservation" à propos du principe expliqué par le grand-père concernant les populations de poissons ?', 'la protection durable d''une ressource naturelle existante', array['la destruction volontaire d''une espèce précise','la vente organisée d''un produit naturel','la capture systématique de tous les poissons rencontres']::text[], null, 27651, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27662, 'cm2', 'lecture', 'Que veut dire "un commun accord" à propos de la décision partagée de relâcher précisément le poisson attrape ?', 'une décision prise ensemble, en accord mutuel partage', array['une décision imposée unilatéralement par l''un des deux seulement','un désaccord total persistant entre les deux personnes','une décision prise entièrement au hasard sans réflexion']::text[], null, 27651, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27663, 'cm2', 'lecture', 'Que veut dire "bien établie" à propos de la tradition familiale de relâcher certains poissons attrapés ?', 'solidement ancrée et respectée depuis particulièrement longtemps', array['récente et particulièrement incertaine dans sa pratique','abandonnée depuis peu par l''ensemble de la famille','totalement inconnue du reste de la famille de Louis']::text[], null, 27651, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27664, 'cm2', 'lecture', 'Pourquoi précisément Louis et son grand-père restent-ils longtemps silencieux en attendant que les poissons mordent ?', 'le calme nécessaire permet de ne pas effrayer les poissons environnants présents dans l''étang', array['ils se sont en réalité disputes avant de partir pécher ensemble ce matin-là','ils n''ont simplement rien à se dire particulier ce jour-là précis','le règlement de l''étang interdit strictement toute conversation entre pêcheurs']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27665, 'cm2', 'lecture', 'Pourquoi précisément Louis ressent-il à la fois de l''excitation et de l''appréhension quand son flotteur s''enfonce soudainement ?', 'cette sensation particulière est totalement nouvelle et inconnue pour lui à ce moment précis', array['il a en réalité peur que sa ligne se casse définitivement sous l''effort','son grand-père l''a averti d''un danger réel présent dans cet étang','il pense en réalité avoir accroché un objet particulièrement dangereux']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27666, 'cm2', 'lecture', 'Pourquoi précisément décident-ils finalement de relâcher le poisson attrape plutôt que de le garder pour eux ?', 'ils pêchent avant tout par plaisir et respectent une tradition familiale de relâcher leurs prises', array['le poisson attrape est en réalité trop petit pour être garde raisonnablement','ils n''ont simplement pas de quoi transporter ce poisson jusqu''à la maison','ce poisson précis n''est en réalité pas comestible selon la réglementation']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27667, 'cm2', 'lecture', 'Qu''est-ce qui montre concrètement que cette sortie de pêche compte particulièrement pour le jeune Louis ce jour-là ?', 'il en parle avec enthousiasme à toutes les personnes croisées sur le chemin du retour vers chez lui', array['il oublie complètement cette expérience dès le lendemain de la sortie','il ne souhaite plus jamais y retourner avec son propre grand-père','il ne dit finalement rien à personne de cette expérience particulière vécue']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27668, 'cm2', 'lecture', 'Pourquoi précisément Louis interroge-t-il son grand-père sur l''importance de relâcher certains poissons attrapés ?', 'sa curiosité naturelle le pousse à mieux comprendre les raisons profondes de cette tradition familiale précise', array['il doute sérieusement de la pertinence réelle de cette pratique observée','son grand-père l''oblige explicitement à poser cette question particulière','il cherche uniquement à faire durer davantage cette matinée de pêche partagée']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27669, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Louis et son grand-père à travers cette activité partagée depuis plusieurs années ?', 'ils entretiennent une complicité durable construite autour de cette passion commune sincèrement partagée', array['ils se voient en réalité rarement en dehors de ces sorties régulières de pêche','Louis n''apprécie en réalité pas vraiment cette activité malgré les apparences observées','le grand-père préférerait nettement pécher entièrement seul de son propre côté']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27670, 'cm2', 'lecture', 'Que peut-on déduire de la transmission des valeurs de respect de la nature illustrée par cette histoire particulière ?', 'le grand-père transmet à Louis un rapport respectueux envers les animaux et l''environnement naturel qui les entoure', array['cette tradition n''a en réalité aucune signification particulière à leurs propres yeux','Louis n''apprend finalement rien de particulier lors de ces sorties partagées','le grand-père impose cette règle sans jamais réellement l''expliquer à Louis']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27671, 'cm2', 'lecture', 'Que peut-on déduire globalement du plaisir manifeste par Louis à raconter sa pêche à chaque personne croisée sur le chemin du retour ?', 'cette matinée restera pour lui un souvenir particulièrement marquant et source d''une véritable fierté personnelle', array['il cherche uniquement à se vanter sans réelle sincérité face aux personnes croisées','il exagère largement la réalité de ce qui s''est réellement passe ce matin-là','il espère simplement recevoir une récompense matérielle de la part de ses parents']::text[], null, 27651, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27673, 'cm2', 'lecture', 'À quel moment précis de la semaine Charlotte se rend-elle habituellement au centre équestre ?', 'chaque samedi matin', array['chaque dimanche soir','chaque mercredi après-midi','chaque vendredi en fin de journée']::text[], null, 27672, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27674, 'cm2', 'lecture', 'Depuis combien de temps précisément Charlotte pratique-t-elle l''équitation avec passion ?', 'depuis deux années complètes', array['depuis à peine quelques semaines','depuis toute sa petite enfance','elle vient tout juste de commencer cette année']::text[], null, 27672, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27675, 'cm2', 'lecture', 'Comment se nomme précisément la jument confiée ce jour-là à Charlotte par sa monitrice ?', 'Belle', array['Étoile','Cannelle','Perle']::text[], null, 27672, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27676, 'cm2', 'lecture', 'Que doit faire précisément Charlotte avant de monter en selle sur Belle ?', 'brosser le pelage et nettoyer les sabots de la jument', array['donner directement à manger à la jument','promener longuement la jument hors du manège','simplement attendre patiemment sa monitrice']::text[], null, 27672, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27677, 'cm2', 'lecture', 'Que parvient finalement à réaliser Charlotte vers la toute fin de son cours d''équitation ?', 'un petit parcours d''obstacles particulièrement simple', array['un très long trajet en dehors du centre équestre','une chute accidentelle depuis le dos de sa jument','un simple tour de manège supplémentaire au pas']::text[], null, 27672, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27678, 'cm2', 'lecture', 'Que précise finalement la monitrice de Charlotte concernant les prochains cours à venir ?', 'Charlotte pourra désormais monter régulièrement Belle', array['Charlotte devra changer de jument dès le prochain cours','Charlotte ne pourra plus jamais remonter sur un cheval','Charlotte devra recommencer entièrement son apprentissage']::text[], null, 27672, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27679, 'cm2', 'lecture', 'Que veut dire "hebdomadaire" à propos du cours d''équitation suivi régulièrement par Charlotte ?', 'qui revient chaque semaine de manière régulière', array['qui n''a lieu qu''une seule fois par an','qui se déroule uniquement pendant les vacances scolaires','qui se produit de manière complètement imprévisible']::text[], null, 27672, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27680, 'cm2', 'lecture', 'Que veut dire "monture" à propos de Belle, la jument confiée ce jour-là à Charlotte ?', 'l''animal sur lequel on monte pour se déplacer', array['un simple objet décoratif installé dans le manège','un accessoire particulier utilise pour brosser un cheval','un bâtiment spécifique situe dans le centre équestre']::text[], null, 27672, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27681, 'cm2', 'lecture', 'Que veut dire "allure" à propos du trot mentionne par la monitrice de Charlotte durant le cours ?', 'la manière particulière dont un cheval se déplace', array['la couleur précise du pelage d''un cheval','le nom donne à la selle posée sur un cheval','le prix demande pour un cours d''équitation']::text[], null, 27672, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27682, 'cm2', 'lecture', 'Que veut dire "appréhension" à propos du ressenti de Charlotte face à cette allure encore inconnue ?', 'une légère inquiétude ressentie face à une situation nouvelle', array['une joie profonde et particulièrement intense ressentie','une totale indifférence face à la situation vécue','une immense colère ressentie sans raison précise']::text[], null, 27672, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27683, 'cm2', 'lecture', 'Que veut dire "prodigues" à propos des conseils donnés par la monitrice à Charlotte durant ce cours précis ?', 'généreusement donnes avec beaucoup d''attention', array['donnes uniquement à contrecoeur et sans conviction réelle','totalement inutiles dans cette situation précise','donnes en réalité trop tard pour être utiles']::text[], null, 27672, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27684, 'cm2', 'lecture', 'Que veut dire "complicité" à propos du lien naissant entre Charlotte et Belle évoque à la fin de l''histoire ?', 'une entente particulière et une proximité naissante entre deux êtres', array['une simple relation purement professionnelle et distante','une rivalité persistante entre deux personnages','une indifférence totale de l''un envers l''autre']::text[], null, 27672, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27685, 'cm2', 'lecture', 'Pourquoi précisément la monitrice rappelle-t-elle à Charlotte l''importance de brosser et nettoyer les sabots avant chaque cours ?', 'cette routine assure le confort et la bonne santé du cheval avant chaque séance de travail', array['elle souhaite uniquement occuper Charlotte avant le début réel du cours','cette tache est en réalité purement décorative et sans réelle utilité','elle espère ainsi retarder volontairement le début du cours d''équitation']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27686, 'cm2', 'lecture', 'Pourquoi précisément Charlotte ressent-elle une légère appréhension au moment de passer au trot avec Belle ?', 'cette allure plus rapide et inconnue avec cette jument représente un véritable défi nouveau pour elle', array['elle a en réalité peur que sa monitrice se moque ouvertement d''elle','elle sait pertinemment que Belle à l''habitude de désarçonner ses cavaliers','elle préférerait nettement rester uniquement au pas durant tout le cours']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27687, 'cm2', 'lecture', 'Qu''est-ce qui permet précisément à Charlotte de se détendre progressivement durant le passage au trot avec Belle ?', 'les précieux conseils prodigues par sa monitrice présente à ses côtés durant tout le cours', array['le fait que Belle s''arrête complètement de bouger durant un long moment','l''arrivée soudaine d''un autre cavalier plus expérimente dans le manège','la décision prise de finalement redescendre immédiatement de sa jument']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27688, 'cm2', 'lecture', 'Pourquoi précisément la monitrice félicite-t-elle chaleureusement Charlotte à la fin de ce cours particulier ?', 'Charlotte à réellement progresse en franchissant avec aisance son tout premier petit parcours d''obstacles', array['Charlotte a simplement terminé son cours sans tomber une seule fois de sa jument','la monitrice félicite systématiquement tous les cavaliers à la fin de chaque cours','Charlotte a offert un cadeau particulier à sa propre monitrice ce jour-là']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27689, 'cm2', 'lecture', 'Que peut-on déduire du lien particulier qui semble se créer entre Charlotte et Belle au fil de ce cours précis ?', 'une réelle complicité commence à naître entre la jeune cavalière et sa nouvelle jument', array['Charlotte préfère finalement nettement les autres chevaux du centre équestre','Belle se montre en réalité plutôt difficile et peu coopérative avec Charlotte','aucun lien particulier ne semble réellement se créer entre elles ce jour-là']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27690, 'cm2', 'lecture', 'Que peut-on déduire de l''enthousiasme manifeste par Charlotte en racontant sa journée à sa maman sur le chemin du retour ?', 'cette expérience particulièrement positive renforce sa passion sincère pour l''équitation', array['elle cherche uniquement à impressionner sa propre maman sans réelle sincérité','elle regrette en réalité d''avoir monté Belle plutôt qu''un autre cheval','elle n''a en réalité pas particulièrement apprécie ce cours d''équitation précis']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27691, 'cm2', 'lecture', 'Pourquoi précisément Charlotte est-elle impatiente de retrouver Belle dès le samedi suivant ?', 'la complicité naissante vécue avec cette jument lui donne véritablement envie de poursuivre cette relation', array['elle n''a en réalité pas d''autre activité prévue pour le samedi suivant','sa monitrice l''oblige explicitement à revenir des la semaine suivante','elle espère simplement recevoir un cheval à elle en cadeau prochainement']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27692, 'cm2', 'lecture', 'Que peut-on déduire globalement du rôle joue par la monitrice tout au long de l''apprentissage de Charlotte ?', 'elle accompagne avec patience et bienveillance les progrès réels de sa jeune élève', array['elle se montre en réalité plutôt sévère et peu encourageante envers Charlotte','elle ne s''implique en réalité que très peu dans les cours donnés','elle préférerait clairement enseigner à d''autres élèves plus expérimentés']::text[], null, 27672, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27694, 'cm2', 'lecture', 'Quel jour précis de la semaine Gabriel se réveille-t-il sous une pluie continue ?', 'un dimanche', array['un lundi','un samedi','un mercredi']::text[], null, 27693, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27695, 'cm2', 'lecture', 'Qu''avait précisément prévu de faire Gabriel ce jour-là avec ses amis du quartier ?', 'passer la journée dehors sur le terrain vague', array['aller ensemble au cinéma du quartier','visiter un musée avec toute sa famille','participer à une compétition sportive prévue']::text[], null, 27693, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27696, 'cm2', 'lecture', 'Que propose précisément la maman de Gabriel face à cette pluie continue tombant dehors ?', 'organiser une journée créative à l''intérieur de la maison', array['sortir malgré tout affronter la pluie ensemble','aller directement rendre visite aux grands-parents','regarder simplement la télévision toute la journée']::text[], null, 27693, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27697, 'cm2', 'lecture', 'Que choisit précisément de peindre Gabriel durant cette journée passée à l''intérieur ?', 'un tableau représentant la pluie sur une forêt imaginaire', array['un portrait fidèle de sa propre maman','une photographie du terrain vague situe derrière chez lui','un paysage ensoleillé imagine de toutes pièces']::text[], null, 27693, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27698, 'cm2', 'lecture', 'Que préparent ensemble Gabriel et sa maman une fois le tableau termine ?', 'un goûter compose de crêpes maison', array['un grand repas complet pour toute la famille','un gâteau d''anniversaire pour un ami','un simple thé accompagné de quelques biscuits']::text[], null, 27693, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27699, 'cm2', 'lecture', 'Que se passe-t-il précisément en fin d''après-midi concernant la pluie qui tombait depuis le matin ?', 'elle cesse progressivement et un arc-en-ciel apparaît', array['elle redouble encore davantage d''intensité','elle se transforme progressivement en neige abondante','rien ne change vraiment, elle continue de tomber pareillement']::text[], null, 27693, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27700, 'cm2', 'lecture', 'Que veut dire "sans discontinuer" à propos de la pluie tombant depuis le matin sur toute la région ?', 'de manière continue et ininterrompue pendant longtemps', array['de manière très brève et particulièrement ponctuelle','de manière irrégulière avec de nombreuses pauses','de manière extrêmement violente mais très courte']::text[], null, 27693, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27701, 'cm2', 'lecture', 'Que veut dire "convoite" à propos du terrain vague évoque à la toute fin de cette histoire ?', 'particulièrement désire et attendu avec impatience', array['totalement oublie et délaisse par tous','juge dangereux et donc évité par tous','récemment ferme au public pour travaux']::text[], null, 27693, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27702, 'cm2', 'lecture', 'Que veut dire "réconfortant" à propos du goûter préparé par Gabriel et sa maman cet après-midi-là ?', 'qui apporte du bien-être et une douce consolation', array['qui provoque au contraire une certaine déception','particulièrement froid et désagréable à consommer','prépare dans une précipitation excessive et sans soin']::text[], null, 27693, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27703, 'cm2', 'lecture', 'Que veut dire "motifs" à propos des formes dessinées par les gouttes de pluie glissant sur la vitre ?', 'des dessins ou formes particulières qui se répètent', array['des sons particuliers produits par la pluie qui tombe','des odeurs spécifiques dégagées par la pluie tombante','des couleurs uniques et jamais observées auparavant']::text[], null, 27693, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27704, 'cm2', 'lecture', 'Que veut dire "cycle" à propos du phénomène naturel de l''eau expliqué par la maman de Gabriel ?', 'une suite de transformations qui se répète régulièrement', array['un événement unique qui ne se reproduit jamais','un simple objet rond utilise pour illustrer une explication','une durée très précise mesurée en heures exactes']::text[], null, 27693, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27705, 'cm2', 'lecture', 'Que veut dire "grandissant" à propos de l''enthousiasme ressenti par Gabriel face à la proposition de sa maman ?', 'qui augmente progressivement avec le temps qui passe', array['qui diminue au contraire très rapidement','qui reste parfaitement stable sans jamais changer','qui disparaît complètement au bout de quelques minutes']::text[], null, 27693, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27706, 'cm2', 'lecture', 'Pourquoi précisément Gabriel ressent-il d''abord une légère déception en se réveillant ce dimanche matin-là ?', 'la pluie continue l''empêche de réaliser le projet extérieur qu''il avait prévu depuis longtemps avec ses amis', array['il n''aime en réalité pas du tout la compagnie de ses propres amis du quartier','sa maman lui avait promis une sortie qu''elle refuse finalement d''honorer ce jour-là','il a en réalité peur des orages violents qui accompagnent parfois la pluie']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27707, 'cm2', 'lecture', 'Pourquoi précisément Gabriel accepte-t-il finalement avec enthousiasme la proposition de sa maman ce matin-là ?', 'il reconnaît la valeur réelle de cette alternative créative malgré sa déception initiale ressentie', array['il n''a en réalité pas d''autre choix réel que d''accepter cette proposition formulée','ses amis ont en réalité déjà annule eux-mêmes leur propre sortie prévue','sa maman insiste fermement jusqu''à ce qu''il finisse par céder totalement']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27708, 'cm2', 'lecture', 'Pourquoi précisément Gabriel choisit-il de peindre justement un paysage de pluie plutôt qu''un autre sujet ?', 'le paysage gris qu''il observé par la fenêtre du salon l''inspire directement à ce moment précis', array['sa maman lui impose explicitement ce sujet particulier à peindre','il ne sait tout simplement pas peindre d''autres sujets différents','c''est le seul sujet propose dans le livre de peinture utilise']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27709, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que Gabriel développe un véritable intérêt pour les phénomènes naturels durant cette journée ?', 'il interroge spontanément sa maman sur l''origine de la pluie et écoute attentivement son explication donnée', array['il se contente simplement de regarder la pluie tomber sans poser la moindre question','sa maman aborde ce sujet précis sans que Gabriel ne montre le moindre intérêt réel','il préfère nettement continuer à peindre plutôt que d''écouter les explications de sa maman']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27710, 'cm2', 'lecture', 'Pourquoi précisément Gabriel sort-il rapidement admirer l''arc-en-ciel apparu en fin d''après-midi ce jour-là ?', 'ce spectacle naturel particulièrement rare et lumineux suscite chez lui une réelle curiosité et un émerveillement sincère', array['sa maman l''oblige explicitement à sortir observer ce phénomène précis','il espère en réalité pouvoir enfin rejoindre ses amis sur le terrain vague','il souhaite uniquement vérifier si la pluie à définitivement cesse de tomber']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27711, 'cm2', 'lecture', 'Que peut-on déduire de la conclusion tirée par Gabriel à la toute fin de cette journée pluvieuse et imprévue ?', 'il comprend qu''un imprévu peut malgré tout se transformer en une expérience finalement très positive et mémorable', array['il regrette profondément d''avoir accepté la proposition initiale formulée par sa maman','il préférerait nettement revivre une journée identique le week-end suivant à nouveau','cette journée n''aura finalement laisse aucun souvenir particulier durable chez lui']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27712, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par la maman de Gabriel tout au long de cette journée particulière racontée ?', 'elle sait transformer avec bienveillance une déception initiale en une occasion sincère de partage et de découverte', array['elle impose systématiquement ses propres choix à Gabriel sans jamais le consulter réellement','elle se montre en réalité plutôt distante et peu impliquée dans les activités proposées','elle préférerait nettement que Gabriel sorte malgré tout braver la pluie tombante']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27713, 'cm2', 'lecture', 'Que peut-on déduire globalement de la place occupée par la curiosité dans le quotidien de Gabriel à travers cette histoire ?', 'elle lui permet de tirer le meilleur parti de chaque situation rencontrée, y compris des imprévus du quotidien', array['elle ne joue en réalité aucun rôle particulier significatif dans son quotidien habituel','elle se manifeste uniquement lorsqu''il est contrarié par une situation précise vécue','elle disparaît complètement dès qu''un imprévu survient dans son quotidien']::text[], null, 27693, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27715, 'cm2', 'lecture', 'Depuis combien de temps précisément Julia rêvait-elle de posséder sa propre cabane de jardin ?', 'depuis de nombreux mois', array['depuis à peine quelques jours','depuis sa toute petite enfance seulement','elle n''y avait en réalité jamais pense auparavant']::text[], null, 27714, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27716, 'cm2', 'lecture', 'Où précisément Julia et son papa décident-ils finalement d''installer la nouvelle cabane ?', 'dans un coin ombrage près du grand pommier', array['juste à côté du portail d''entrée du jardin','directement au milieu du potager familial','contre le mur extérieur de la maison']::text[], null, 27714, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27717, 'cm2', 'lecture', 'Que dessine précisément le papa de Julia avant de commencer la construction de la cabane ?', 'un plan simple sur une feuille de papier', array['une maquette complète en carton','un dessin numérique réalise sur ordinateur','rien du tout, ils improvisent entièrement']::text[], null, 27714, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27718, 'cm2', 'lecture', 'Que fait précisément Julia pour personnaliser l''intérieur de sa cabane une fois terminée ?', 'elle ajoute des coussins, des étagères et une guirlande lumineuse', array['elle installe un véritable lit et une armoire','elle peint uniquement les murs intérieurs en bleu','elle n''apporte finalement aucune modification particulière']::text[], null, 27714, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27719, 'cm2', 'lecture', 'Qui précisément Julia invite-t-elle à découvrir sa toute nouvelle cabane de jardin ?', 'sa meilleure amie Rosalie', array['sa propre grande soeur','sa maîtresse d''école','son cousin venu en visite']::text[], null, 27714, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27720, 'cm2', 'lecture', 'Que fait désormais Julia chaque soir après l''école dans sa nouvelle cabane installée au fond du jardin ?', 'elle s''installe pour lire ou dessiner tranquillement', array['elle y fait uniquement ses devoirs scolaires','elle y range simplement ses jouets d''enfant','elle n''y retourne finalement plus très souvent']::text[], null, 27714, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27721, 'cm2', 'lecture', 'Que veut dire "concrétiser" à propos du projet de cabane que Julia souhaitait réaliser depuis longtemps ?', 'rendre réellement possible un projet jusqu''alors imagine', array['abandonner définitivement un projet envisage','modifier complètement un projet déjà termine','raconter simplement un projet à d''autres personnes']::text[], null, 27714, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27722, 'cm2', 'lecture', 'Que veut dire "recyclées" à propos des planches de bois utilisées pour construire la cabane de Julia ?', 'réutilisées après avoir déjà servi à un autre usage', array['achetées neuves spécialement pour ce projet précis','importées depuis un pays particulièrement lointain','fabriquées à partir d''un matériau totalement différent']::text[], null, 27714, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27723, 'cm2', 'lecture', 'Que veut dire "poncer" à propos de l''une des taches réalisées par Julia et son papa sur les planches de bois ?', 'frotter une surface pour la rendre lisse', array['peindre une surface d''une couleur vive','couper une planche de bois en plusieurs morceaux','clouer solidement deux planches ensemble']::text[], null, 27714, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27724, 'cm2', 'lecture', 'Que veut dire "traite" à propos du bois utilise pour la construction, évoque par le papa de Julia ?', 'soumis à un procède spécial pour le protéger durablement', array['coupe selon une forme particulière et précise','peint d''une couleur spécifique choisie à l''avance','transporte depuis un lieu de stockage éloigne']::text[], null, 27714, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27725, 'cm2', 'lecture', 'Que veut dire "improvisées" à propos des étagères installées par Julia à l''intérieur de sa cabane ?', 'fabriquées rapidement avec les moyens disponibles sur le moment', array['commandées spécialement dans un magasin spécialise','installées par un professionnel venu spécialement','identiques à celles présentes dans sa propre chambre']::text[], null, 27714, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27726, 'cm2', 'lecture', 'Que veut dire "durablement" à propos de la protection du bois contre l''humidité mentionnée par le papa de Julia ?', 'de manière efficace et pour une très longue période', array['de manière très brève et peu efficace','uniquement pendant la période de construction précise','de façon totalement inutile et superflue']::text[], null, 27714, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27727, 'cm2', 'lecture', 'Pourquoi précisément Julia et son papa choisissent-ils un emplacement ombrage près du pommier pour la cabane ?', 'cet emplacement offre probablement un cadre agréable et protège pour profiter pleinement de la cabane', array['il s''agit du seul endroit disponible dans tout le jardin familial','le papa de Julia souhaite avant tout protéger ses propres plantations du soleil','Julia n''aime pas du tout le soleil et cherche à l''éviter systématiquement']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27728, 'cm2', 'lecture', 'Pourquoi précisément le papa de Julia explique-t-il patiemment chaque étape de construction avant de commencer les travaux ?', 'il souhaite que Julia comprenne et participe activement à son propre projet plutôt que de simplement observer', array['il n''est en réalité pas sur lui-même de la méthode de construction à suivre','Julia insiste fermement pour tout savoir avant même de commencer les travaux','il espère ainsi retarder volontairement le début réel de la construction']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27729, 'cm2', 'lecture', 'Pourquoi précisément Julia se montre-t-elle particulièrement fière de planter elle-même quelques clous durant la construction ?', 'réaliser une tache concrète et nouvelle pour elle lui procure un réel sentiment d''accomplissement personnel', array['son papa la félicite excessivement pour un geste pourtant très simple à réaliser','elle n''a en réalité jamais rien construit ni fabriqué auparavant de toute sa vie','elle espère impressionner sa meilleure amie qui doit venir plus tard dans la journée']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27730, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément l''attachement sincère de Julia pour sa nouvelle cabane de jardin ?', 'elle prend désormais l''habitude de s''y installer chaque soir après l''école pour lire ou dessiner tranquillement', array['elle n''y retourne finalement qu''une seule fois après l''avoir terminée avec son papa','elle préfère nettement rester dans sa propre chambre plutôt que dans cette cabane','elle regrette en réalité d''avoir consacré autant de temps à ce projet particulier']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27731, 'cm2', 'lecture', 'Pourquoi précisément Julia interroge-t-elle son papa sur le traitement nécessaire du bois contre l''humidité ?', 'sa curiosité naturelle la pousse à comprendre comment préserver durablement ce qu''ils ont construit ensemble', array['elle doute sérieusement de la solidité réelle de la cabane nouvellement construite','son papa l''oblige explicitement à poser cette question particulière avant de continuer','elle cherche uniquement à faire durer davantage cette conversation avec son papa']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27732, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Julia et son papa à travers ce projet de construction partage ensemble ?', 'ce projet commun renforce durablement leur complicité et leur confiance mutuelle partagée', array['le papa de Julia réalise finalement l''essentiel du travail sans réelle participation de sa fille','Julia se désintéresse rapidement du projet une fois la construction bien entamée','ce projet crée en réalité davantage de tensions que de moments de partage sincère']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27733, 'cm2', 'lecture', 'Que peut-on déduire du plaisir manifeste par Julia et Rosalie à jouer ensemble dans la nouvelle cabane construite ?', 'cet espace bien à elles stimule naturellement leur imagination et leur complicité amicale', array['les deux fillettes s''ennuient en réalité assez rapidement dans cet espace restreint','Rosalie préférerait nettement jouer ailleurs plutôt que dans cette cabane précise','la cabane construite se révèle finalement trop petite pour accueillir deux personnes']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27734, 'cm2', 'lecture', 'Que peut-on déduire globalement de la valeur que Julia accorde à cette cabane construite avec son papa ?', 'elle considère ce projet partage comme un cadeau précieux et durable bien au-delà de sa simple valeur matérielle', array['elle perçoit cette cabane uniquement comme un simple espace de rangement supplémentaire','elle regrette au fond d''elle-même le temps consacre à ce projet de construction','cette cabane ne représente finalement rien de particulièrement spécial à ses propres yeux']::text[], null, 27714, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27736, 'cm2', 'lecture', 'Où précisément se déroule cette grande chasse au trésor à laquelle participe Victor ce samedi ?', 'dans le parc municipal de sa ville', array['dans la cour de son école','sur la plage près de chez lui','dans le jardin de ses grands-parents']::text[], null, 27735, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27737, 'cm2', 'lecture', 'Que remet précisément l''organisatrice à chaque équipe participante dès le début de l''événement ?', 'une première énigme mystérieuse à résoudre', array['une carte complète du parc municipal','une petite boussole individuelle','un plan détaille de toutes les énigmes']::text[], null, 27735, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27738, 'cm2', 'lecture', 'Avec qui précisément Victor forme-t-il son équipe pour cette chasse au trésor particulière ?', 'Nina et Théo', array['sa propre petite soeur','deux enfants inconnus rencontres sur place','il participe en réalité entièrement seul']::text[], null, 27735, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27739, 'cm2', 'lecture', 'Où précisément l''équipe de Victor découvre-t-elle la deuxième énigme cachée ?', 'sous une racine d''un arbre ancien près de l''entrée du parc', array['à l''intérieur d''une fontaine du parc','sur un banc public situe près de l''aire de jeux','cachée dans un buisson près du muret']::text[], null, 27735, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27740, 'cm2', 'lecture', 'Que doit résoudre précisément l''équipe pour comprendre la troisième énigme rencontrée durant la chasse ?', 'une petite opération mathématique', array['une longue devinette en vers rimes','un puzzle constitue de nombreuses pièces','une simple question de culture générale']::text[], null, 27735, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27741, 'cm2', 'lecture', 'Que reçoit finalement chaque membre de l''équipe victorieuse à la toute fin de cette chasse au trésor ?', 'une petite médaille souvenir', array['une somme d''argent importante','un véritable trophée en argent','un simple diplôme imprime sur papier']::text[], null, 27735, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27742, 'cm2', 'lecture', 'Que veut dire "soudée" à propos de l''équipe formée par Victor, Nina et Théo pour cette chasse au trésor ?', 'unie et particulièrement solidaire dans son fonctionnement', array['formée au tout dernier moment et sans grande conviction','composée de personnes qui ne se connaissent pas du tout','divisée par de nombreux désaccords internes persistants']::text[], null, 27735, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27743, 'cm2', 'lecture', 'Que veut dire "scellée" à propos de l''enveloppe découverte sous la racine de l''arbre ancien du parc ?', 'fermée hermétiquement pour protéger son contenu', array['ouverte largement et laissée bien visible','décorée de nombreux dessins colorés','écrite entièrement à la main par l''organisatrice']::text[], null, 27735, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27744, 'cm2', 'lecture', 'Que veut dire "ornementale" à propos de la fontaine mentionnée dans la deuxième énigme rencontrée par l''équipe ?', 'décorative et particulièrement soignée dans son apparence', array['totalement fonctionnelle mais sans réel intérêt visuel','récemment installée dans le parc municipal','réservée exclusivement aux événements officiels de la ville']::text[], null, 27735, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27745, 'cm2', 'lecture', 'Que veut dire "dissimule" à propos de l''indice trouvé par Théo près du muret de la fontaine ?', 'cache avec soin pour ne pas être facilement trouve', array['place bien en évidence pour être vu rapidement','abandonne par erreur à cet endroit précis','écrit en très grandes lettres particulièrement visibles']::text[], null, 27735, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27746, 'cm2', 'lecture', 'Que veut dire "localiser" à propos de l''action finale permettant à l''équipe de trouver le coffre au trésor cache ?', 'déterminer précisément l''emplacement exact d''un objet', array['transporter physiquement un objet d''un lieu à un autre','décrire en détail l''apparence extérieure d''un objet','partager avec d''autres équipes une information précise']::text[], null, 27735, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27747, 'cm2', 'lecture', 'Que veut dire "collective" à propos de la réflexion menée par l''équipe pour résoudre la dernière énigme rencontrée ?', 'menée ensemble par plusieurs personnes réunies', array['menée entièrement seul sans aucune aide extérieure','menée dans un silence total et absolu','menée de manière particulièrement rapide et hâtive']::text[], null, 27735, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27748, 'cm2', 'lecture', 'Pourquoi précisément l''équipe de Victor décide-t-elle de réfléchir méthodiquement plutôt que de se précipiter dès le début de la chasse ?', 'une réflexion soigneuse augmente probablement leurs chances de résoudre correctement chaque énigme rencontrée', array['l''organisatrice leur interdit formellement de courir dans le parc municipal','ils ont en réalité peur de se perdre dans les allées du grand parc','ils souhaitent avant tout laisser une chance aux autres équipes participantes']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27749, 'cm2', 'lecture', 'Pourquoi précisément le souvenir de Nina concernant la fontaine du parc s''avère-t-il si utile à toute l''équipe ?', 'sa connaissance préalable du parc permet à l''équipe de gagner un temps précieux dans sa progression', array['elle a en réalité déjà participé à cette même chasse au trésor l''année précédente','l''organisatrice lui a discrètement donné cette information avant le début de l''événement','elle invente simplement cette information au hasard pour aider son équipe']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27750, 'cm2', 'lecture', 'Qu''est-ce qui rend précisément la troisième énigme plus difficile à résoudre que les deux énigmes précédentes ?', 'elle nécessite une étape de calcul supplémentaire avant de pouvoir localiser l''emplacement du trésor', array['elle est écrite dans une langue étrangère que l''équipe ne maîtrise pas','elle ne contient en réalité aucun indice exploitable par l''équipe','elle a été délibérément rendue illisible par l''organisatrice de l''événement']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27751, 'cm2', 'lecture', 'Pourquoi précisément Victor et son équipe éprouvent-ils une joie particulière en découvrant enfin le coffre au trésor final ?', 'cette découverte récompense les efforts collectifs fournis tout au long de cette chasse au trésor exigeante', array['ils ne s''attendaient en réalité pas du tout à trouver un trésor réel au bout de cette chasse','l''organisatrice leur avait promis une récompense financière importante en cas de victoire','ils découvrent en réalité un trésor bien plus important que ce qu''ils imaginaient au départ']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27752, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément l''efficacité du travail d''équipe entre Victor, Nina et Théo durant cette chasse au trésor ?', 'chacun contribue à sa manière, par ses souvenirs, son observation ou sa réflexion, à la réussite collective finale', array['Victor résout finalement seul l''intégralité des énigmes rencontrées sans aucune aide','Nina et Théo se contentent simplement de suivre passivement les décisions prises par Victor','l''équipe échoue finalement à résoudre la dernière énigme présentée durant l''événement']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27753, 'cm2', 'lecture', 'Que peut-on déduire de la complémentarité des trois enfants formant cette équipe durant toute la chasse au trésor ?', 'leurs qualités respectives, mémoire, observation et logique, se combinent efficacement pour progresser ensemble', array['ils possèdent en réalité tous exactement les mêmes compétences et qualités personnelles','seul Victor possède réellement des qualités utiles à la progression de son équipe','leurs personnalités très différentes génèrent surtout des tensions internes persistantes']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27754, 'cm2', 'lecture', 'Que peut-on déduire globalement du plaisir manifeste par les trois enfants à l''issue de cette chasse au trésor réussie ?', 'cette victoire collective renforce durablement leur amitié et leur goût sincère pour ce type d''activité partagée', array['ils sont surtout soulages que cette chasse au trésor exigeante soit enfin terminée','ils regrettent en réalité d''avoir formé une équipe à trois plutôt que de participer individuellement','la médaille reçue compte finalement bien davantage à leurs yeux que l''expérience vécue ensemble']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27755, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par l''organisatrice tout au long de cette chasse au trésor décrite dans cette histoire ?', 'elle conçoit un parcours progressif et stimulant qui encourage la réflexion et la coopération entre les participants', array['elle se contente simplement de distribuer les énigmes sans réel souci de leur qualité','elle favorise ouvertement certaines équipes participantes au détriment des autres','elle n''intervient en réalité à aucun moment durant le déroulement de cette chasse au trésor']::text[], null, 27735, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27757, 'cm2', 'lecture', 'À quel moment précis de la semaine Rosa assiste-t-elle à ce spectacle de magie avec sa famille ?', 'un dimanche après-midi', array['un samedi matin','un mercredi soir','un vendredi en fin de journée']::text[], null, 27756, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27758, 'cm2', 'lecture', 'Où précisément se déroule ce grand spectacle de magie auquel assiste Rosa ?', 'dans la salle des fêtes de son village', array['dans un théâtre situe en ville','dans la cour de son école','directement chez elle, à la maison']::text[], null, 27756, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27759, 'cm2', 'lecture', 'Que fait disparaître précisément le magicien lors de son tout premier tour de magie ?', 'une colombe blanche sous un foulard de soie rouge', array['une petite pièce de monnaie dorée','un foulard de soie appartenant à un spectateur','l''un des enfants présents dans le public']::text[], null, 27756, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27760, 'cm2', 'lecture', 'Que demande précisément le magicien à Rosa lorsqu''elle monte sur scène participer à son tour ?', 'de choisir une carte précise parmi un jeu complet', array['de choisir un objet cache dans une boite mystérieuse','de répéter simplement une formule magique particulière','de deviner elle-même le prochain tour de magie prévu']::text[], null, 27756, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27761, 'cm2', 'lecture', 'Que devine finalement le magicien concernant le choix effectue par Rosa durant ce tour de magie ?', 'exactement quelle carte elle avait choisie', array['le prénom complet de Rosa','l''âge exact de Rosa','la couleur précise des vêtements portes par Rosa']::text[], null, 27756, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27762, 'cm2', 'lecture', 'Quel autre numéro impressionnant est évoqué vers la fin du spectacle de magie assiste par Rosa ?', 'un numéro de lévitation', array['un numéro de jonglerie avec des balles','un numéro de danse acrobatique','un numéro de chant particulièrement puissant']::text[], null, 27756, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27763, 'cm2', 'lecture', 'Que veut dire "ébahis" à propos des yeux du public observant le tour de disparition réalise par le magicien ?', 'extrêmement étonnés face à un spectacle surprenant', array['totalement indifférents face à la scène observée','particulièrement en colère sans raison précise','profondément ennuyés par le spectacle propose']::text[], null, 27756, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27764, 'cm2', 'lecture', 'Que veut dire "incrédule" à propos de Rosa retournant s''asseoir après son tour de magie sur scène ?', 'ayant du mal à croire ce qu''elle vient de vivre', array['totalement convaincue et rassurée par l''expérience vécue','particulièrement fière sans le moindre étonnement','complètement indifférente à ce qui vient de se passer']::text[], null, 27756, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27765, 'cm2', 'lecture', 'Que veut dire "bluffant" à propos du tour de magie réalise avec la carte choisie par Rosa ?', 'impressionnant au point de sembler difficile à croire', array['particulièrement simple et facilement explicable','totalement rate et sans réel intérêt','identique à un tour déjà vu par Rosa auparavant']::text[], null, 27756, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27766, 'cm2', 'lecture', 'Que veut dire "bouche bée" à propos de la réaction de toute la salle face au numéro de lévitation présente ?', 'frappe d''un tel étonnement qu''on en reste sans voix', array['en train de parler très fort et bruyamment','totalement endormie durant tout le numéro présente','en train de rire aux éclats sans discontinuer']::text[], null, 27756, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27767, 'cm2', 'lecture', 'Que veut dire "habiles" à propos des manipulations réalisées par le magicien avec le jeu de cartes utilise ?', 'exécutées avec une grande dextérité et beaucoup d''adresse', array['effectuées de manière hasardeuse et particulièrement maladroite','réalisées très lentement et avec une grande difficulté visible','copiées directement depuis un livre de magie']::text[], null, 27756, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27768, 'cm2', 'lecture', 'Que veut dire "se porte volontaire" à propos de l''attitude de Rosa quand le magicien invite des enfants sur scène ?', 'elle propose spontanément de participer elle-même au tour présente', array['elle refuse catégoriquement de monter sur la scène proposée','elle attend qu''un autre enfant soit choisi à sa place','elle demande à ses parents la permission avant de répondre']::text[], null, 27756, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27769, 'cm2', 'lecture', 'Pourquoi précisément Rosa observe-t-elle si attentivement chaque geste effectue par le magicien durant le spectacle ?', 'sa curiosité la pousse à essayer de comprendre le secret cache derrière ces tours impressionnants présentes', array['elle a en réalité déjà assisté à ce même spectacle de magie l''année précédente','elle cherche uniquement à repérer une erreur éventuelle commise par le magicien','ses parents lui ont explicitement demandé de surveiller attentivement le magicien']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27770, 'cm2', 'lecture', 'Pourquoi précisément Rosa se porte-t-elle volontaire avec un tel enthousiasme pour monter sur scène participer au tour de magie ?', 'l''occasion de vivre elle-même un moment magique de près représente pour elle une expérience particulièrement excitante', array['ses parents l''obligent explicitement à se porter volontaire pour ce tour de magie précis','elle connaît déjà à l''avance le secret du tour qui va être présente sur scène','elle espère uniquement recevoir un cadeau particulier en participant à ce tour']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27771, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que Rosa reste profondément marquée par le tour de magie réalise avec sa propre carte choisie ?', 'elle demeure incrédule et continue d''y penser même après être retournée s''asseoir auprès de ses parents', array['elle oublie complètement ce tour dès qu''elle retourne s''asseoir à sa place initiale','elle explique immédiatement à ses parents comment ce tour a été réalise par le magicien','elle refuse catégoriquement de reparler de cette expérience vécue sur scène']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27772, 'cm2', 'lecture', 'Pourquoi précisément Rosa interroge-t-elle son papa sur la manière dont un magicien parvient à réaliser de tels tours ?', 'sa curiosité naturelle la pousse à mieux comprendre le travail véritable qui se cache derrière cet art particulier', array['elle doute sérieusement de la sincérité réelle du magicien qu''elle vient d''observer','son papa lui propose spontanément cette explication sans qu''elle ne demande rien','elle cherche uniquement à prolonger un peu la conversation avec son propre papa']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27773, 'cm2', 'lecture', 'Qu''est-ce que la réponse donnée par le papa de Rosa concernant l''entraînement nécessaire nous apprend sur l''art de la magie ?', 'la magie repose en réalité sur une maîtrise technique acquise grâce à un travail long et rigoureux', array['la magie repose exclusivement sur des pouvoirs surnaturels réels et véritables','n''importe qui peut réussir de tels tours sans le moindre entraînement préalable','les tours de magie présentes sont en réalité improvises entièrement sur scène']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27774, 'cm2', 'lecture', 'Que peut-on déduire du souhait exprimé par Rosa d''apprendre elle-même quelques tours de magie simples ?', 'l''expérience vécue ce jour-là a suscité chez elle une véritable passion naissante pour cet art particulier', array['elle souhaite uniquement se moquer gentiment de ses propres camarades de classe','elle pense en réalité que la magie est trop facile pour mériter d''être apprise sérieusement','elle a déjà oublié l''enthousiasme ressenti durant le spectacle auquel elle vient d''assister']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27775, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''effet produit par ce spectacle de magie sur l''imagination de la jeune Rosa ?', 'il stimule durablement sa curiosité et nourrit chez elle un véritable émerveillement pour cet art du spectacle', array['il la laisse totalement indifférente une fois le spectacle termine','il lui fait au contraire peur et elle refuse désormais d''assister à un tel spectacle','il ne suscite chez elle qu''un intérêt très passager et rapidement oublie']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27776, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par la famille de Rosa dans cette expérience partagée ensemble ce dimanche après-midi ?', 'elle accompagne et encourage avec bienveillance la curiosité et l''enthousiasme naturel de Rosa face à cette découverte', array['elle se montre en réalité plutôt indifférente à l''enthousiasme manifeste par Rosa ce jour-là','elle regrette d''avoir emmené Rosa assister à ce spectacle de magie particulier','elle empêche activement Rosa de participer pleinement à cette expérience vécue']::text[], null, 27756, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27778, 'cm2', 'lecture', 'Où précisément Simon participe-t-il à cet atelier de fabrication de marionnettes durant les vacances scolaires ?', 'au centre de loisirs de son quartier', array['dans la cour de son école','chez sa grand-mère, à la maison','dans une salle municipale du centre-ville']::text[], null, 27777, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27779, 'cm2', 'lecture', 'Quel type de marionnette précisément Simon choisit-il de fabriquer durant cet atelier ?', 'un petit chevalier courageux', array['un dragon impressionnant','une princesse élégante','un animal de la forêt']::text[], null, 27777, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27780, 'cm2', 'lecture', 'Avec quel matériau précisément Simon fabrique-t-il la tête de sa marionnette chevalier ?', 'du papier mâche', array['de l''argile séchée au four','du bois soigneusement sculpte','du tissu rembourré de coton']::text[], null, 27777, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27781, 'cm2', 'lecture', 'Que montre précisément l''animatrice à Simon pour lui apprendre à animer sa marionnette fabriquée ?', 'comment manipuler une croix de commande en bois', array['comment coudre solidement les différents morceaux de tissu','comment peindre le visage de la marionnette','comment attacher simplement une ficelle unique']::text[], null, 27777, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27782, 'cm2', 'lecture', 'Que doivent faire tous les enfants participants à la toute fin de cet atelier de fabrication de marionnettes ?', 'présenter leur marionnette lors d''un petit spectacle devant leurs familles', array['ramener immédiatement leur marionnette chez eux sans autre étape','offrir leur marionnette fabriquée à un autre enfant présent','détruire leur marionnette pour recommencer un nouveau modèle']::text[], null, 27777, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27783, 'cm2', 'lecture', 'Comment réagit précisément l''assistance présente après la démonstration réalisée par Simon sur la petite scène ?', 'elle applaudit avec enthousiasme', array['elle reste totalement silencieuse','elle quitte immédiatement la salle','elle rit fortement sans raison précise']::text[], null, 27777, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27784, 'cm2', 'lecture', 'Que veut dire "chatoyantes" à propos des couleurs choisies par Simon pour le corps de sa marionnette chevalier ?', 'vives et brillantes, changeant légèrement selon la lumière', array['ternes et particulièrement fades à regarder','identiques à la couleur naturelle du tissu utilise','totalement invisibles une fois la marionnette terminée']::text[], null, 27777, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27785, 'cm2', 'lecture', 'Que veut dire "confectionne" à propos du corps du chevalier réalisé par Simon à partir de morceaux de tissu ?', 'fabriqué avec soin à partir de plusieurs éléments assemblés', array['acheté directement dans un magasin spécialisé','emprunté temporairement à un autre enfant de l''atelier','dessiné simplement sur une feuille de papier']::text[], null, 27777, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27786, 'cm2', 'lecture', 'Que veut dire "dextérité" à propos de l''habileté nécessaire pour faire bouger correctement une marionnette à fils ?', 'une habileté manuelle précise acquise par la pratique', array['une force physique particulièrement importante','une connaissance théorique approfondie de la couture','une capacité à mémoriser de nombreuses informations']::text[], null, 27777, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27787, 'cm2', 'lecture', 'Que veut dire "improvisée" à propos de la petite scène installée pour le spectacle final de cet atelier ?', 'mise en place rapidement avec les moyens disponibles sur place', array['construite spécialement des mois à l''avance pour cet événement précis','identique à celle d''un véritable théâtre professionnel','installée habituellement en permanence dans cette salle du centre']::text[], null, 27777, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27788, 'cm2', 'lecture', 'Que veut dire "savoir-faire" à propos des compétences acquises par Simon durant cet atelier de fabrication de marionnettes ?', 'une compétence pratique acquise par l''expérience et l''entraînement', array['une simple connaissance théorique jamais mise en pratique','un diplôme officiel obtenu à la fin de l''atelier suivi','un objet matériel rapporte à la maison par Simon']::text[], null, 27777, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27789, 'cm2', 'lecture', 'Que veut dire "assistance" à propos des personnes réunies dans la salle pour regarder le spectacle final des enfants ?', 'l''ensemble des personnes présentes pour assister à un événement', array['l''aide matérielle apportée par l''animatrice aux enfants présents','le nom donne à la salle utilisée pour ce spectacle précis','un synonyme du mot marionnette utilise dans cette histoire']::text[], null, 27777, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27790, 'cm2', 'lecture', 'Pourquoi précisément Simon doit-il laisser sécher la tête en papier mâche de sa marionnette durant plusieurs jours avant de continuer ?', 'le papier mâche nécessite un temps de séchage naturel avant de pouvoir être manipule sans risque de l''abîmer', array['l''animatrice impose ce délai uniquement pour ralentir volontairement la progression des enfants','Simon préfère en réalité travailler sur d''autres activités en attendant sans raison particulière','le centre de loisirs manque de matériel disponible durant cette période précise de l''atelier']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27791, 'cm2', 'lecture', 'Pourquoi précisément Simon découvre-t-il que manipuler une marionnette à fils demande davantage de dextérité qu''il ne l''imaginait initialement ?', 'contrôler précisément plusieurs fils en même temps s''avère plus complexe en pratique qu''en apparence première', array['sa marionnette chevalier a été fabriquée de manière particulièrement défectueuse dès le départ','l''animatrice ne lui a en réalité donné aucune indication utile pour l''aider dans cette tache','il n''a en réalité jamais essaye sérieusement de faire fonctionner correctement sa propre marionnette']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27792, 'cm2', 'lecture', 'Pourquoi précisément Simon se sent-il un peu nerveux juste avant de monter sur la petite scène improvisée pour son spectacle ?', 'présenter son travail personnel devant un public réuni représente une situation nouvelle et impressionnante pour lui', array['il sait pertinemment que sa marionnette fonctionne particulièrement mal depuis le début','l''animatrice l''a averti d''une possible erreur technique pouvant survenir durant le spectacle','il n''a en réalité pas du tout envie de participer à ce spectacle final organisé']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27793, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que la démonstration réalisée par Simon devant le public rencontre un réel succès ce jour-là ?', 'les applaudissements enthousiastes de toute l''assistance présente saluent sa performance accomplie sur scène', array['Simon quitte précipitamment la scène avant même la fin de sa propre démonstration','l''animatrice doit intervenir directement pour corriger une erreur commise par Simon','le public présent reste totalement silencieux durant toute la démonstration réalisée']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27794, 'cm2', 'lecture', 'Que peut-on déduire de la fierté manifeste par Simon en ramenant sa marionnette chevalier à la maison à la fin de l''atelier ?', 'il valorise sincèrement le travail personnel accompli et le nouveau savoir-faire acquis durant ces vacances', array['il considère en réalité cette marionnette comme un simple objet sans grande valeur particulière','il regrette d''avoir participé à cet atelier plutôt qu''à une autre activité proposée durant les vacances','il prévoit déjà de se débarrasser rapidement de cette marionnette une fois rentre chez lui']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27795, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par l''animatrice tout au long de cet atelier de fabrication de marionnettes suivi par Simon ?', 'elle guide patiemment les enfants à travers chaque étape technique, favorisant ainsi leur progression et leur réussite', array['elle laisse les enfants totalement livres à eux-mêmes sans le moindre encadrement particulier','elle favorise ouvertement certains enfants participants au détriment des autres présents','elle se désintéresse rapidement du projet de Simon une fois celui-ci bien avance']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27796, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''évolution de Simon entre le tout début et la toute fin de cet atelier de plusieurs jours ?', 'il progresse véritablement, passant d''un simple débutant curieux à un jeune créateur capable de présenter fièrement son propre travail', array['il ne progresse finalement que très peu malgré le temps consacre à cette activité particulière','il perd progressivement tout intérêt pour cette activité au fil des différentes séances suivies','son niveau reste rigoureusement identique du début à la toute fin de cet atelier suivi']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27797, 'cm2', 'lecture', 'Que peut-on déduire du choix fait par Simon de fabriquer une nouvelle marionnette dès le prochain atelier propose ?', 'l''expérience vécue cette fois-ci lui a donné goût à cette pratique créative et il souhaite sincèrement la poursuivre', array['il pense en réalité avoir raté sa première marionnette et souhaite simplement recommencer','il n''a en réalité pas d''autre activité prévue durant les prochaines vacances scolaires','l''animatrice l''oblige explicitement à participer de nouveau à ce même atelier']::text[], null, 27777, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27799, 'cm2', 'lecture', 'Depuis quel moment précis de l''année Emma participe-t-elle à la chorale de son école ?', 'depuis la rentrée de septembre', array['depuis les vacances de printemps','depuis le tout début de l''année scolaire précédente','elle vient tout juste de s''inscrire cette semaine']::text[], null, 27798, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27800, 'cm2', 'lecture', 'À quel moment précis de la semaine se déroulent les répétitions de la chorale suivies par Emma ?', 'chaque mardi après-midi', array['chaque lundi matin','chaque vendredi soir','chaque samedi matin']::text[], null, 27798, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27801, 'cm2', 'lecture', 'Comment se nomme précisément le professeur de musique qui encadre la chorale à laquelle participe Emma ?', 'monsieur Rivet', array['madame Rivet','monsieur Dumont','madame Lenoir']::text[], null, 27798, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27802, 'cm2', 'lecture', 'Que se voit confier précisément Emma dans l''une des chansons prévues pour le spectacle de fin d''année ?', 'un petit passage en solo', array['la direction complète du choeur','le choix des costumes portes','l''écriture d''une nouvelle chanson']::text[], null, 27798, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27803, 'cm2', 'lecture', 'Où précisément Emma s''entraîne-t-elle chaque soir à répéter son passage en solo ?', 'devant le miroir de sa propre chambre', array['dans la salle de musique de l''école','chez sa meilleure amie','dans le jardin familial']::text[], null, 27798, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27804, 'cm2', 'lecture', 'Que ressent précisément Emma juste avant de monter sur scène le jour du spectacle final ?', 'un léger trac', array['une immense colère','une profonde tristesse','une totale indifférence']::text[], null, 27798, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27805, 'cm2', 'lecture', 'Que veut dire "inlassablement" à propos de la manière dont Emma répète chaque soir son passage en solo ?', 'sans jamais se lasser, de manière régulière et persévérante', array['de manière très brève et peu appliquée','seulement une fois, sans jamais recommencer','avec beaucoup de mauvaise volonté ressentie']::text[], null, 27798, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27806, 'cm2', 'lecture', 'Que veut dire "articuler" à propos du conseil donné par la maman d''Emma concernant sa manière de chanter ?', 'prononcer clairement chaque son pour être bien compris', array['chanter le plus fort possible sans nuance particulière','chanter très doucement presque à voix basse','répéter plusieurs fois la même parole chantée']::text[], null, 27798, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27807, 'cm2', 'lecture', 'Que veut dire "harmonies" à propos des voix superposées évoquées par monsieur Rivet lors d''une répétition ?', 'des combinaisons de sons qui s''accordent agréablement ensemble', array['des voix qui chantent toutes exactement la même note','des instruments de musique utilisés durant les répétitions','des costumes portés par les enfants lors du spectacle']::text[], null, 27798, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27808, 'cm2', 'lecture', 'Que veut dire "trac" à propos du ressenti d''Emma juste avant de monter sur la scène du spectacle final ?', 'une nervosité ressentie avant de se produire devant un public', array['une joie profonde ressentie avant un événement attendu','une totale indifférence face à la situation vécue','une grande fatigue physique ressentie ce jour précis']::text[], null, 27798, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27809, 'cm2', 'lecture', 'Que veut dire "hebdomadaire" à propos de l''activité de chorale à laquelle participe Emma depuis la rentrée ?', 'qui revient chaque semaine de manière régulière', array['qui n''a lieu qu''une seule fois par trimestre','qui se déroule uniquement pendant les vacances scolaires','qui se produit de manière totalement imprévisible']::text[], null, 27798, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27810, 'cm2', 'lecture', 'Que veut dire "placer sa voix" à propos de l''explication donnée par monsieur Rivet aux enfants de la chorale ?', 'utiliser correctement sa voix pour chanter sans se fatiguer la gorge', array['choisir l''endroit précis où se tenir durant une répétition','déposer un objet à un emplacement particulier de la salle','mémoriser précisément les paroles d''une chanson donnée']::text[], null, 27798, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27811, 'cm2', 'lecture', 'Pourquoi précisément monsieur Rivet explique-t-il patiemment aux enfants comment respirer correctement pour chanter ?', 'une bonne technique respiratoire évite de fatiguer inutilement la voix des jeunes choristes', array['il souhaite avant tout occuper le temps de répétition disponible chaque mardi','les parents des enfants exigent explicitement cet enseignement particulier','c''est une simple habitude sans réelle utilité pratique pour les enfants']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27812, 'cm2', 'lecture', 'Pourquoi précisément Emma s''entraîne-t-elle chaque soir chez elle en plus des répétitions organisées à l''école ?', 'elle souhaite sincèrement progresser et se sentir pleinement prête pour le jour du spectacle final', array['monsieur Rivet exige explicitement cet entraînement supplémentaire de chaque enfant','elle a en réalité peur de décevoir ses propres camarades de chorale','elle n''a en réalité rien d''autre à faire durant ses soirées libres']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27813, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément qu''Emma gagne progressivement en confiance au fil des semaines de répétition ?', 'elle parvient désormais à chanter son passage en solo sans la moindre hésitation devant ses camarades', array['elle refuse catégoriquement de chanter devant qui que ce soit avant le jour du spectacle','elle demande finalement à une autre enfant de la remplacer pour ce passage en solo','elle oublie régulièrement les paroles de son passage lors des répétitions suivantes']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27814, 'cm2', 'lecture', 'Pourquoi précisément Emma interroge-t-elle monsieur Rivet sur le principe des chansons chantées à plusieurs voix différentes ?', 'sa curiosité naturelle la pousse à mieux comprendre la construction musicale des chansons répétées ensemble', array['elle trouve que ces chansons à plusieurs voix sont bien trop difficiles à chanter correctement','monsieur Rivet l''oblige explicitement à poser cette question durant une répétition précise','elle cherche uniquement à faire durer davantage cette répétition particulière du mardi']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27815, 'cm2', 'lecture', 'Qu''est-ce qui permet précisément à Emma de réussir à chanter son passage en solo devant toutes les familles réunies malgré son trac ressenti ?', 'les nombreuses répétitions effectuées en amont lui donnent la confiance nécessaire pour surmonter sa nervosité du moment', array['monsieur Rivet chante en réalité à sa place durant le spectacle final organise','le public présent ne remarque en réalité pas sa présence sur la scène ce jour-là','elle décide finalement de ne pas chanter et reste silencieuse durant tout le spectacle']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27816, 'cm2', 'lecture', 'Que peut-on déduire du plaisir manifeste par Emma pour la chorale depuis le tout début de son inscription en septembre ?', 'cette activité correspond sincèrement à un talent et un goût naturel qu''elle découvre et cultive avec enthousiasme', array['elle participe uniquement pour faire plaisir à ses propres parents qui l''y ont inscrite','elle préférerait en réalité nettement pratiquer une autre activité extrascolaire différente','cette activité ne représente finalement rien de particulier à ses propres yeux']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27817, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par la maman d''Emma dans la progression de sa fille au sein de la chorale ?', 'elle soutient et encourage avec attention les efforts fournis par sa fille, contribuant ainsi à sa réussite', array['elle se montre en réalité plutôt indifférente aux progrès accomplis par sa propre fille','elle critique systématiquement chaque tentative réalisée par Emma à la maison','elle préférerait nettement qu''Emma abandonne cette activité de chorale suivie']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27818, 'cm2', 'lecture', 'Que peut-on déduire globalement de la décision d''Emma de continuer la chorale des la rentrée suivante ?', 'cette expérience très positive confirme durablement sa passion sincère pour le chant et la musique', array['elle continue uniquement par habitude sans réel enthousiasme personnel','elle espère surtout obtenir un nouveau passage en solo plus important encore','elle n''a en réalité pas d''autre activité extrascolaire disponible pour l''année suivante']::text[], null, 27798, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27820, 'cm2', 'lecture', 'Quel jour précis de la semaine se déroule cette grande journée sportive organisée par l''école de Nathan ?', 'un vendredi', array['un lundi','un mercredi','un jeudi']::text[], null, 27819, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27821, 'cm2', 'lecture', 'Dans quelle équipe précisément Nathan se retrouve-t-il pour cette journée sportive organisée par son école ?', 'l''équipe verte', array['l''équipe rouge','l''équipe bleue','l''équipe jaune']::text[], null, 27819, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27822, 'cm2', 'lecture', 'En quoi consiste précisément la toute première épreuve de cette journée sportive vécue par Nathan ?', 'une course de relais', array['un match de football','un concours de saut en hauteur','une course d''orientation dans le parc']::text[], null, 27819, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27823, 'cm2', 'lecture', 'Quelle responsabilité précise se voit confier Nathan durant cette course de relais organisée ?', 'le tout dernier relais de son équipe', array['le tout premier relais de son équipe','le rôle d''arbitre de la course','le comptage des points de son équipe']::text[], null, 27819, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27824, 'cm2', 'lecture', 'Quelles autres épreuves précises s''enchaînent tout au long de cette journée sportive après la course de relais ?', 'un lancer de ballon, un parcours d''équilibre et un saut en longueur', array['une course à pied et un concours de dessin','un match de basketball et une épreuve de natation','un quiz de culture générale et une épreuve de chant']::text[], null, 27819, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27825, 'cm2', 'lecture', 'À quelle place précise termine finalement l''équipe verte de Nathan au classement général de cette journée sportive ?', 'à la deuxième place', array['à la toute première place','à la toute dernière place','l''équipe n''est finalement pas classée']::text[], null, 27819, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27826, 'cm2', 'lecture', 'Que veut dire "distincte" à propos de la couleur portée par chaque équipe lors de cette journée sportive organisée ?', 'différente et particulière à chaque équipe concernée', array['identique pour toutes les équipes participantes','choisie au hasard juste avant chaque épreuve','attribuée uniquement aux membres les plus rapides']::text[], null, 27819, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27827, 'cm2', 'lecture', 'Que veut dire "appréhension" à propos du ressenti de Nathan juste avant de recevoir le bâton du relais final ?', 'une légère inquiétude ressentie face à une situation importante', array['une joie profonde et particulièrement intense ressentie','une totale indifférence face à la situation vécue','une immense fatigue physique déjà ressentie']::text[], null, 27819, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27828, 'cm2', 'lecture', 'Que veut dire "s''enchaînent" à propos des différentes épreuves qui se succèdent tout au long de cette journée sportive ?', 'se suivent les unes après les autres sans interruption notable', array['se déroulent toutes exactement au même moment précis','sont annulées les unes après les autres durant la journée','sont organisées uniquement le matin de cette journée']::text[], null, 27819, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27829, 'cm2', 'lecture', 'Que veut dire "solennellement" à propos de la manière dont les professeurs annoncent les résultats finaux de cette journée ?', 'avec une certaine gravite et un sérieux particulier', array['de manière très désinvolte et peu sérieuse','en chuchotant discrètement à chaque élève concerne','en riant beaucoup durant toute l''annonce des résultats']::text[], null, 27819, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27830, 'cm2', 'lecture', 'Que veut dire "exigeante" à propos de l''épreuve de saut en longueur mentionnée parmi les différentes épreuves de la journée ?', 'qui demande beaucoup d''efforts et de capacités physiques', array['très facile à réaliser sans effort particulier','de très courte durée seulement','sans aucun intérêt particulier pour les élèves']::text[], null, 27819, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27831, 'cm2', 'lecture', 'Que veut dire "esprit d''équipe" à propos de ce que Nathan retient finalement comme le plus important de cette journée sportive vécue ?', 'la solidarité et la coopération ressenties entre les membres d''un même groupe', array['la volonté individuelle de gagner à tout prix une compétition','le simple fait de porter la même couleur qu''un camarade','la rapidité personnelle d''un coureur lors d''une épreuve donnée']::text[], null, 27819, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27832, 'cm2', 'lecture', 'Pourquoi précisément Nathan accepte-t-il la responsabilité du tout dernier relais malgré l''impression ressentie face à cette tache ?', 'sa détermination et sa confiance en ses propres capacités l''emportent finalement sur son impression initiale ressentie', array['ses camarades d''équipe l''obligent explicitement à accepter cette responsabilité particulière','aucun autre élève de son équipe n''est disponible pour assurer ce dernier relais précis','il espère uniquement impressionner ses propres parents présents ce jour-là']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27833, 'cm2', 'lecture', 'Pourquoi précisément les cris enthousiastes de son équipe encouragent-ils autant Nathan durant sa course de relais final ?', 'le soutien collectif ressenti lui donne une motivation supplémentaire pour donner le meilleur de lui-même', array['il a en réalité besoin de ces encouragements pour ne pas se perdre sur le terrain de sport','ses camarades espèrent ainsi le distraire volontairement de la course qu''il doit courir','il n''entend en réalité pas du tout ces encouragements durant sa propre course']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27834, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément l''engagement sincère de Nathan tout au long de cette journée sportive malgré la fatigue ressentie ?', 'il continue de participer activement à chaque épreuve et d''encourager ses camarades malgré son épuisement progressif', array['il abandonne finalement plusieurs épreuves en cours de journée par manque de motivation personnelle','il se contente uniquement d''observer les autres élèves participer aux différentes épreuves organisées','il quitte précipitamment la journée sportive avant même l''annonce des résultats finaux']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27835, 'cm2', 'lecture', 'Pourquoi précisément l''équipe verte de Nathan ressent-elle une immense joie collective après avoir remporté la course de relais ?', 'cette victoire récompense les efforts individuels et collectifs fournis par chaque membre de l''équipe durant cette épreuve', array['ils ne s''attendaient en réalité pas du tout à remporter cette première épreuve de la journée','les autres équipes participantes abandonnent finalement volontairement cette course de relais','cette victoire leur assure automatiquement la toute première place du classement général final']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27836, 'cm2', 'lecture', 'Que peut-on déduire de l''attitude de Nathan envers ses camarades lors des épreuves suivantes de cette journée sportive ?', 'il fait preuve d''un véritable esprit d''équipe en encourageant sincèrement chacun malgré sa propre fatigué ressentie', array['il se désintéresse rapidement des épreuves suivantes une fois son propre relais termine','il critique ouvertement les performances réalisées par ses camarades d''équipe présents','il préférerait nettement participer seul plutôt qu''en équipe à cette journée sportive']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27837, 'cm2', 'lecture', 'Que peut-on déduire de la réaction de Nathan face à la deuxième place finalement obtenue par son équipe au classement général ?', 'il relativisé sainement l''importance du classement final au profit de l''expérience collective vécue ensemble', array['il ressent une profonde déception qui gâche entièrement son souvenir de cette journée sportive','il accuse injustement ses propres camarades d''être responsables de cette deuxième place obtenue','il refuse catégoriquement de reconnaître les efforts fournis par les autres équipes participantes']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27838, 'cm2', 'lecture', 'Que peut-on déduire globalement du message que Nathan souhaite transmettre à ses parents en rentrant chez lui ce soir-là ?', 'la valeur du partage et de la cohésion d''équipe compte davantage à ses yeux qu''une simple victoire individuelle', array['il souhaite uniquement se plaindre du résultat final obtenu par son équipe ce jour-là','il cherche surtout à minimiser ses propres efforts fournis durant cette journée sportive','il n''accorde en réalité aucune importance particulière à cette journée sportive vécue']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27839, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par les professeurs organisateurs dans la réussite globale de cette journée sportive scolaire ?', 'ils mettent en place un cadre stimulant et varie qui favorise à la fois l''effort physique et la cohésion entre élèves', array['ils se contentent simplement de surveiller les élèves sans réel investissement personnel','ils favorisent ouvertement certaines équipes participantes au détriment des autres élèves','ils n''interviennent en réalité à aucun moment durant le déroulement de cette journée sportive']::text[], null, 27819, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27841, 'cm2', 'lecture', 'À quelle discipline sportive précise Sara s''inscrit-elle cette année dans un nouveau club de sa ville ?', 'le parcours d''obstacles', array['la natation synchronisée','la gymnastique rythmique','l''escalade en salle']::text[], null, 27840, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27842, 'cm2', 'lecture', 'Que fait précisément l''entraîneur des la toute première séance suivie par Sara dans ce nouveau club ?', 'il explique les règles essentielles de sécurité à respecter', array['il organise directement une première compétition','il laisse les enfants s''entraîner entièrement seuls','il présente uniquement le matériel disponible dans le club']::text[], null, 27840, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27843, 'cm2', 'lecture', 'Quels obstacles précis composent le parcours découvert par Sara lors de cette première séance ?', 'des murs, des filets et des poutres d''équilibre', array['des piscines et des toboggans aquatiques','des tapis de course et des vélos d''appartement','des cerceaux et des ballons de sport varies']::text[], null, 27840, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27844, 'cm2', 'lecture', 'Quel obstacle précis Sara redoute-t-elle le plus parmi tous ceux composant ce parcours d''obstacles ?', 'la poutre d''équilibre étroite', array['le premier mur à escalader','le grand filet suspendu','aucun obstacle particulier ne l''inquiète réellement']::text[], null, 27840, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27845, 'cm2', 'lecture', 'Comment réagit précisément le groupe présent lorsque Sara parvient enfin à traverser la poutre d''équilibre délicate ?', 'il applaudit chaleureusement', array['il reste totalement silencieux','il quitte immédiatement la salle','il se moque gentiment de Sara']::text[], null, 27840, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27846, 'cm2', 'lecture', 'À quoi participe finalement Sara après plusieurs mois de pratique régulière et assidue dans ce club sportif ?', 'sa toute première compétition officielle', array['un simple entraînement supplémentaire','une démonstration télévisée nationale','l''organisation d''un nouveau club sportif']::text[], null, 27840, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27847, 'cm2', 'lecture', 'Que veut dire "intimidée" à propos du ressenti de Sara face à la hauteur du premier mur à escalader ?', 'impressionnée et légèrement inquiété face à un défi', array['totalement indifférente face à la situation rencontrée','particulièrement enthousiaste sans la moindre crainte','profondément ennuyée par cet obstacle propose']::text[], null, 27840, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27848, 'cm2', 'lecture', 'Que veut dire "infructueuses" à propos des premières tentatives réalisées par Sara sur la poutre d''équilibre ?', 'qui n''aboutissent pas au résultat espère', array['qui réussissent parfaitement dès le premier essai','qui sont interdites par le règlement du club','qui sont réalisées par un autre enfant du groupe']::text[], null, 27840, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27849, 'cm2', 'lecture', 'Que veut dire "assidue" à propos de la pratique régulière de Sara au sein de ce club de parcours d''obstacles ?', 'appliquée et constante dans le temps', array['très occasionnelle et peu suivie dans la durée','réalisée uniquement durant les vacances scolaires','abandonnée puis reprise à plusieurs reprises différentes']::text[], null, 27840, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27850, 'cm2', 'lecture', 'Que veut dire "coordination" à propos de la qualité nécessaire pour franchir le grand filet suspendu ?', 'la capacité à faire travailler ensemble plusieurs parties du corps', array['la capacité à mémoriser rapidement de nombreuses informations','la capacité à courir très vite sur une longue distance','la capacité à rester immobile durant une longue période']::text[], null, 27840, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27851, 'cm2', 'lecture', 'Que veut dire "modules" à propos des différents éléments composant le parcours d''obstacles découvert par Sara ?', 'les différents éléments ou structures composant un ensemble', array['les différents entraîneurs présents dans le club sportif','les différents horaires proposés pour les séances','les différents enfants inscrits dans ce club sportif']::text[], null, 27840, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27852, 'cm2', 'lecture', 'Que veut dire "sans gravite" à propos des chutes subies par Sara lors de ses premières tentatives sur la poutre d''équilibre ?', 'sans conséquence sérieuse ni blessure importante', array['particulièrement dangereuses et inquiétantes','provoquant une blessure grave nécessitant des soins','totalement évitées grâce à un équipement particulier']::text[], null, 27840, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27853, 'cm2', 'lecture', 'Pourquoi précisément l''entraîneur explique-t-il en détail les règles de sécurité des la toute première séance suivie par les enfants ?', 'la pratique de cette discipline exigeante nécessite une vigilance particulière pour éviter tout accident évitable', array['il souhaite avant tout impressionner les parents des enfants présents ce jour-là','le règlement officiel du club l''oblige à consacrer un temps minimal à cette explication','il n''a en réalité rien d''autre à proposer durant cette toute première séance']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27854, 'cm2', 'lecture', 'Pourquoi précisément Sara hésite-t-elle quelques instants avant de se lancer face au premier mur à escalader ?', 'la hauteur impressionnante de cet obstacle inconnu suscite chez elle une appréhension naturelle et compréhensible', array['elle a en réalité déjà tenté d''escalader ce mur à de nombreuses reprises auparavant','l''entraîneur lui interdit explicitement de commencer avant d''avoir reçu son accord','elle n''a en réalité aucune envie réelle de participer à cette activité proposée']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27855, 'cm2', 'lecture', 'Qu''est-ce qui permet précisément à Sara de réussir à escalader ce premier mur malgré son appréhension initiale ressentie ?', 'la technique précise enseignée par l''entraîneur associée à sa propre détermination personnelle lui permettent de réussir', array['un autre enfant du groupe escalade le mur à sa place à ce moment précis','l''entraîneur porte physiquement Sara jusqu''au sommet du mur concerne','elle abandonne finalement cette tentative sans jamais réussir à escalader ce mur']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27856, 'cm2', 'lecture', 'Pourquoi précisément la poutre d''équilibre représente-t-elle un défi particulièrement redoute par Sara parmi tous les obstacles rencontres ?', 'maintenir un équilibre parfait sur une surface étroite exige une maîtrise du corps plus délicate que les autres obstacles rencontres', array['cette poutre est en réalité bien plus haute que tous les autres obstacles proposés dans ce parcours','l''entraîneur ne fournit aucune explication utile concernant cet obstacle particulier','Sara à déjà subi une blessure sérieuse sur cette poutre lors d''une séance précédente']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27857, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément la persévérance de Sara face aux difficultés rencontrées sur la poutre d''équilibre étroite ?', 'malgré plusieurs chutes successives, elle continue de tenter jusqu''à parvenir finalement à traverser entièrement cet obstacle délicat', array['elle abandonne définitivement cet obstacle des la toute première tentative infructueuse réalisée','l''entraîneur doit la porter lui-même jusqu''à l''autre extrémité de cette poutre concernée','elle refuse catégoriquement de retenter cet obstacle lors des séances suivantes organisées']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27858, 'cm2', 'lecture', 'Que peut-on déduire de la réponse donnée par l''entraîneur concernant les qualités physiques développées par cette discipline particulière ?', 'cette activité complète favorise un développement physique équilibre grâce à la diversité des obstacles proposés', array['seule la force physique brute importe réellement dans la pratique de cette discipline sportive','cette discipline ne développe en réalité aucune qualité physique particulièrement utile','l''équilibre et la coordination ne jouent finalement aucun rôle dans cette pratique sportive']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27859, 'cm2', 'lecture', 'Que peut-on déduire de la réussite de Sara lors de sa toute première compétition officielle sans la moindre chute constatée ?', 'les mois de pratique régulière et assidue portent pleinement leurs fruits lors de cette première épreuve officielle', array['cette compétition officielle était en réalité beaucoup plus facile que les entraînements habituels suivis','Sara a simplement eu beaucoup de chance lors du déroulement de cette compétition particulière','les autres participants à cette compétition étaient en réalité moins bien prépares que Sara']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27860, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''évolution de Sara entre sa toute première séance hésitante et sa réussite lors de la compétition officielle ?', 'elle progresse véritablement grâce à sa persévérance, passant d''une débutante intimidée à une pratiquante confiante et compétente', array['elle ne progresse finalement que très peu malgré les nombreux mois de pratique consacres à cette discipline','son niveau reste rigoureusement identique entre le début et la fin de cette période de pratique régulière','elle perd progressivement tout intérêt pour cette discipline au fil des différentes séances suivies']::text[], null, 27840, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27862, 'cm2', 'lecture', 'À quel moment précis de l''année Adam se rend-il avec sa famille au grand parc aquatique évoque dans cette histoire ?', 'un samedi d''été', array['un dimanche d''hiver','un mercredi de printemps','un vendredi d''automne']::text[], null, 27861, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27863, 'cm2', 'lecture', 'Vers quelle attraction précise Adam et sa soeur se précipitent-ils dès leur arrivée au parc aquatique ?', 'le premier toboggan gigantesque aperçu', array['la piscine à vagues située plus loin','la rivière artificielle paisible','le restaurant du parc aquatique']::text[], null, 27861, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27864, 'cm2', 'lecture', 'Qui précisément rassure Adam juste avant qu''il ne se lance dans la descente de ce premier toboggan impressionnant ?', 'sa grande soeur', array['son papa','un maître-nageur du parc','personne, il se lance entièrement seul']::text[], null, 27861, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27865, 'cm2', 'lecture', 'Sur quoi précisément Adam se laisse-t-il flotter tranquillement sur la rivière artificielle du parc aquatique ?', 'une bouée gonflable colorée', array['un simple matelas de plage','une planche de bois flottante','il nage directement sans aucun support']::text[], null, 27861, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27866, 'cm2', 'lecture', 'Que découvre précisément Adam avec curiosité durant l''après-midi passe dans ce parc aquatique ?', 'une piscine à vagues particulièrement impressionnante', array['un nouveau toboggan encore plus haut','une cascade artificielle décorative','un bassin réserve aux tout petits enfants']::text[], null, 27861, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27867, 'cm2', 'lecture', 'Que fait précisément la famille d''Adam en milieu de journée durant cette sortie au parc aquatique ?', 'elle fait une pause pour déjeuner ensemble sur une terrasse ombragée', array['elle rentre directement à la maison pour se reposer','elle quitte définitivement le parc aquatique','elle assiste à un spectacle aquatique organisé']::text[], null, 27861, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27868, 'cm2', 'lecture', 'Que veut dire "vertigineuse" à propos de la hauteur du premier toboggan découvert par Adam à son arrivée ?', 'impressionnante au point de donner une sensation de vertige', array['particulièrement basse et peu impressionnante','identique à celle des autres toboggans du parc','totalement invisible depuis l''entrée du parc aquatique']::text[], null, 27861, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27869, 'cm2', 'lecture', 'Que veut dire "grisante" à propos de la sensation ressentie par Adam lors de sa toute première descente sur le toboggan ?', 'procurant une sensation d''excitation intense et grisante', array['particulièrement décevante par rapport à ses attentes','totalement neutre sans aucune émotion particulière ressentie','légèrement douloureuse au niveau du corps']::text[], null, 27861, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27870, 'cm2', 'lecture', 'Que veut dire "exaltante" à propos de l''expérience vécue par Adam en remontant immédiatement recommencer le toboggan ?', 'procurant un enthousiasme et une joie particulièrement intense', array['particulièrement ennuyeuse et répétitive à vivre','provoquant une fatigue excessive et désagréable','totalement banale et sans réel intérêt particulier']::text[], null, 27861, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27871, 'cm2', 'lecture', 'Que veut dire "aménagé" à propos du paysage observé par Adam tout autour de la rivière artificielle du parc aquatique ?', 'arrange et organise avec soin pour l''agrément des visiteurs', array['totalement naturel et laisse sans aucune intervention humaine','particulièrement dangereux et non sécurise pour les visiteurs','identique en tout point à un paysage de bord de mer naturel']::text[], null, 27861, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27872, 'cm2', 'lecture', 'Que veut dire "générées" à propos des vagues artificielles produites dans la piscine à vagues du parc aquatique ?', 'produites et créées grâce à un dispositif technique spécifique', array['totalement naturelles et indépendantes de toute intervention','observées uniquement lors de journées particulièrement venteuses','provoquées par le mouvement des nombreux visiteurs présents']::text[], null, 27861, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27873, 'cm2', 'lecture', 'Que veut dire "grandissant" à propos du plaisir ressenti par Adam au fil de ses descentes successives sur le toboggan ?', 'qui augmente progressivement avec le temps qui passe', array['qui diminue au contraire très rapidement','qui reste parfaitement stable sans jamais changer','qui disparaît complètement après la première descente']::text[], null, 27861, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27874, 'cm2', 'lecture', 'Pourquoi précisément Adam hésite-t-il quelques instants avant de se lancer dans la descente de ce premier toboggan impressionnant ?', 'la hauteur vertigineuse de cette attraction inconnue suscite chez lui une appréhension naturelle et compréhensible', array['il a en réalité déjà essayé ce même toboggan lors d''une précédente visite au parc aquatique','sa soeur aînée lui interdit explicitement de se lancer avant elle-même','il n''a en réalité aucune envie réelle de découvrir cette attraction particulière']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27875, 'cm2', 'lecture', 'Pourquoi précisément Adam remonte-t-il immédiatement les escaliers pour recommencer la descente de ce même toboggan ?', 'le plaisir intense ressenti lors de la première descente lui donne envie de renouveler immédiatement cette expérience', array['ses parents l''obligent explicitement à recommencer cette descente une seconde fois','il pense avoir raté sa première descente et souhaite simplement recommencer correctement','il n''a en réalité rien d''autre à faire en attendant que sa famille le rejoigne']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27876, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément qu''Adam apprécie particulièrement le moment de détente passe sur la rivière artificielle du parc ?', 'il profite pleinement du soleil et du paysage tout en se laissant flotter tranquillement sur sa bouée gonflable', array['il demande rapidement à quitter cette attraction pour retourner vers le toboggan initial','il s''ennuie visiblement durant tout le temps passe sur cette rivière artificielle paisible','il refuse catégoriquement de monter sur la bouée gonflable proposée par ses parents']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27877, 'cm2', 'lecture', 'Pourquoi précisément Adam interroge-t-il son papa sur le fonctionnement des vagues artificielles de la piscine à vagues ?', 'sa curiosité naturelle le pousse à mieux comprendre le fonctionnement technique de cette attraction impressionnante', array['il a en réalité peur de ces vagues artificielles et cherche à se rassurer davantage','son papa l''oblige explicitement à poser cette question particulière durant la journée','il cherche uniquement à faire durer davantage cette pause avant de retourner se baigner']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27878, 'cm2', 'lecture', 'Que peut-on déduire du moment de partage vécu par toute la famille lors de la pause déjeuner sur la terrasse ombragée du parc ?', 'ce moment convivial renforce la complicité familiale autour d''une expérience commune sincèrement appréciée de tous', array['cette pause déjeuner est vécue comme une contrainte plutôt que comme un moment de plaisir partage','les membres de la famille n''ont finalement pas grand-chose à se raconter durant cette pause','cette pause déjeuner gâche considérablement le plaisir ressenti durant le reste de la journée']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27879, 'cm2', 'lecture', 'Que peut-on déduire globalement du plaisir manifeste par Adam tout au long de cette journée passée au parc aquatique en famille ?', 'cette sortie constitue pour lui une expérience particulièrement enrichissante et mémorable partagée avec les siens', array['il s''ennuie en réalité profondément durant la plus grande partie de cette journée vécue au parc aquatique','il regrette d''avoir choisi ce parc aquatique plutôt qu''une autre destination pour cette sortie familiale','cette journée ne restera finalement qu''un souvenir très ordinaire et rapidement oublie par Adam']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27880, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par la famille d''Adam dans la réussite de cette journée passée ensemble au parc aquatique ?', 'leur présence et leur enthousiasme partage contribuent grandement au plaisir sincère ressenti par Adam ce jour-là', array['chaque membre de la famille reste isole de son côté sans réel partage durant cette journée vécue ensemble','les parents d''Adam se montrent en réalité plutôt indifférents aux attractions découvertes ce jour-là','cette sortie familiale crée davantage de tensions que de moments de plaisir sincèrement partages']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27881, 'cm2', 'lecture', 'Que peut-on déduire de l''affirmation faite par Adam en fin de journée selon laquelle cette sortie restera l''un des plus beaux souvenirs de son été ?', 'l''ensemble des expériences vécues ce jour-là, entre sensations fortes et moments de partage, a profondément marqué le jeune garçon', array['il exagère largement son propre ressenti simplement pour faire plaisir à ses parents présents','il compare cette journée à d''autres sorties bien plus impressionnantes vécues auparavant','cette affirmation ne reflète en réalité pas du tout son véritable ressenti sur cette journée']::text[], null, 27861, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27883, 'cm2', 'lecture', 'À quel moment précis de l''année Léna se rend-elle dans ce grand parc d''attractions avec sa famille ?', 'un dimanche de printemps', array['un samedi d''hiver','un vendredi d''automne','un mercredi d''été']::text[], null, 27882, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27884, 'cm2', 'lecture', 'Pourquoi précisément Léna attend-elle impatiemment cette sortie particulière au parc d''attractions ?', 'elle vient d''atteindre la taille minimale requise pour monter dans le grand huit', array['elle n''est en réalité jamais allée auparavant dans un parc d''attractions','ses parents lui ont promis un cadeau spécial à la fin de cette sortie','son grand frère célèbre son anniversaire ce jour-là précis']::text[], null, 27882, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27885, 'cm2', 'lecture', 'Qui précisément accompagne Léna et rassure ses craintes avant de monter dans le grand huit ?', 'son grand frère', array['sa maman','un employé du parc d''attractions','personne, elle monte entièrement seule']::text[], null, 27882, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27886, 'cm2', 'lecture', 'Que fait précisément Léna en faisant la queue devant l''entrée de cette attraction impressionnante ?', 'elle observe les autres visiteurs descendant du grand huit', array['elle révise mentalement le parcours complet du manège','elle demande à faire demi-tour et à quitter la file d''attente','elle discute tranquillement avec d''autres enfants présents']::text[], null, 27882, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27887, 'cm2', 'lecture', 'Que ressent précisément Léna durant la descente fulgurante suivant la toute première montée du grand huit ?', 'un cri mêlant à la fois la peur et une joie intense', array['une immense tristesse inattendue','une totale indifférence face à la situation vécue','un profond ennui durant toute la descente']::text[], null, 27882, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27888, 'cm2', 'lecture', 'Que demande immédiatement Léna à ses parents une fois descendue du grand huit à la fin du parcours ?', 'si elle peut remonter tout de suite dans cette attraction', array['de rentrer immédiatement à la maison','de ne plus jamais remonter dans une telle attraction','de lui acheter une glace pour se calmer']::text[], null, 27882, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27889, 'cm2', 'lecture', 'Que veut dire "vertigineux" à propos des rails du grand huit aperçus par Léna dès son arrivée dans le parc d''attractions ?', 'donnant une impression de hauteur et de vitesse impressionnantes', array['particulièrement bas et peu impressionnants à regarder','totalement immobiles et sans aucun mouvement particulier','recouverts entièrement de couleurs vives et joyeuses']::text[], null, 27882, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27890, 'cm2', 'lecture', 'Que veut dire "dévale" à propos du wagon du grand huit descendant soudainement la pente après la première montée ?', 'descend rapidement et avec une grande vitesse', array['s''arrête complètement au sommet de la montée','remonte immédiatement vers le sommet de la structure','avance très lentement tout au long du parcours']::text[], null, 27882, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27891, 'cm2', 'lecture', 'Que veut dire "fulgurante" à propos de la descente vécue par Léna juste après la première montée du grand huit ?', 'extrêmement rapide et intense', array['particulièrement lente et progressive','totalement immobile et sans mouvement','répétée plusieurs fois de suite durant le parcours']::text[], null, 27882, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27892, 'cm2', 'lecture', 'Que veut dire "radieux" à propos du visage de Léna en descendant finalement du wagon à la fin du parcours ?', 'rayonnant de joie et de satisfaction', array['marqué par une profonde tristesse','totalement inexpressif et neutre','recouvert d''une expression de colère visible']::text[], null, 27882, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27893, 'cm2', 'lecture', 'Que veut dire "inversée" à propos de la boucle traversée par le grand huit durant le parcours vécu par Léna ?', 'retournée, faisant passer les passagers la tête en bas', array['identique à toutes les autres parties du parcours','particulièrement lente comparée au reste du trajet','totalement invisible depuis l''extérieur de l''attraction']::text[], null, 27882, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27894, 'cm2', 'lecture', 'Que veut dire "inoubliable" à propos de l''expérience vécue par Léna lors de ce tout premier tour de grand huit ?', 'qui restera durablement grave dans la mémoire', array['facilement oubliée dès le lendemain de l''événement','identique à toutes les autres expériences déjà vécues','sans aucun intérêt particulier pour celle qui la vit']::text[], null, 27882, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27895, 'cm2', 'lecture', 'Pourquoi précisément le grand frère de Léna tente-t-il de la rassurer en lui expliquant calmement le parcours du grand huit ?', 'il souhaite l''aider à mieux appréhender une expérience nouvelle et impressionnante pour elle', array['il espère ainsi impressionner leurs propres parents présents ce jour-là','il doit obligatoirement fournir cette explication selon le règlement du parc','il n''a en réalité rien d''autre à faire en attendant que la file d''attente avance']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27896, 'cm2', 'lecture', 'Pourquoi précisément Léna observe-t-elle attentivement les visages des visiteurs descendant du grand huit avant de monter elle-même ?', 'elle cherche à se faire une idée plus précise de ce qui l''attend afin de mieux se préparer mentalement', array['elle connaît personnellement certains de ces visiteurs et souhaite les saluer','elle espère ainsi convaincre ses parents de renoncer finalement à cette attraction','elle n''a en réalité aucune autre occupation possible durant cette longue attente']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27897, 'cm2', 'lecture', 'Pourquoi précisément le coeur de Léna bat-il plus rapidement au moment où le grand huit commence son ascension vers le sommet ?', 'l''anticipation de la descente à venir et la nouveauté de cette expérience suscitent chez elle une tension naturelle', array['elle a en réalité peur que le wagon dans lequel elle se trouve tombe en panne durant l''ascension','son grand frère lui à volontairement raconte une histoire effrayante juste avant le départ du manège','elle regrette déjà d''avoir accepté de monter dans cette attraction impressionnante']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27898, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que l''expérience vécue par Léna dépasse largement ses craintes initiales ressenties avant de monter dans le grand huit ?', 'elle découvre avec surprise un plaisir inattendu au coeur même de la peur ressentie durant la descente', array['elle reste totalement indifférente du début à la fin du parcours effectué','elle pleure abondamment durant l''ensemble du trajet parcouru dans le grand huit','elle demande à arrêter immédiatement le manège des la toute première descente ressentie']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27899, 'cm2', 'lecture', 'Pourquoi précisément Léna demande-t-elle immédiatement à remonter dans le grand huit juste après en être descendue ?', 'l''enthousiasme et le plaisir intense ressentis durant ce premier tour lui donnent envie de renouveler immédiatement cette sensation', array['ses parents lui promettent une récompense si elle accepte de remonter une seconde fois','elle pense avoir manque une partie importante du parcours lors de ce premier tour effectuée','son grand frère l''oblige explicitement à remonter une seconde fois dans cette attraction']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27900, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par le grand frère de Léna tout au long de cette expérience vécue au parc d''attractions ?', 'il accompagne avec bienveillance et patience la découverte de sa petite soeur face à une expérience nouvelle pour elle', array['il se moque ouvertement des craintes exprimées par Léna avant de monter dans l''attraction','il laisse Léna affronter entièrement seule cette expérience sans lui apporter le moindre soutien','il préférerait nettement monter seul dans cette attraction plutôt qu''avec sa petite soeur']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27901, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''évolution du ressenti de Léna entre le début et la fin de cette expérience vécue dans le grand huit ?', 'elle passe d''une appréhension initiale compréhensible à un véritable enthousiasme durable pour ce type de sensation forte', array['son ressenti reste rigoureusement identique du début à la toute fin de cette expérience vécue','elle regrette profondément d''avoir accepté de monter dans cette attraction impressionnante','elle développe au contraire une peur durable de toute attraction sensationnelle à l''avenir']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27902, 'cm2', 'lecture', 'Que peut-on déduire de la déclaration finale de Léna affirmant que le grand huit devient sa toute nouvelle attraction préférée ?', 'cette expérience marquante transforme durablement sa perception des sensations fortes et enrichit ses goûts personnels', array['elle affirme simplement cela pour faire plaisir à son grand frère présent à ses côtés','elle exagère largement son propre ressenti sans réelle conviction personnelle sincère','elle changera probablement d''avis des la prochaine sortie effectuée dans un parc d''attractions']::text[], null, 27882, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27904, 'cm2', 'lecture', 'Quel âge précis à la petite cousine de Paul accompagnée à cette fête foraine ?', 'quatre ans', array['sept ans','dix ans','deux ans']::text[], null, 27903, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27905, 'cm2', 'lecture', 'Où précisément se déroule cette fête foraine que Paul et Zoé visitent ensemble chaque printemps ?', 'sur la grande place principale de leur ville', array['dans un parc situe en dehors de la ville','sur la plage proche de chez eux','dans la cour de l''école de Zoé']::text[], null, 27903, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27906, 'cm2', 'lecture', 'Sur quel manège précis Paul aide-t-il sa petite cousine à monter dès leur arrivée sur la place de la fête foraine ?', 'un manège enfantin avec des chevaux de bois', array['une grande roue panoramique','des autos tamponneuses colorées','un grand huit destine aux enfants']::text[], null, 27903, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27907, 'cm2', 'lecture', 'Que fait précisément Zoé durant tout le tour effectue sur le manège des petits chevaux de bois ?', 'elle agrippe les rênes en riant et salue Paul à chaque passage', array['elle reste totalement immobile sans dire un mot','elle pleure abondamment durant tout le tour effectué','elle demande immédiatement à descendre du manège']::text[], null, 27903, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27908, 'cm2', 'lecture', 'Quelle nouvelle attraction Zoé supplie-t-elle Paul de découvrir avec elle après ce premier tour de manège ?', 'un petit train enfantin parcourant la fête foraine', array['un second tour sur le même manège','un stand de tir à la fête foraine','une grande roue panoramique']::text[], null, 27903, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27909, 'cm2', 'lecture', 'Que partagent ensemble Paul et Zoé avec leurs parents en fin d''après-midi avant de quitter la fête foraine ?', 'une barbe à papa achetée à un stand', array['un repas complet dans un restaurant','une pomme d''amour partagée à plusieurs','rien du tout, ils rentrent directement chez eux']::text[], null, 27903, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27910, 'cm2', 'lecture', 'Que veut dire "entraînante" à propos de la musique diffusée par le manège des petits chevaux de bois ?', 'qui donne envie de bouger et procure de l''entrain', array['particulièrement triste et mélancolique à écouter','totalement silencieuse malgré les apparences','identique à celle diffusée par tous les autres manages présents']::text[], null, 27903, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27911, 'cm2', 'lecture', 'Que veut dire "communicatif" à propos de l''enthousiasme manifeste par Zoé durant le trajet effectue en petit train ?', 'qui se transmet facilement aux autres personnes présentes', array['qui reste totalement invisible aux yeux des autres','qui provoque au contraire une certaine gêne chez les autres','qui n''intéresse absolument personne d''autre que Zoé elle-même']::text[], null, 27903, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27912, 'cm2', 'lecture', 'Que veut dire "supplie" à propos de la demande formulée par Zoé pour que Paul l''accompagne vers une nouvelle attraction ?', 'demande avec une grande insistance et beaucoup d''enthousiasme', array['demande de manière très timide et hésitante','refuse catégoriquement toute nouvelle attraction proposée','oublie complètement sa demande initiale quelques instants plus tard']::text[], null, 27903, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27913, 'cm2', 'lecture', 'Que veut dire "agrippe" à propos de la manière dont Zoé tient les rênes de son cheval de bois durant le tour de manège ?', 'tient fermement avec ses deux mains', array['tient très mollement sans grande conviction','laisse totalement de côté sans y toucher','manipule très délicatement du bout des doigts']::text[], null, 27903, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27914, 'cm2', 'lecture', 'Que veut dire "panoramique" à propos de la grande roue mentionnée parmi les attractions présentes à cette fête foraine ?', 'offrant une vue dégagée et étendue sur les environs', array['particulièrement petite et peu impressionnante','réservée exclusivement aux adultes visiteurs présents','installée uniquement lors des fêtes foraines hivernales']::text[], null, 27903, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27915, 'cm2', 'lecture', 'Que veut dire "destine" à propos du petit train évoque comme étant spécifiquement conçu pour les plus jeunes visiteurs présents ?', 'conçu et prévu spécialement pour un usage ou un public particulier', array['totalement interdit à tous les visiteurs présents sur place','identique en tout point aux autres attractions de la fête foraine','installé uniquement de manière temporaire pour cette occasion précise']::text[], null, 27903, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27916, 'cm2', 'lecture', 'Pourquoi précisément Paul reste-t-il juste à côté de Zoé pendant tout le tour effectue sur le manège des chevaux de bois ?', 'il souhaite veiller sur sa petite cousine tout en partageant pleinement ce moment de plaisir avec elle', array['le règlement du manège exige obligatoirement la présence d''un accompagnateur adulte','il a en réalité peur que Zoé tombe de son cheval de bois durant le tour effectué','il n''a en réalité rien d''autre à faire en attendant que le tour de manège se termine']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27917, 'cm2', 'lecture', 'Pourquoi précisément Zoé salue-t-elle chaleureusement Paul à chaque passage devant lui durant son tour de manège ?', 'elle souhaite partager sa joie immédiate avec la personne qui compte pour elle et qui l''accompagne ce jour-là', array['elle a en réalité peur et cherche à se rassurer en vérifiant sa présence à chaque instant','Paul lui a explicitement demandé de le saluer à chaque passage devant lui','elle ne remarque en réalité pas vraiment la présence de Paul durant ce tour de manège']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27918, 'cm2', 'lecture', 'Pourquoi précisément Paul accepte-t-il avec plaisir d''accompagner Zoé sur cette nouvelle attraction du petit train malgré la fatigue possible ressentie ?', 'le bonheur manifeste par sa petite cousine lui procure lui-même une réelle satisfaction personnelle', array['il n''a en réalité pas d''autre attraction intéressante à découvrir de son propre côté','les parents de Zoé l''obligent explicitement à accompagner sa petite cousine partout','il espère ainsi recevoir une récompense de la part des parents de Zoé']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27919, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que Paul prend un plaisir sincère à expliquer le fonctionnement des manages à sa petite cousine curieuse ?', 'il découvre lui-même avec plaisir à quel point Zoé s''intéresse déjà aux mécanismes simples de ces attractions découvertes', array['il répond très brièvement aux questions posées par Zoé sans réel intérêt personnel','il refuse catégoriquement de répondre aux nombreuses questions posées par sa petite cousine','il demande à un employé de la fête foraine de répondre à sa place aux questions de Zoé']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27920, 'cm2', 'lecture', 'Que peut-on déduire de la relation entre Paul et sa petite cousine Zoé à travers cette après-midi partagée ensemble à la fête foraine ?', 'une complicité sincère et bienveillante unit le grand cousin et sa petite cousine au fil de cette expérience partagée', array['Paul se montre en réalité plutôt distant et peu implique dans les activités proposées à Zoé','Zoé préférerait nettement passer cette après-midi avec ses propres parents plutôt qu''avec Paul','cette sortie annuelle ne représente en réalité rien de particulier pour l''un comme pour l''autre']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27921, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par Paul en tant que grand cousin responsable tout au long de cette sortie à la fête foraine ?', 'il fait preuve d''attention et de patience en veillant au bien-être et au plaisir de sa jeune cousine tout au long de la sortie', array['il se contente simplement d''accompagner Zoé sans réel investissement personnel dans cette sortie','il préférerait nettement profiter seul des attractions plutôt que d''accompagner sa petite cousine','il néglige à plusieurs reprises la surveillance nécessaire de sa jeune cousine durant cette sortie']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27922, 'cm2', 'lecture', 'Que peut-on déduire globalement du souhait exprimé par Zoé de revenir à cette même fête foraine l''année suivante avec Paul ?', 'cette expérience partagée cette année laisse une empreinte durable et positive dans son jeune esprit', array['elle oubliera probablement cette sortie des la semaine suivante malgré son enthousiasme du moment','elle exprime ce souhait uniquement par politesse envers son grand cousin présent','elle préférerait en réalité découvrir une toute nouvelle fête foraine l''année suivante']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27923, 'cm2', 'lecture', 'Que peut-on déduire de la tradition annuelle établie entre Paul et Zoé autour de cette sortie à la fête foraine du printemps ?', 'cette sortie répétée chaque année renforce durablement le lien affectif particulier qui unit les deux cousins', array['cette tradition n''a en réalité plus grande importance ni pour l''un ni pour l''autre des deux cousins','Paul accompagne Zoé uniquement par obligation familiale sans réel plaisir personnel ressenti','cette sortie annuelle sera probablement abandonnée dès l''année suivante par les deux cousins']::text[], null, 27903, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27925, 'cm2', 'lecture', 'Quel jour précis de la semaine Iris se rend-elle chez ses grands-parents pour y passer sa toute première nuit seule ?', 'un vendredi soir', array['un lundi matin','un dimanche après-midi','un mercredi soir']::text[], null, 27924, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27926, 'cm2', 'lecture', 'Que prépare précisément la grand-mère d''Iris pour l''accueillir chaleureusement dès son arrivée ?', 'un goûter spécial avec des gâteaux maison et du chocolat chaud', array['un grand repas complet servi immédiatement','un simple verre d''eau pour se rafraîchir','rien de particulier, l''accueil se fait sans goûter']::text[], null, 27924, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27927, 'cm2', 'lecture', 'Que propose précisément le grand-père d''Iris après le goûter partage en début de soirée ?', 'de l''accompagner au jardin observer les premières étoiles', array['de regarder immédiatement un film ensemble','de partir directement se coucher très tôt','de préparer ensemble le repas du lendemain matin']::text[], null, 27924, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27928, 'cm2', 'lecture', 'Que regarde précisément toute la famille réunie ensemble après le dîner de ce vendredi soir particulier ?', 'un vieux film que le grand-père appréciait enfant', array['un match de football retransmis à la télévision','un documentaire sur les étoiles observées plus tôt','rien du tout, chacun se couche immédiatement']::text[], null, 27924, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27929, 'cm2', 'lecture', 'Que fait précisément la grand-mère d''Iris pour la rassurer au moment du coucher ce premier soir ?', 'elle lui raconte une histoire particulièrement apaisante', array['elle laisse une petite lumière allumée toute la nuit','elle reste assise à ses côtés jusqu''au petit matin','elle appelle immédiatement les parents d''Iris au téléphone']::text[], null, 27924, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27930, 'cm2', 'lecture', 'Comment se sent précisément Iris au réveil, le lendemain matin de cette première nuit passée chez ses grands-parents ?', 'particulièrement fière d''elle-même', array['profondément triste et déçue','totalement indifférente à cette expérience vécue','encore très inquiété et apeurée']::text[], null, 27924, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27931, 'cm2', 'lecture', 'Que veut dire "onctueux" à propos du chocolat chaud préparé par la grand-mère d''Iris pour le goûter d''accueil ?', 'd''une texture douce et particulièrement agréable en bouche', array['particulièrement froid et désagréable à boire','très amer et difficile à avaler facilement','prépare avec beaucoup trop de sucre ajoute']::text[], null, 27924, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27932, 'cm2', 'lecture', 'Que veut dire "transmise" à propos de l''ancienne recette familiale utilisée par la grand-mère d''Iris pour préparer le dîner ?', 'léguée et partagée d''une génération à l''autre au fil du temps', array['inventée tout récemment par la grand-mère elle-même','achetée directement dans un livre de cuisine spécialise','totalement oubliée et jamais réellement utilisée auparavant']::text[], null, 27924, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27933, 'cm2', 'lecture', 'Que veut dire "s''assombrit" à propos du ciel observé par Iris et son grand-père en cette soirée de printemps particulière ?', 'devient progressivement plus sombre à mesure que la nuit approche', array['devient au contraire de plus en plus clair et lumineux','reste parfaitement identique du début à la fin de la soirée','se recouvre entièrement de nuages épais et menaçants']::text[], null, 27924, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27934, 'cm2', 'lecture', 'Que veut dire "astronomie" à propos des notions simples expliquées par le grand-père d''Iris concernant les étoiles observées ?', 'la science qui étudie les astres et les phénomènes célestes', array['la technique particulière utilisée pour cultiver un jardin','un jeu traditionnel pratique en famille durant les soirées','une ancienne recette de cuisine transmise depuis longtemps']::text[], null, 27924, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27935, 'cm2', 'lecture', 'Que veut dire "apaisante" à propos de l''histoire racontée par la grand-mère d''Iris juste avant de dormir ce premier soir ?', 'qui procure calme et réconfort à celle qui l''écoute', array['particulièrement effrayante et inquiétante à écouter','totalement ennuyeuse et sans réel intérêt particulier','racontée de manière très brève et peu détaillée']::text[], null, 27924, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27936, 'cm2', 'lecture', 'Que veut dire "bercée" à propos du sentiment ressenti par Iris juste avant de s''endormir cette première nuit chez ses grands-parents ?', 'doucement enveloppée et apaisée par une sensation rassurante', array['brusquement réveillée par un bruit soudain inattendu','particulièrement effrayée par un événement précis vécu','empêchée complètement de trouver le sommeil recherche']::text[], null, 27924, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27937, 'cm2', 'lecture', 'Pourquoi précisément Iris ressent-elle un mélange d''excitation et d''appréhension avant cette toute première nuit passée chez ses grands-parents ?', 'cette expérience nouvelle et inconnue suscite chez elle à la fois de la curiosité et une légère inquiétude naturelle', array['elle a en réalité déjà vécu une mauvaise expérience lors d''une précédente visite chez ses grands-parents','ses parents lui ont explicitement raconté des histoires effrayantes concernant cette maison','elle n''a en réalité aucune envie réelle de rendre visite à ses propres grands-parents']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27938, 'cm2', 'lecture', 'Pourquoi précisément la grand-mère d''Iris prépare-t-elle un goûter spécial dès l''arrivée de sa petite-fille ce vendredi soir ?', 'elle souhaite marquer cette occasion particulière et mettre immédiatement Iris à l''aise dans cette nouvelle situation', array['elle n''a en réalité rien d''autre à proposer à Iris pour l''occuper ce vendredi soir précis','Iris exige explicitement ce goûter spécial avant même son arrivée chez ses grands-parents','c''est une habitude systématique sans réel lien avec cette première nuit particulière']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27939, 'cm2', 'lecture', 'Pourquoi précisément le grand-père d''Iris propose-t-il d''observer ensemble les étoiles plutôt qu''une autre activité ce vendredi soir ?', 'il souhaite partager avec sa petite-fille un moment privilégié autour d''une activité qui le passionne lui-même', array['il n''a en réalité rien d''autre à proposer à Iris durant cette soirée particulière','Iris exige explicitement cette activité avant toute autre chose ce soir-là','c''est la seule activité possible en l''absence d''électricité chez les grands-parents']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27940, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que la curiosité naturelle d''Iris se manifeste durant l''observation des étoiles avec son grand-père ?', 'elle pose de nombreuses questions sur ce qu''elle observe et découvre avec passion quelques notions simples d''astronomie', array['elle reste totalement silencieuse durant toute l''observation réalisée avec son grand-père','elle demande rapidement à rentrer à l''intérieur sans finir cette observation commencée','elle connaît déjà parfaitement toutes les réponses avant même de poser une question']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27941, 'cm2', 'lecture', 'Pourquoi précisément Iris ressent-elle une légère appréhension au moment de se coucher dans cette chambre inconnue ce premier soir ?', 'dormir dans un environnement nouveau et différent de sa propre chambre habituelle représente un changement notable pour elle', array['elle a entendu un bruit étrange provenant de cette chambre juste avant de s''y installer','sa grand-mère lui a raconté une histoire effrayante concernant cette chambre précise','elle regrette déjà d''avoir accepté de passer cette nuit chez ses propres grands-parents']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27942, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par les grands-parents d''Iris tout au long de cette première nuit passée loin de ses parents ?', 'ils offrent à leur petite-fille un cadre chaleureux et rassurant qui facilite grandement cette première expérience d''indépendance', array['ils se montrent en réalité plutôt indifférents au bien-être ressenti par leur petite-fille','ils laissent Iris totalement livrée à elle-même sans le moindre accompagnement particulier','ils regrettent d''avoir proposé à Iris de passer cette nuit chez eux sans ses propres parents']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27943, 'cm2', 'lecture', 'Que peut-on déduire de la fierté manifeste par Iris au réveil, le lendemain matin de cette première nuit vécue chez ses grands-parents ?', 'surmonter avec succès cette expérience nouvelle renforce durablement sa confiance en elle-même et son autonomie naissante', array['elle exagère largement son propre ressenti simplement pour faire plaisir à ses grands-parents','cette expérience ne représente finalement rien de particulier à ses propres yeux','elle préférerait en réalité ne jamais revivre une expérience similaire à l''avenir']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27944, 'cm2', 'lecture', 'Que peut-on déduire globalement du souhait exprimé par Iris de revenir très prochainement passer une nouvelle nuit chez ses grands-parents ?', 'cette première expérience très positive lui donne véritablement envie de renouveler ce moment de complicité partage', array['elle exprime ce souhait uniquement par politesse envers ses propres grands-parents','elle a en réalité déjà oublié l''appréhension ressentie avant cette première nuit vécue','elle préférerait en réalité passer davantage de temps avec ses propres parents plutôt']::text[], null, 27924, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27946, 'cm2', 'lecture', 'À quel moment précis de la semaine Milan rentre-t-il de ses grandes vacances d''été passées à la campagne ?', 'un dimanche soir', array['un lundi matin','un vendredi après-midi','un mercredi soir']::text[], null, 27945, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27947, 'cm2', 'lecture', 'Chez qui précisément Milan à-t-il passe ses deux mois de vacances d''été évoques dans cette histoire ?', 'chez ses grands-parents à la campagne', array['chez des amis de la famille','dans une colonie de vacances organisée','chez sa tante habitant en bord de mer']::text[], null, 27945, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27948, 'cm2', 'lecture', 'Que redécouvre précisément Milan en retrouvant sa propre chambre restée inchangée après son retour de vacances ?', 'plusieurs objets et jouets qu''il avait presque oublies', array['une chambre entièrement repeinte durant son absence','un nouveau lit installé pendant les vacances','rien de particulier, tout est resté absolument identique']::text[], null, 27945, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27949, 'cm2', 'lecture', 'Que demande précisément la maîtresse de Milan à toute la classe lors de la reprise scolaire du lendemain matin ?', 'de rédiger un texte sur le moment le plus marquant des vacances', array['de dessiner un souvenir précis de leurs propres vacances','de présenter oralement un objet rapporte de vacances','de choisir un livre à lire durant les vacances suivantes']::text[], null, 27945, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27950, 'cm2', 'lecture', 'Que choisit précisément Milan de raconter dans le texte rédige pour sa maîtresse d''école ?', 'le moment où il a aidé son grand-père à récolter les fruits du verger', array['une simple description de la maison de ses grands-parents','un jeu auquel il a joué avec des amis de vacances','une dispute survenue avec l''un de ses grands-parents']::text[], null, 27945, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27951, 'cm2', 'lecture', 'Que fait précisément Milan le soir de sa reprise scolaire concernant ses grands-parents restes à la campagne ?', 'il leur téléphone longuement pour leur raconter sa journée', array['il leur écrit une longue lettre manuscrite','il ne les contacte pas particulièrement ce soir-là','il prépare déjà sa prochaine visite chez eux']::text[], null, 27945, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27952, 'cm2', 'lecture', 'Que veut dire "repérés" à propos de ce que Milan retrouve avec impatience en rentrant chez lui après ces vacances estivales ?', 'les habitudes et le cadre familier de son quotidien habituel', array['des objets précis rapportes spécialement de ses vacances','des amis particuliers rencontres durant l''été passe','des lieux qu''il n''avait jamais visités auparavant']::text[], null, 27945, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27953, 'cm2', 'lecture', 'Que veut dire "savoureux" à propos des détails donnés par Milan en racontant la récolte des fruits avec son grand-père ?', 'particulièrement plaisants et intéressants à découvrir', array['très brefs et peu détaillés dans leur formulation','inventes de toutes pièces sans lien avec la réalité vécue','identiques à ceux donnés par tous les autres élèves de la classe']::text[], null, 27945, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27954, 'cm2', 'lecture', 'Que veut dire "autonomie" à propos de ce que Milan estime avoir gagné durant ses vacances passées chez ses grands-parents ?', 'la capacité à agir et à se débrouiller par soi-même', array['une connaissance approfondie de la vie à la campagne','une plus grande force physique acquise durant l''été','un plus grand nombre d''amis rencontres durant les vacances']::text[], null, 27945, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27955, 'cm2', 'lecture', 'Que veut dire "nostalgie" à propos du sentiment ressenti par Milan durant le trajet en voiture le ramenant chez lui ?', 'un doux regret mélancolique lie à des souvenirs passes', array['une joie intense sans la moindre once de tristesse','une colère ressentie sans raison particulière précise','une totale indifférence face aux souvenirs évoques']::text[], null, 27945, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27956, 'cm2', 'lecture', 'Que veut dire "marquant" à propos du moment que Milan doit choisir de raconter dans son texte rédige pour l''école ?', 'particulièrement important et qui laisse une impression durable', array['totalement banal et sans réel intérêt particulier','choisi entièrement au hasard sans réflexion préalable','identique au moment choisi par tous les autres élèves']::text[], null, 27945, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27957, 'cm2', 'lecture', 'Que veut dire "admiration" à propos de la réaction des amis de Milan en découvrant ses photographies de vacances ?', 'un sentiment d''estime et d''intérêt sincère pour ce qui est observé', array['une profonde indifférence face aux photographies montrées','une légère jalousie mêlée de rancoeur ressentie','un ennui manifeste rapidement exprimé par le groupe d''amis']::text[], null, 27945, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27958, 'cm2', 'lecture', 'Pourquoi précisément Milan ressent-il un mélange de nostalgie et d''impatience durant son trajet de retour vers la maison familiale ?', 'il quitte des souvenirs précieux tout en se réjouissant de retrouver son propre quotidien habituel', array['il regrette profondément d''avoir du quitter ses grands-parents sans aucune contrepartie positive','ses parents lui ont annoncé une mauvaise nouvelle durant ce trajet de retour effectué en voiture','il redoute particulièrement la reprise de l''école prévue dès le lendemain matin']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27959, 'cm2', 'lecture', 'Pourquoi précisément la maîtresse de Milan demande-t-elle à chaque élève de rédiger un texte sur ses vacances d''été ?', 'elle souhaite permettre à chaque élève de partager et de mettre en valeur une expérience personnelle vécue durant l''été', array['elle cherche uniquement à occuper la classe durant cette toute première journée de reprise scolaire','elle doit impérativement noter ce travail pour le bulletin scolaire de fin de trimestre','les parents des élèves exigent explicitement ce type d''exercice des la rentrée scolaire']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27960, 'cm2', 'lecture', 'Pourquoi précisément Milan choisit-il de raconter justement la récolte des fruits plutôt qu''un autre moment de ses vacances ?', 'cette expérience partagée avec son grand-père représente pour lui un souvenir particulièrement fort et significatif', array['c''est le seul moment dont il se souvient réellement parmi tous ceux vécus durant l''été','sa maîtresse lui impose explicitement ce sujet précis à développer dans son texte','il n''a en réalité rien d''autre d''intéressant à raconter concernant ses propres vacances']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27961, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que Milan à réellement gagne en maturité durant ses vacances passées auprès de ses grands-parents ?', 'il prend conscience lui-même, en rédigeant son texte, des progrès personnels accomplis durant cette période passée loin de ses parents', array['il refuse catégoriquement de reconnaître le moindre changement personnel survenu durant l''été','ses parents constatent eux-mêmes ce changement sans que Milan n''en soit lui-même conscient','sa maîtresse d''école lui fait remarquer ce changement au moment de corriger son texte rédige']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27962, 'cm2', 'lecture', 'Pourquoi précisément Milan téléphone-t-il longuement à ses grands-parents dès le soir de sa reprise scolaire ?', 'le lien affectif fort qui l''unit à eux le pousse naturellement à vouloir partager avec eux les événements de sa journée', array['ses parents l''obligent explicitement à téléphoner chaque soir à ses propres grands-parents','il a oublié un objet important chez ses grands-parents et doit le leur signaler rapidement','il souhaite uniquement se plaindre auprès d''eux de cette reprise scolaire difficile']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27963, 'cm2', 'lecture', 'Que peut-on déduire de la conclusion tirée par Milan à la toute fin de cette histoire concernant son propre retour à la maison familiale ?', 'il parvient à concilier les souvenirs précieux des vacances passées avec un bonheur sincère retrouve dans son quotidien habituel', array['il regrette profondément chaque instant passe loin de ses propres grands-parents durant l''année scolaire','il considère désormais son quotidien habituel comme moins intéressant que ses vacances passées','cette rentrée scolaire ne représente finalement rien de particulier à ses propres yeux']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27964, 'cm2', 'lecture', 'Que peut-on déduire globalement du rôle joue par les grands-parents de Milan dans son développement personnel à travers cette histoire racontée ?', 'ils contribuent de manière significative à son épanouissement personnel en lui offrant un cadre différent et enrichissant', array['ils n''ont finalement joue aucun rôle particulier significatif durant ces deux mois de vacances passées ensemble','Milan aurait vécu une expérience identique auprès de n''importe quelle autre personne de sa famille','leur influence sur Milan s''est en réalité avérée plutôt négative au cours de ces vacances passées']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27965, 'cm2', 'lecture', 'Que peut-on déduire de l''admiration manifestée par les amis de Milan en découvrant ses photographies de vacances durant la récréation ?', 'ses vacances à la campagne représentent à leurs yeux une expérience différente et enviable qu''ils écoutent avec un réel intérêt', array['ses amis se moquent en réalité discrètement de ses vacances passées à la campagne','ses amis ont eux-mêmes vécu des vacances bien plus impressionnantes que celles de Milan','cette admiration manifestée ne reflète en réalité aucun intérêt sincère de la part de ses amis']::text[], null, 27945, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27967, 'cm2', 'lecture', 'À quel moment précis de la semaine Selma visite-t-elle ce jardin des papillons avec sa classe entière ?', 'un mercredi après-midi', array['un lundi matin','un vendredi soir','un samedi après-midi']::text[], null, 27966, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27968, 'cm2', 'lecture', 'Où précisément Selma et ses camarades pénètrent-ils dès l''entrée de ce jardin des papillons visite ?', 'dans une grande serre chauffée remplie de papillons multicolores', array['dans un simple jardin extérieur aménagé','dans un musée consacre aux insectes','dans une salle de cinéma présentant un documentaire']::text[], null, 27966, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27969, 'cm2', 'lecture', 'Que fait précisément le guide dès le début de cette visite pour informer les enfants de la classe de Selma ?', 'il explique les différentes étapes de la métamorphose du papillon', array['il distribue à chaque enfant un petit papillon en plastique','il organise immédiatement un jeu de recherche dans la serre','il demande à chaque enfant de choisir son papillon préfère']::text[], null, 27966, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27970, 'cm2', 'lecture', 'Sur quoi précisément s''est posé le magnifique papillon bleu observé par Selma durant cette visite ?', 'une grande fleur tropicale', array['l''épaule de son camarade de classe','le bras du guide accompagnant la classe','une branche sèche située près de l''entrée']::text[], null, 27966, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27971, 'cm2', 'lecture', 'Qu''observe précisément le guide en invitant tous les enfants à s''approcher d''une branche particulière de la serre ?', 'une chrysalide accrochée délicatement à la branche', array['un nid d''oiseau construit récemment','une fleur particulièrement rare et précieuse','un papillon endormi sur cette même branche']::text[], null, 27966, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27972, 'cm2', 'lecture', 'Que fait précisément Selma une fois de retour à l''école après cette visite du jardin des papillons ?', 'elle dessine le papillon bleu qui s''est posé sur elle', array['elle écrit un long texte sur cette visite réalisée','elle montre des photographies prises durant la visite','elle ne fait rien de particulier concernant cette sortie']::text[], null, 27966, 'L', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27973, 'cm2', 'lecture', 'Que veut dire "chatoyantes" à propos des ailes du papillon bleu observé par Selma sur la grande fleur tropicale ?', 'brillantes et changeant légèrement de couleur selon la lumière', array['ternes et particulièrement peu visibles à l''oeil nu','identiques en tout point aux ailes de tous les autres papillons','totalement transparentes et difficiles à distinguer clairement']::text[], null, 27966, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27974, 'cm2', 'lecture', 'Que veut dire "camouflage" à propos de l''explication donnée par le guide concernant les papillons aux couleurs discrètes observées ?', 'une technique naturelle permettant de se fondre dans son environnement', array['une maladie particulière affectant certains papillons observés','une technique utilisée par les guides pour attirer les papillons','un phénomène qui rend certains papillons incapables de voler']::text[], null, 27966, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27975, 'cm2', 'lecture', 'Que veut dire "chrysalide" à propos de l''enveloppe protectrice observée par les enfants accrochée à une branche de la serre ?', 'l''enveloppe dans laquelle la chenille se transforme en papillon', array['le nom donne au tout premier oeuf pondu par un papillon adulte','une fleur particulière appréciée des papillons de cette serre','un autre nom donne simplement à l''aile d''un papillon adulte']::text[], null, 27966, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27976, 'cm2', 'lecture', 'Que veut dire "éclosion" à propos du moment attendu par Selma concernant le papillon en formation dans la chrysalide observée ?', 'le moment où un être vivant sort de son enveloppe protectrice', array['le moment où un papillon se pose sur une fleur précise','le moment où une fleur tropicale s''ouvre complètement','le moment où la serre chauffée ouvre ses portes au public']::text[], null, 27966, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27977, 'cm2', 'lecture', 'Que veut dire "instructive" à propos de la visite guidée vécue par Selma et ses camarades dans ce jardin des papillons ?', 'qui apporte des connaissances nouvelles et un enseignement utile', array['particulièrement ennuyeuse et dépourvue de réel intérêt','organisée dans la précipitation et sans réelle préparation','identique à une visite déjà réalisée l''année précédente']::text[], null, 27966, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27978, 'cm2', 'lecture', 'Que veut dire "métamorphose" à propos des différentes étapes expliquées par le guide concernant le développement du papillon ?', 'une transformation profonde de la forme d''un être vivant au cours de sa vie', array['un simple changement de couleur observe chez un papillon adulte','un déplacement effectué par un papillon d''une fleur à une autre','une maladie rare qui affecte parfois certains papillons observés']::text[], null, 27966, 'V', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27979, 'cm2', 'lecture', 'Pourquoi précisément le guide commence-t-il la visite en expliquant les étapes de la métamorphose du papillon aux enfants présents ?', 'cette explication préalable permet aux enfants de mieux comprendre et apprécier ce qu''ils vont ensuite observer dans la serre', array['il souhaite avant tout tester les connaissances scientifiques déjà acquises par les enfants de la classe','le programme scolaire impose formellement cette explication au tout début de chaque visite organisée','il n''a en réalité rien d''autre à proposer aux enfants durant les premières minutes de la visite']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27980, 'cm2', 'lecture', 'Pourquoi précisément Selma interroge-t-elle le guide sur les différences de couleurs observées entre les papillons de la serre ?', 'sa curiosité naturelle la pousse à mieux comprendre la diversité fascinante du monde observe autour d''elle', array['elle doute sérieusement de la véracité des explications données précédemment par le guide accompagnant la classe','le guide l''oblige explicitement à poser cette question particulière durant la visite organisée','elle cherche uniquement à faire durer davantage cette visite avant de retourner à l''école']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27981, 'cm2', 'lecture', 'Qu''est-ce qui montre précisément que Selma développe une réelle fascination pour le processus de transformation du papillon observe dans la chrysalide ?', 'elle imagine avec émerveillement le minuscule papillon en train de se former progressivement à l''intérieur de son enveloppe protectrice', array['elle se contente simplement d''observer la chrysalide sans manifester le moindre intérêt particulier','elle demande immédiatement à quitter cette partie de la visite pour observer autre chose','elle pense que cette chrysalide est en réalité totalement vide et inanimée']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27982, 'cm2', 'lecture', 'Pourquoi précisément Selma ressent-elle un mélange de surprise et de bonheur intense lorsqu''un papillon se pose sur son épaule ?', 'ce contact direct et inattendu avec un papillon vivant représente pour elle un moment magique et privilégié', array['elle a en réalité peur de ce papillon et cherche à le faire fuir rapidement','le guide lui avait promis à l''avance qu''un papillon viendrait se poser sur elle','elle pense qu''il s''agit en réalité d''un faux papillon place volontairement par le guide']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27983, 'cm2', 'lecture', 'Que peut-on déduire du rôle joue par le guide tout au long de cette visite du jardin des papillons vécue par la classe de Selma ?', 'il transmet avec passion et pédagogie des connaissances qui nourrissent durablement la curiosité naturelle des enfants présents', array['il se contente simplement de surveiller les enfants sans réel souci pédagogique particulier','il favorise ouvertement certains enfants de la classe au détriment des autres élèves présents','il n''apporte finalement aucune information particulièrement utile aux enfants durant cette visite']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27984, 'cm2', 'lecture', 'Que peut-on déduire globalement de l''effet produit par cette visite sur l''intérêt de Selma pour la nature et les insectes observés ?', 'cette expérience sensorielle et éducative renforce durablement sa curiosité et son émerveillement pour le monde naturel', array['cette visite la laisse totalement indifférente une fois revenue à son école habituelle','elle développe au contraire une certaine crainte des papillons suite à cette visite réalisée','cette sortie ne suscite chez elle qu''un intérêt très passager et rapidement oublie']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27985, 'cm2', 'lecture', 'Que peut-on déduire du souhait exprimé par Selma de revenir visiter ce jardin des papillons en compagnie de ses propres parents ?', 'elle souhaite sincèrement partager avec sa famille une expérience qu''elle a elle-même trouvée particulièrement enrichissante', array['elle exprime ce souhait uniquement par politesse envers son enseignante ayant organise cette sortie','elle a en réalité déjà oublié l''émerveillement ressenti durant cette visite réalisée avec sa classe','elle préférerait en réalité découvrir un tout autre lieu plutôt que de revenir dans ce même jardin']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (27986, 'cm2', 'lecture', 'Que peut-on déduire de l''application avec laquelle Selma dessine le papillon bleu une fois revenue à l''école après cette visite ?', 'elle cherche à conserver durablement le souvenir précis d''un moment qui l''a profondément marquée sur le plan personnel', array['elle doit obligatoirement rendre ce dessin note à sa maîtresse d''école dès le lendemain matin','elle a déjà oublié à quoi ressemblait précisément ce papillon dès sa sortie de la serre visitée','elle dessine ce papillon uniquement pour impressionner ses propres camarades de classe']::text[], null, 27966, 'I', 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (44000, 'cm2', 'logique', 'Quel nombre vient après ? 1, 1, 2, 3, 5, …', '8', array['7','9','6']::text[], null, null, null, 'publie');
