insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (44004, 'cm2', 'logique', 'Léo, Emma et Noah ont chacun un animal différent : chat, chien, poisson. Emma a un chat. Léo n''a pas de poisson. Qui a le poisson ?', 'Noah', array['Léo','Emma','Impossible à savoir']::text[], null, null, null, 'publie');
