insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (44207, 'cm2', 'logique', 'Chloé, Camille et Adam ont chacun un instrument différent : la guitare, le piano, la flûte. Chloé joue la guitare. Camille ne joue pas la flûte. Qui joue la flûte ?', 'Adam', array['Chloé','Camille','Impossible à savoir']::text[], null, null, null, 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (44208, 'cm2', 'logique', 'Emma, Manon et Léo ont chacun un animal différent : chien, chat, poisson. Emma a un chien. Manon n''a pas de poisson. Qui a le poisson ?', 'Léo', array['Emma','Manon','Impossible à savoir']::text[], null, null, null, 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (44209, 'cm2', 'logique', 'Zoé, Camille et Adam ont chacun un animal différent : chat, poisson, chien. Zoé a un chat. Camille n''a pas de chien. Qui a le chien ?', 'Adam', array['Zoé','Camille','Impossible à savoir']::text[], null, null, null, 'publie');
insert into contenu_questions (id, classe, matiere, enonce, bonne_reponse, mauvais_choix, grille, passage_id, type_lecture, statut) values (44210, 'cm2', 'logique', 'Adam, Lucas et Léo ont chacun un sport différent : la natation, le foot, le tennis. Adam pratique la natation. Lucas ne pratique pas le tennis. Qui pratique le tennis ?', 'Léo', array['Adam','Lucas','Impossible à savoir']::text[], null, null, null, 'publie');
